import { jsPDF } from "jspdf";
import { AIAnalysisResult } from "../types";

export const ExportService = {
  /**
   * Converts an array of objects to CSV and triggers a download.
   */
  exportToCSV: (data: any[], filename: string) => {
    if (!data || !data.length) return;

    // Get headers from the first object
    const headers = Object.keys(data[0]);

    const csvContent = [
      headers.join(','), // Header row
      ...data.map(row => headers.map(fieldName => {
        const value = row[fieldName];
        // Handle strings with commas, arrays, objects to prevent CSV breakage
        if (value === null || value === undefined) return '';
        if (typeof value === 'string' && value.includes(',')) return `"${value}"`;
        if (Array.isArray(value)) return `"${value.join(';')}"`;
        if (typeof value === 'object') return `"${JSON.stringify(value).replace(/"/g, '""')}"`;
        return value;
      }).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    if (link.download !== undefined) {
      const url = URL.createObjectURL(blob);
      link.setAttribute('href', url);
      link.setAttribute('download', filename);
      link.style.visibility = 'hidden';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    }
  },

  /**
   * Generates a PDF report including the analyzed image and AI results.
   */
  generateAnalysisPDF: (analysis: AIAnalysisResult, imageBase64: string, title: string) => {
    const doc = new jsPDF();
    const pageWidth = doc.internal.pageSize.getWidth();
    const pageHeight = doc.internal.pageSize.getHeight();
    const margin = 20;

    // Header / Title
    doc.setFontSize(22);
    doc.setTextColor(16, 185, 129); // Emerald-500
    doc.text("AgriVision AI Report", margin, margin);

    doc.setFontSize(14);
    doc.setTextColor(60, 60, 60);
    doc.text(title, margin, margin + 10);

    // Timestamp
    doc.setFontSize(10);
    doc.setTextColor(150, 150, 150);
    doc.text(`Generated: ${new Date().toLocaleString()}`, margin, margin + 16);

    let yPos = margin + 25;

    // Image Section
    if (imageBase64) {
      try {
        const imgProps = doc.getImageProperties(imageBase64);
        const imgWidth = pageWidth - (margin * 2);
        const imgHeight = (imgProps.height * imgWidth) / imgProps.width;

        // Ensure image doesn't take up too much space, cap height at 100
        const finalHeight = Math.min(imgHeight, 100);

        doc.addImage(imageBase64, 'JPEG', margin, yPos, imgWidth, finalHeight);
        yPos += finalHeight + 10;
      } catch (e) {
        console.error("Error adding image to PDF", e);
        doc.setFontSize(10);
        doc.text("[Image could not be processed]", margin, yPos);
        yPos += 10;
      }
    }

    // Analysis Results Section
    doc.setFillColor(241, 245, 249); // slate-100
    doc.rect(margin, yPos, pageWidth - (margin * 2), 25, 'F');

    doc.setFontSize(12);
    doc.setTextColor(0, 0, 0);
    doc.text(`Subject: ${analysis.detectedSubject}`, margin + 5, yPos + 8);
    doc.text(`Condition: ${analysis.condition}`, margin + 5, yPos + 16);

    // Confidence Score
    doc.text(`Confidence: ${analysis.confidence}%`, pageWidth - margin - 35, yPos + 12);

    yPos += 35;

    // Issues
    if (analysis.issues && analysis.issues.length > 0) {
      doc.setFontSize(14);
      doc.setTextColor(185, 28, 28); // red-700
      doc.text("Detected Issues:", margin, yPos);
      yPos += 8;

      doc.setFontSize(11);
      doc.setTextColor(40, 40, 40);
      analysis.issues.forEach(issue => {
        doc.text(`• ${issue}`, margin + 5, yPos);
        yPos += 6;
      });
      yPos += 5;
    }

    // Recommendations
    if (analysis.recommendations && analysis.recommendations.length > 0) {
      doc.setFontSize(14);
      doc.setTextColor(16, 185, 129); // emerald-600
      doc.text("AI Recommendations:", margin, yPos);
      yPos += 8;

      doc.setFontSize(11);
      doc.setTextColor(40, 40, 40);
      analysis.recommendations.forEach(rec => {
        // Handle text wrapping
        const lines = doc.splitTextToSize(`• ${rec}`, pageWidth - (margin * 2) - 5);
        doc.text(lines, margin + 5, yPos);
        yPos += (lines.length * 6);
      });
    }

    // Footer
    doc.setFontSize(8);
    doc.setTextColor(200, 200, 200);
    doc.text("AgriVision AI Platform - Automated Analysis Report", margin, pageHeight - 10);

    doc.save(`AgriVision_Report_${Date.now()}.pdf`);
  }
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { 
  Upload, 
  Scan, 
  Droplets, 
  CheckCircle,
  FileText,
  Sprout,
  Loader2,
  Download,
  Settings,
  Map,
  Layers,
  ThermometerSun,
  Eye,
  Maximize2,
  Palette
} from 'lucide-react';
import { MOCK_CROPS } from '../constants';
import { CropData, HealthStatus, AIAnalysisResult } from '../types';
import { analyzeCropImage } from '../services/geminiService';
import { ApiService } from '../services/api';
import { dbService } from '../services/db';
import { ExportService } from '../services/exportService';
import { ResponsiveContainer, LineChart, Line, CartesianGrid, XAxis, YAxis, Tooltip, ReferenceLine } from 'recharts';

type OverlayType = 'NONE' | 'NDVI' | 'THERMAL';
type NdviColorScheme = 'RG' | 'SPECTRAL' | 'DIVERGING';

export const CropDashboard: React.FC = () => {
  const [selectedCrop, setSelectedCrop] = useState<CropData | null>(null);
  const [crops, setCrops] = useState<CropData[]>(MOCK_CROPS);

  // Single Plant/Leaf Analysis State
  const [analysisImage, setAnalysisImage] = useState<string | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [analysisResult, setAnalysisResult] = useState<AIAnalysisResult | null>(null);

  // Map / Drone State
  const [mapImage, setMapImage] = useState<string>("https://images.unsplash.com/photo-1500382017468-9049fed747ef?ixlib=rb-4.0.3&auto=format&fit=crop&w=1600&q=80"); // Default placeholder
  const [overlayType, setOverlayType] = useState<OverlayType>('NONE');
  const [overlayOpacity, setOverlayOpacity] = useState(0.7);
  const [ndviColorScheme, setNdviColorScheme] = useState<NdviColorScheme>('RG');
  const mapInputRef = useRef<HTMLInputElement>(null);

  // NDVI Configuration State
  const [warningThreshold, setWarningThreshold] = useState(0.4);
  const [healthyThreshold, setHealthyThreshold] = useState(0.7);

  // Chart Interaction State
  const [draggingThreshold, setDraggingThreshold] = useState<'healthy' | 'warning' | null>(null);
  const chartContainerRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Load saved map from DB on mount
  useEffect(() => {
    const loadSavedMap = async () => {
        try {
            const saved = await dbService.getUpload('current-drone-map');
            if (saved) {
                setMapImage(saved.dataUrl);
            }
        } catch (e) {
            console.error("Failed to load saved map", e);
        }
    };
    loadSavedMap();
  }, []);

  useEffect(() => {
    // Poll for live crop data
    const interval = setInterval(async () => {
      const data = await ApiService.getCrops();
      setCrops(data);
      // Update selected crop if it exists in the new data
      if (selectedCrop) {
        const updated = data.find(c => c.id === selectedCrop.id);
        if (updated) setSelectedCrop(updated);
      }
    }, 5000);
    return () => clearInterval(interval);
  }, [selectedCrop]);

  // Handle Dragging Logic for Chart Thresholds
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!draggingThreshold || !chartContainerRef.current) return;

      const rect = chartContainerRef.current.getBoundingClientRect();
      const marginTop = 20;
      const marginBottom = 30;
      const chartHeight = rect.height - marginTop - marginBottom;

      const relativeY = e.clientY - rect.top - marginTop;
      let newValue = 1 - (relativeY / chartHeight);

      newValue = Math.max(0, Math.min(1, newValue));
      newValue = Math.round(newValue * 100) / 100;

      if (draggingThreshold === 'healthy') {
        if (newValue > warningThreshold) setHealthyThreshold(newValue);
      } else {
        if (newValue < healthyThreshold) setWarningThreshold(newValue);
      }
    };

    const handleMouseUp = () => {
      setDraggingThreshold(null);
    };

    if (draggingThreshold) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      document.body.style.userSelect = 'none';
    }

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
      document.body.style.userSelect = '';
    };
  }, [draggingThreshold, warningThreshold, healthyThreshold]);

  // Derived state: Apply threshold logic to crops dynamically
  const displayedCrops = useMemo(() => {
    return crops.map(crop => {
        let dynamicStatus = HealthStatus.CRITICAL;
        if (crop.ndvi >= healthyThreshold) {
            dynamicStatus = HealthStatus.HEALTHY;
        } else if (crop.ndvi >= warningThreshold) {
            dynamicStatus = HealthStatus.WARNING;
        }
        return { ...crop, status: dynamicStatus };
    });
  }, [crops, warningThreshold, healthyThreshold]);

  // Image Upload Handlers
  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const result = reader.result as string;
        setAnalysisImage(result);
        setAnalysisResult(null); 
        // Save to DB
        await ApiService.saveImage(`analysis-${Date.now()}`, 'CROP', result);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleMapUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const result = reader.result as string;
        setMapImage(result);
        // Save to DB with a fixed ID so it persists as the current map
        await ApiService.saveImage('current-drone-map', 'MAP', result);
      };
      reader.readAsDataURL(file);
    }
  };

  const triggerUpload = () => fileInputRef.current?.click();
  const triggerMapUpload = () => mapInputRef.current?.click();

  const runAnalysis = async () => {
    if (!analysisImage) return;
    setAnalyzing(true);
    const result = await analyzeCropImage(analysisImage.split(',')[1]);
    setAnalysisResult(result);
    setAnalyzing(false);
  };

  const handleExportData = () => {
    const dataToExport = displayedCrops.map(c => ({
        ID: c.fieldId,
        Name: c.name,
        Type: c.type,
        NDVI: c.ndvi,
        Moisture: c.soilMoisture,
        Status: c.status,
        Alerts: c.alerts.join('; ')
    }));
    ExportService.exportToCSV(dataToExport, 'my_field_data.csv');
  };

  const handleDownloadPDF = () => {
    if (analysisResult && analysisImage) {
        ExportService.generateAnalysisPDF(analysisResult, analysisImage, `Crop Analysis: ${analysisResult.detectedSubject}`);
    }
  };

  // Helper to get colors for NDVI overlay
  const getNdviColors = (scheme: NdviColorScheme) => {
    switch(scheme) {
        case 'SPECTRAL': 
            return { 
                low: '#d946ef', // Fuchsia
                mid: '#f43f5e', // Rose
                high: '#3b82f6', // Blue
                bg: '#3b82f6',
                gradient: 'from-fuchsia-500 via-rose-500 to-blue-500',
                labels: ['Dense/Wet', 'Stress', 'Healthy']
            };
        case 'DIVERGING': 
            return { 
                low: '#b91c1c', // Dark Red
                mid: '#f3f4f6', // Gray/White
                high: '#15803d', // Dark Green
                bg: '#15803d',
                gradient: 'from-red-700 via-gray-100 to-green-700',
                labels: ['Dead/Soil', 'Mix', 'Lush']
            };
        case 'RG': 
        default: 
            return { 
                low: '#ef4444', // Red
                mid: '#eab308', // Yellow
                high: '#22c55e', // Green
                bg: '#22c55e',
                gradient: 'from-red-500 via-yellow-400 to-green-500',
                labels: ['Critical', 'Warning', 'Healthy']
            };
    }
  };

  const ndviColors = getNdviColors(ndviColorScheme);

  const growthData = [
    { name: 'Week 1', ndvi: 0.2 },
    { name: 'Week 2', ndvi: 0.35 },
    { name: 'Week 3', ndvi: 0.5 },
    { name: 'Week 4', ndvi: 0.65 },
    { name: 'Week 5', ndvi: 0.78 },
    { name: 'Week 6', ndvi: 0.82 },
  ];

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Crop Monitoring</h1>
          <p className="text-slate-500">Real-time surveillance & vegetation analytics</p>
        </div>
        <div className="flex space-x-3 mt-4 md:mt-0">
            <button 
                onClick={handleExportData}
                className="flex items-center space-x-2 px-4 py-2 bg-white border border-slate-300 rounded-lg text-sm font-medium hover:bg-slate-50 transition-colors"
            >
                <FileText size={16} />
                <span>Export Data (CSV)</span>
            </button>
        </div>
      </div>

      {/* DRONE MAP & HEATMAP ANALYSIS */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="p-4 border-b border-slate-100 flex flex-col md:flex-row justify-between items-center gap-4">
            <div className="flex items-center gap-2">
                <Map className="text-indigo-600" size={20} />
                <h3 className="font-semibold text-slate-800">Drone Field Map Analysis</h3>
            </div>

            <div className="flex items-center gap-3 bg-slate-50 p-1.5 rounded-lg border border-slate-200">
                <button 
                    onClick={() => setOverlayType('NONE')}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition-all ${
                        overlayType === 'NONE' ? 'bg-white shadow text-slate-900' : 'text-slate-500 hover:text-slate-900'
                    }`}
                >
                    <Eye size={16} /> RGB
                </button>
                <button 
                    onClick={() => setOverlayType('NDVI')}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition-all ${
                        overlayType === 'NDVI' ? 'bg-emerald-500 shadow text-white' : 'text-slate-500 hover:text-emerald-600'
                    }`}
                >
                    <Layers size={16} /> NDVI
                </button>
                <button 
                    onClick={() => setOverlayType('THERMAL')}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition-all ${
                        overlayType === 'THERMAL' ? 'bg-rose-500 shadow text-white' : 'text-slate-500 hover:text-rose-600'
                    }`}
                >
                    <ThermometerSun size={16} /> Thermal
                </button>
            </div>
        </div>

        <div className="relative w-full h-[400px] bg-slate-900 overflow-hidden group">
            {/* Base Image */}
            <img 
                src={mapImage} 
                alt="Farm Map" 
                className="w-full h-full object-cover transition-transform duration-700 hover:scale-105"
            />

            {/* Overlays */}
            {overlayType !== 'NONE' && (
                <div 
                    className="absolute inset-0 mix-blend-multiply pointer-events-none transition-opacity duration-500"
                    style={{ 
                        opacity: overlayOpacity,
                        background: overlayType === 'NDVI' 
                            ? `radial-gradient(circle at 30% 40%, ${ndviColors.bg} 0%, transparent 40%), radial-gradient(circle at 70% 60%, ${ndviColors.mid} 0%, transparent 40%), radial-gradient(circle at 80% 20%, ${ndviColors.low} 0%, transparent 30%), ${ndviColors.bg}`
                            : 'radial-gradient(circle at 50% 50%, #facc15 0%, #ef4444 40%, #3b82f6 100%)'
                    }}
                />
