            <div className="bg-slate-50 p-4 rounded-lg border border-slate-100">
                <p className="text-sm font-medium text-slate-700 mb-3">Visual Threshold Preview</p>
                <div className="h-6 w-full rounded-full bg-slate-200 overflow-hidden flex shadow-inner relative">
