                    <div 
                        style={{ flex: 1 }} 
                        className="bg-emerald-500 h-full transition-all duration-300 flex items-center justify-center text-[10px] text-white font-bold"
                    >
                        HEALTHY
                    </div>
                </div>
                <div className="flex justify-between text-xs text-slate-400 mt-2 font-mono">
                    <span>0.0</span>
                    <span>1.0</span>
                </div>
            </div>
        </div>
      </div>

      {/* Main Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Field List */}
        <div className="lg:col-span-1 space-y-4">
          <h2 className="text-lg font-semibold text-slate-800 mb-2">My Fields</h2>
          {displayedCrops.map((crop) => (
            <div 
              key={crop.id}
              onClick={() => setSelectedCrop(crop)}
              className={`p-4 rounded-xl border cursor-pointer transition-all ${
                selectedCrop?.id === crop.id 
                  ? 'border-emerald-500 bg-emerald-50 ring-1 ring-emerald-500' 
                  : 'border-slate-200 bg-white hover:border-emerald-300'
              }`}
            >
              <div className="flex justify-between items-start mb-2">
                <div>
                  <h3 className="font-semibold text-slate-900">{crop.name}</h3>
                  <p className="text-xs text-slate-500">{crop.type} • ID: {crop.fieldId}</p>
                </div>
                <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                  crop.status === HealthStatus.HEALTHY ? 'bg-green-100 text-green-700' :
                  crop.status === HealthStatus.WARNING ? 'bg-amber-100 text-amber-700' :
                  'bg-rose-100 text-rose-700'
                }`}>
                  {crop.status}
                </span>
              </div>
              <div className="flex items-center space-x-4 text-sm text-slate-600">
                <div className="flex items-center space-x-1">
                  <Sprout size={14} className="text-emerald-500" />
                  <span className="font-mono font-medium">NDVI: {crop.ndvi}</span>
                </div>
                <div className="flex items-center space-x-1">
                  <Droplets size={14} className="text-blue-500" />
                  <span>Moist: {crop.soilMoisture}%</span>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Detailed View / Analysis */}
        <div className="lg:col-span-2 space-y-6">
          {/* AI Analysis Section */}
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
            <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="font-semibold text-slate-800 flex items-center gap-2">
                <Scan className="text-indigo-500" size={18} />
                AI Crop Doctor (Single Plant)
              </h3>
            </div>

            <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-4">
                <div 
                    onClick={triggerUpload}
                    className="border-2 border-dashed border-slate-300 rounded-lg p-6 flex flex-col items-center justify-center min-h-[200px] bg-slate-50 relative cursor-pointer hover:bg-slate-100 transition-colors"
                >
                  {analysisImage ? (
                    <img 
                      src={analysisImage} 
                      alt="Crop Analysis" 
                      className="absolute inset-0 w-full h-full object-cover rounded-lg" 
                    />
                  ) : (
                    <div className="text-center pointer-events-none">
                      <Upload className="mx-auto h-10 w-10 text-slate-400 mb-2" />
                      <p className="text-sm text-slate-500">Upload leaf or field image</p>
                    </div>
                  )}
                  <input 
                    ref={fileInputRef}
                    type="file" 
                    accept="image/*"
                    onChange={handleImageUpload}
                    className="hidden"
                  />
                </div>
                <button 
                  onClick={runAnalysis}
                  disabled={!analysisImage || analyzing}
                  className={`w-full py-2 rounded-lg font-medium flex justify-center items-center space-x-2 ${
                    !analysisImage ? 'bg-slate-100 text-slate-400 cursor-not-allowed' :
                    analyzing ? 'bg-indigo-400 text-white cursor-wait' :
                    'bg-indigo-600 text-white hover:bg-indigo-700'
                  }`}
                >
                  {analyzing ? (
                    <span>Analyzing...</span>
                  ) : (
                    <>
                      <Scan size={16} />
                      <span>Analyze Crop Health</span>
                    </>
                  )}
                </button>
              </div>

              <div className="space-y-4">
                {analysisResult ? (
                  <div className="animate-fade-in space-y-3">
                    <div className="flex items-center justify-between">
                      <h4 className="font-bold text-lg text-slate-900">{analysisResult.detectedSubject}</h4>
                      <span className="text-xs bg-indigo-100 text-indigo-700 px-2 py-1 rounded-full">
                         {analysisResult.confidence}% Conf.
                      </span>
                    </div>

                    <div className={`p-3 rounded-lg border-l-4 ${
                      analysisResult.condition.toLowerCase().includes('healthy') ? 'bg-green-50 border-green-500' : 'bg-rose-50 border-rose-500'
                    }`}>
                      <p className="font-medium text-slate-800">Condition: {analysisResult.condition}</p>
                    </div>

                    {analysisResult.issues.length > 0 && (
                      <div>
                        <p className="text-xs font-semibold text-slate-500 uppercase mb-1">Detected Issues</p>
                        <ul className="list-disc pl-4 space-y-1 text-sm text-slate-700">
                          {analysisResult.issues.map((issue, i) => (
                            <li key={i}>{issue}</li>
                          ))}
                        </ul>
                      </div>
                    )}

                    <div>
                      <p className="text-xs font-semibold text-slate-500 uppercase mb-1">AI Recommendations</p>
                      <ul className="space-y-2">
                        {analysisResult.recommendations.map((rec, i) => (
                          <li key={i} className="flex items-start space-x-2 text-sm bg-slate-50 p-2 rounded">
                            <CheckCircle size={14} className="text-emerald-500 mt-0.5 flex-shrink-0" />
                            <span>{rec}</span>
                          </li>
                        ))}
                      </ul>
                    </div>

                    <button 
                      onClick={handleDownloadPDF}
                      className="mt-4 w-full py-2 flex items-center justify-center space-x-2 bg-slate-800 text-white rounded-lg hover:bg-slate-900 transition-colors text-sm shadow-md"
                    >
                      <Download size={16} />
                      <span>Download PDF Report</span>
                    </button>
                  </div>
                ) : (
                  <div className="h-full flex items-center justify-center text-slate-400 text-sm italic">
                    Result will appear here...
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* Charts Section */}
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
            <h3 className="font-semibold text-slate-800 mb-6">NDVI Growth Trends (Drag lines to adjust thresholds)</h3>
            <div className="h-64 w-full" ref={chartContainerRef}>
              <ResponsiveContainer width="100%" height="100%">
                <LineChart 
                  data={growthData} 
                  margin={{ top: 20, right: 30, left: 20, bottom: 10 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="name" stroke="#64748b" fontSize={12} />
                  <YAxis stroke="#64748b" fontSize={12} domain={[0, 1]} />
                  <Tooltip 
                    contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }} 
                  />
                  <Line 
                    type="monotone" 
                    dataKey="ndvi" 
                    stroke="#10b981" 
                    strokeWidth={3} 
                    dot={{ fill: '#10b981', strokeWidth: 2 }} 
                    activeDot={{ r: 8 }} 
                  />

                  {/* Interactive Threshold Lines */}
                  <ReferenceLine 
                    y={healthyThreshold} 
                    stroke="#059669" 
                    strokeDasharray="5 5"
                    strokeWidth={2}
                    label={{ value: 'Healthy', position: 'insideTopLeft', fill: '#059669', fontSize: 11 }}
                    style={{ cursor: 'ns-resize' }}
                    onMouseDown={() => setDraggingThreshold('healthy')}
                  />
                  <ReferenceLine 
                    y={warningThreshold} 
                    stroke="#e11d48" 
                    strokeDasharray="5 5" 
                    strokeWidth={2}
                    label={{ value: 'Critical', position: 'insideBottomLeft', fill: '#e11d48', fontSize: 11 }}
                    style={{ cursor: 'ns-resize' }}
                    onMouseDown={() => setDraggingThreshold('warning')}
                  />
                </LineChart>
              </ResponsiveContainer>
              <div className="flex justify-center gap-4 mt-2 text-xs text-slate-500">
                <span className="flex items-center gap-1"><div className="w-3 h-0.5 bg-emerald-600 border border-dashed"></div> Healthy ({healthyThreshold.toFixed(2)})</span>
                <span className="flex items-center gap-1"><div className="w-3 h-0.5 bg-rose-500 border border-dashed"></div> Critical ({warningThreshold.toFixed(2)})</span>
              </div>
            </div>
          </div>

        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { 
  Activity, 
  Thermometer, 
  AlertOctagon, 
  Video,
  Camera,
  X,
  HeartPulse,
  Power,
  Scan,
  Loader2,
  FileText
} from 'lucide-react';
import { MOCK_ANIMALS } from '../constants';
import { AnimalData, HealthStatus, AIAnalysisResult } from '../types';
import { analyzeLivestockFrame } from '../services/geminiService';
import { ApiService } from '../services/api';
import { ExportService } from '../services/exportService';
import { BarChart, Bar, XAxis, Tooltip, ResponsiveContainer } from 'recharts';

// @ts-ignore
import * as tf from '@tensorflow/tfjs';
// @ts-ignore
import * as cocoSsd from '@tensorflow-models/coco-ssd';

// Tracking Types
interface TrackedObject {
  id: number;
  bbox: [number, number, number, number]; // x, y, w, h
  class: string;
  score: number;
  lastSeen: number;
  velocity: number;
  behavior: string;
  center: { x: number, y: number };
}

export const LivestockDashboard: React.FC = () => {
  const [animals, setAnimals] = useState<AnimalData[]>(MOCK_ANIMALS);
  const [analyzingId, setAnalyzingId] = useState<string | null>(null);
  const [analysisResults, setAnalysisResults] = useState<Record<string, AIAnalysisResult>>({});
  const [showRecommendations, setShowRecommendations] = useState(false);
  const [recommendations, setRecommendations] = useState<any[]>([]);

  // Camera & Live Feed State
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isCameraActive, setIsCameraActive] = useState(false);
  const [cameraError, setCameraError] = useState<string | null>(null);
  const [feedMode, setFeedMode] = useState<'SIMULATION' | 'CAMERA'>('SIMULATION');

  // AI Model State
  const [model, setModel] = useState<any>(null);
  const [modelLoading, setModelLoading] = useState(true);

  // Tracking State Refs
  const trackedObjectsRef = useRef<Map<number, TrackedObject>>(new Map());
  const nextObjectIdRef = useRef(1);

  // Load COCO-SSD Model
  useEffect(() => {
    const loadModel = async () => {
        try {
            await tf.ready();
            const loadedModel = await cocoSsd.load();
            setModel(loadedModel);
            setModelLoading(false);
            console.log("TensorFlow Model Loaded");
        } catch (err) {
            console.error("Failed to load TensorFlow model", err);
            setModelLoading(false);
        }
    };
    loadModel();
  }, []);

  useEffect(() => {
    // Poll for live animal tracking data
    const interval = setInterval(async () => {
      const data = await ApiService.getAnimals();
      setAnimals(data);
    }, 3000);
    return () => clearInterval(interval);
  }, []);

  // Live Camera Logic
  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        // Wait for video to load metadata to avoid size mismatch
        videoRef.current.onloadedmetadata = () => {
             setIsCameraActive(true);
             setCameraError(null);
        };
      }
    } catch (err) {
      setCameraError("Camera access denied or unavailable.");
      console.error(err);
      setFeedMode('SIMULATION');
    }
  };

  const stopCamera = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      const stream = videoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
    setIsCameraActive(false);
  };

  useEffect(() => {
    if (feedMode === 'CAMERA') {
      startCamera();
    } else {
      stopCamera();
    }
    return () => stopCamera();
  }, [feedMode]);

  // --- Tracking & Behavior Logic ---

  const getCenter = (bbox: [number, number, number, number]) => ({
    x: bbox[0] + bbox[2] / 2,
    y: bbox[1] + bbox[3] / 2
  });

  const getDistance = (p1: { x: number, y: number }, p2: { x: number, y: number }) => {
    return Math.sqrt(Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2));
  };

  const inferBehavior = (velocity: number, bbox: [number, number, number, number], canvasHeight: number): string => {
    const [x, y, w, h] = bbox;
    const aspectRatio = w / h;
    const bottomY = y + h;

    // 1. Movement Check
    if (velocity > 2.5) return "Walking";

    // 2. Posture Check (Lying down vs Standing)
    // Cows/Sheep appear wider when lying down
    if (aspectRatio > 1.6) return "Resting";

    // 3. Position Check (Feeding)
    // If the bottom of the bounding box is in the bottom 25% of the frame, 
    // or if the head (usually lower part) is down.
    // This is a heuristic approximation.
    if (bottomY > canvasHeight * 0.85) return "Feeding";

    return "Standing";
  };

  const updateTrackedObjects = (predictions: any[], canvasHeight: number) => {
    const newTrackedMap = new Map<number, TrackedObject>();
    const currentFrameTime = Date.now();
    const matchThreshold = 100; // Max pixels to match an object between frames

    // Convert predictions to temporary object format
    const detected = predictions.map(p => ({
      bbox: p.bbox,
      class: p.class,
      score: p.score,
      center: getCenter(p.bbox)
    }));

    // Match with existing objects
    const usedIndices = new Set<number>();

    trackedObjectsRef.current.forEach((trackedObj, id) => {
      let bestMatchIndex = -1;
      let minDist = Infinity;

      detected.forEach((det, idx) => {
        if (usedIndices.has(idx)) return;
        const dist = getDistance(trackedObj.center, det.center);
        if (dist < minDist && dist < matchThreshold) {
          minDist = dist;
          bestMatchIndex = idx;
        }
      });

      if (bestMatchIndex !== -1) {
        // Update existing object
        const match = detected[bestMatchIndex];
        const velocity = minDist; // Distance moved per frame approx velocity
        const behavior = inferBehavior(velocity, match.bbox, canvasHeight);

        newTrackedMap.set(id, {
          id,
          bbox: match.bbox,
          class: match.class,
          score: match.score,
          lastSeen: currentFrameTime,
          velocity,
          behavior,
          center: match.center
        });
        usedIndices.add(bestMatchIndex);
      } else {
        // Object lost temporarily? Keep if recent, else drop
        if (currentFrameTime - trackedObj.lastSeen < 1000) {
           newTrackedMap.set(id, { ...trackedObj, velocity: 0 }); // Assume stopped if not seen
        }
      }
    });

    // Add new objects
    detected.forEach((det, idx) => {
      if (!usedIndices.has(idx)) {
        const id = nextObjectIdRef.current++;
        const behavior = inferBehavior(0, det.bbox, canvasHeight);
        newTrackedMap.set(id, {
          id,
          bbox: det.bbox,
          class: det.class,
          score: det.score,
          lastSeen: currentFrameTime,
          velocity: 0,
          behavior,
          center: det.center
        });
      }
    });

    trackedObjectsRef.current = newTrackedMap;
    return Array.from(newTrackedMap.values());
  };


  // --- AI Detection Loop ---
  useEffect(() => {
    if (!canvasRef.current || !videoRef.current) return;

    // If simulation, use the simple loop
    if (feedMode === 'SIMULATION') {
         runSimulationLoop();
         return;
    }

    // If camera is active but model not ready, do nothing yet
    if (feedMode === 'CAMERA' && (!isCameraActive || !model)) return;

    // Real Object Detection Loop
    let animationId: number;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    const video = videoRef.current;

    const runDetection = async () => {
        if (!ctx || !video || video.readyState !== 4) {
            animationId = requestAnimationFrame(runDetection);
            return;
        }

        // Match canvas size to video size
        if (canvas.width !== video.videoWidth || canvas.height !== video.videoHeight) {
            canvas.width = video.videoWidth;
            canvas.height = video.videoHeight;
        }

        // Detect objects
        const predictions = await model.detect(video);

        // Filter for farm animals or people
        const relevantClasses = ['cow', 'sheep', 'horse', 'dog', 'cat', 'bird', 'person', 'zebra', 'giraffe', 'elephant', 'bear'];
        const filteredPredictions = predictions.filter((p: any) => relevantClasses.includes(p.class));

        // Update Tracker & Behavior
        const trackedObjects = updateTrackedObjects(filteredPredictions, canvas.height);

        // Clear canvas
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        if (trackedObjects.length === 0) {
            // Draw "NO ANIMAL DETECTED"
            ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            ctx.fillStyle = '#ef4444'; // Red
            ctx.font = 'bold 24px Inter, sans-serif';
            ctx.textAlign = 'center';
            ctx.fillText('NO ANIMAL DETECTED', canvas.width / 2, canvas.height / 2);

            ctx.font = '14px Inter, sans-serif';
            ctx.fillStyle = '#ffffff';
            ctx.fillText('Move camera to scan barn area', canvas.width / 2, canvas.height / 2 + 30);
        } else {
            // Draw Bounding Boxes & Behavior
            trackedObjects.forEach((obj) => {
                const [x, y, width, height] = obj.bbox;
                const isAnimal = obj.class !== 'person';
                const color = isAnimal ? '#10b981' : '#f59e0b'; // Green for animal, Amber for person

                // Box
                ctx.strokeStyle = color;
                ctx.lineWidth = 4;
                ctx.strokeRect(x, y, width, height);

                // Label Background
                ctx.fillStyle = color;
                // Wider background for longer behavior text
                const labelText = `${obj.class.toUpperCase()}: ${obj.behavior}`;
                const textWidth = ctx.measureText(labelText).width;
                ctx.fillRect(x, y - 25, textWidth + 20, 25);

                // Text
                ctx.fillStyle = '#ffffff';
                ctx.font = 'bold 14px Inter, sans-serif';
                ctx.textAlign = 'left';
                ctx.fillText(
                    labelText, 
                    x + 5, 
                    y - 7
                );

                // Confidence
                ctx.fillStyle = 'rgba(255,255,255,0.8)';
                ctx.font = '10px Inter, sans-serif';
                ctx.fillText(`${Math.round(obj.score * 100)}%`, x + 5, y + 15);
            });
        }

        animationId = requestAnimationFrame(runDetection);
    };

    runDetection();

    return () => {
        cancelAnimationFrame(animationId);
    };
  }, [isCameraActive, feedMode, model]);


  // Separate simulation loop function to keep effect clean
  const runSimulationLoop = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationId: number;
    let frame = 0;

    const targets = [
        { x: 20, y: 30, dx: 0.2, dy: 0, label: 'Cow #882', status: 'Healthy', behavior: 'Grazing' },
        { x: 60, y: 50, dx: 0, dy: 0, label: 'Cow #891', status: 'Warning', behavior: 'Resting' }
    ];

    const draw = () => {
        if (!canvas || !ctx) return;
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        // Ensure default size for simulation if needed
        if (canvas.width !== 800) { canvas.width = 800; canvas.height = 450; }

        frame++;

        targets.forEach((target, i) => {
            // Simulate random movement changes for behavior demo
            if (frame % 200 === 0) {
               const r = Math.random();
               if (r > 0.6) { target.behavior = 'Walking'; target.dx = 0.5; }
               else if (r > 0.3) { target.behavior = 'Grazing'; target.dx = 0.1; }
               else { target.behavior = 'Resting'; target.dx = 0; }
            }

            target.x += target.dx;
            if (target.x < 10 || target.x > 80) target.dx *= -1;

            const boxX = (target.x / 100) * canvas.width;
            const boxY = (target.y / 100) * canvas.height;
            const boxW = 120;
            const boxH = target.behavior === 'Resting' ? 60 : 80; // Shorter if resting

            ctx.strokeStyle = target.status === 'Healthy' ? '#10b981' : '#f59e0b';
            ctx.lineWidth = 2;
            ctx.strokeRect(boxX, boxY, boxW, boxH);

            // Header
            ctx.fillStyle = target.status === 'Healthy' ? '#10b981' : '#f59e0b';
            ctx.fillRect(boxX, boxY - 24, boxW, 24);

            ctx.fillStyle = '#ffffff';
            ctx.font = 'bold 12px Inter, sans-serif';
            ctx.textAlign = 'left'; 
            ctx.fillText(target.label, boxX + 5, boxY - 8);

            // Details
            ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
            ctx.font = '11px Inter, sans-serif';
            ctx.fillText(`Status: ${target.status}`, boxX + 5, boxY + 15);
            ctx.fillStyle = '#fbbf24'; // Amber for behavior
            ctx.font = 'bold 11px Inter, sans-serif';
            ctx.fillText(`Action: ${target.behavior}`, boxX + 5, boxY + 28);
        });

        // Scanning line
        const time = Date.now() / 1000;
        const scanY = (Math.sin(time) + 1) / 2 * canvas.height;
        ctx.strokeStyle = 'rgba(99, 102, 241, 0.5)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(0, scanY);
        ctx.lineTo(canvas.width, scanY);
        ctx.stroke();

        animationId = requestAnimationFrame(draw);
    };
    draw();
    return () => cancelAnimationFrame(animationId);
  };


  const handleScanAnimal = async (animal: AnimalData) => {
    if (!animal.imageUrl) return;
    setAnalyzingId(animal.id);

    try {
        const response = await fetch(animal.imageUrl);
        const blob = await response.blob();
        const reader = new FileReader();
        reader.onloadend = async () => {
            const base64 = reader.result as string;
            const result = await analyzeLivestockFrame(base64.split(',')[1]);
            setAnalysisResults(prev => ({ ...prev, [animal.id]: result }));
            setAnalyzingId(null);
        };
        reader.readAsDataURL(blob);
    } catch (e) {
        console.error("Error analyzing animal", e);
        setAnalyzingId(null);
    }
  };

  const handleExportData = () => {
    const dataToExport = animals.map(a => ({
        Tag: a.tagId,
        Species: a.species,
        Age: a.ageMonths,
        Weight: a.weightKg,
        Temp: a.temperature,
        Activity: a.activityLevel,
        Status: a.status
    }));
    ExportService.exportToCSV(dataToExport, 'livestock_metrics.csv');
  };

  const handleViewRecommendations = async () => {
    setShowRecommendations(true);
    if (recommendations.length === 0) {
        const recs = await ApiService.getBreedingRecommendations();
        setRecommendations(recs);
    }
  };

  const healthData = [
    { name: 'Mon', score: 92 },
    { name: 'Tue', score: 93 },
    { name: 'Wed', score: 88 },
    { name: 'Thu', score: 94 },
    { name: 'Fri', score: 95 },
    { name: 'Sat', score: 91 },
    { name: 'Sun', score: 96 },
  ];

  return (
    <div className="space-y-6 relative">
      {/* Recommendations Modal */}
      {showRecommendations && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-fade-in">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-md overflow-hidden">
                <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-indigo-600 text-white">
                    <h3 className="font-bold flex items-center gap-2">
                        <HeartPulse size={20} /> Breeding Insights
                    </h3>
                    <button onClick={() => setShowRecommendations(false)} className="hover:bg-indigo-700 p-1 rounded-full">
                        <X size={20} />
                    </button>
                </div>
                <div className="p-4 space-y-3">
                    {recommendations.length === 0 ? (
                        <div className="text-center py-8 text-slate-500">Loading insights...</div>
                    ) : (
                        recommendations.map(rec => (
                            <div key={rec.id} className="p-3 bg-indigo-50 rounded-lg border border-indigo-100">
                                <div className="flex justify-between mb-1">
                                    <span className="font-bold text-indigo-900">{rec.animalId}</span>
                                    <span className="text-xs bg-white px-2 py-0.5 rounded text-indigo-600 font-bold border border-indigo-200">
                                        {rec.confidence}% Match
                                    </span>
                                </div>
                                <p className="text-sm text-slate-700 mb-1">Window: <span className="font-semibold">{rec.window}</span></p>
                                <p className="text-xs text-slate-500">{rec.note}</p>
                            </div>
                        ))
                    )}
                </div>
                <div className="p-4 bg-slate-50 text-center">
                    <button onClick={() => setShowRecommendations(false)} className="text-sm text-indigo-600 font-medium hover:underline">
                        Close Insights
                    </button>
                </div>
            </div>
        </div>
      )}

      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Livestock Monitoring</h1>
          <p className="text-slate-500">Real-time health tracking & behavior analysis</p>
        </div>
        <div className="flex items-center space-x-2">
