import React, { useState, useEffect, useRef } from 'react';
import { 
  Activity, 
  Thermometer, 
  AlertOctagon, 
  Video,
  Camera,
  X,
  HeartPulse,
  Power,
  Scan,
  Loader2,
  FileText
} from 'lucide-react';
import { MOCK_ANIMALS } from '../constants';
import { AnimalData, HealthStatus, AIAnalysisResult } from '../types';
import { analyzeLivestockFrame } from '../services/geminiService';
import { ApiService } from '../services/api';
import { ExportService } from '../services/exportService';
import { BarChart, Bar, XAxis, Tooltip, ResponsiveContainer } from 'recharts';
import { useNotifications } from '../context/NotificationContext';

// @ts-ignore
import * as tf from '@tensorflow/tfjs';
// @ts-ignore
import * as cocoSsd from '@tensorflow-models/coco-ssd';

// Tracking Types
interface TrackedObject {
  id: number;
  bbox: [number, number, number, number]; // x, y, w, h
  class: string;
  score: number;
  lastSeen: number;
  velocity: number;
  behavior: string;
  center: { x: number, y: number };
}

export const LivestockDashboard: React.FC = () => {
  const { addNotification } = useNotifications();
  const [animals, setAnimals] = useState<AnimalData[]>(MOCK_ANIMALS);
  const [analyzingId, setAnalyzingId] = useState<string | null>(null);
  const [analysisResults, setAnalysisResults] = useState<Record<string, AIAnalysisResult>>({});
  const [showRecommendations, setShowRecommendations] = useState(false);
  const [recommendations, setRecommendations] = useState<any[]>([]);

  // Camera & Live Feed State
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isCameraActive, setIsCameraActive] = useState(false);
  const [cameraError, setCameraError] = useState<string | null>(null);
  const [feedMode, setFeedMode] = useState<'SIMULATION' | 'CAMERA'>('SIMULATION');

  // AI Model State
  const [model, setModel] = useState<any>(null);
  const [modelLoading, setModelLoading] = useState(true);

  // Tracking State Refs
  const trackedObjectsRef = useRef<Map<number, TrackedObject>>(new Map());
  const nextObjectIdRef = useRef(1);

  // Load COCO-SSD Model
  useEffect(() => {
    const loadModel = async () => {
        try {
            await tf.ready();
            const loadedModel = await cocoSsd.load();
            setModel(loadedModel);
            setModelLoading(false);
            console.log("TensorFlow Model Loaded");
        } catch (err) {
            console.error("Failed to load TensorFlow model", err);
            setModelLoading(false);
        }
    };
    loadModel();
  }, []);

  useEffect(() => {
    // Poll for live animal tracking data
    const interval = setInterval(async () => {
      const data = await ApiService.getAnimals();
      setAnimals(data);
    }, 3000);
    return () => clearInterval(interval);
  }, []);

  // Live Camera Logic
  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        // Wait for video to load metadata to avoid size mismatch
        videoRef.current.onloadedmetadata = () => {
             setIsCameraActive(true);
             setCameraError(null);
             addNotification({ title: 'Camera Active', message: 'Live AI surveillance feed started.', type: 'INFO' });
        };
      }
    } catch (err) {
      setCameraError("Camera access denied or unavailable.");
      console.error(err);
      setFeedMode('SIMULATION');
      addNotification({ title: 'Camera Failed', message: 'Could not access camera device.', type: 'WARNING' });
    }
  };

  const stopCamera = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      const stream = videoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
    setIsCameraActive(false);
  };

  useEffect(() => {
    if (feedMode === 'CAMERA') {
      startCamera();
    } else {
      stopCamera();
    }
    return () => stopCamera();
  }, [feedMode]);

  // --- Tracking & Behavior Logic ---

  const getCenter = (bbox: [number, number, number, number]) => ({
    x: bbox[0] + bbox[2] / 2,
    y: bbox[1] + bbox[3] / 2
  });

  const getDistance = (p1: { x: number, y: number }, p2: { x: number, y: number }) => {
    return Math.sqrt(Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2));
  };

  const inferBehavior = (velocity: number, bbox: [number, number, number, number], canvasHeight: number): string => {
    const [x, y, w, h] = bbox;
    const aspectRatio = w / h;
    const bottomY = y + h;

    // 1. Movement Check
    if (velocity > 2.5) return "Walking";

    // 2. Posture Check (Lying down vs Standing)
    // Cows/Sheep appear wider when lying down
    if (aspectRatio > 1.6) return "Resting";

    // 3. Position Check (Feeding)
    // If the bottom of the bounding box is in the bottom 25% of the frame, 
    // or if the head (usually lower part) is down.
    // This is a heuristic approximation.
    if (bottomY > canvasHeight * 0.85) return "Feeding";

    return "Standing";
  };

  const updateTrackedObjects = (predictions: any[], canvasHeight: number) => {
    const newTrackedMap = new Map<number, TrackedObject>();
    const currentFrameTime = Date.now();
    const matchThreshold = 100; // Max pixels to match an object between frames

    // Convert predictions to temporary object format
    const detected = predictions.map(p => ({
      bbox: p.bbox,
      class: p.class,
      score: p.score,
      center: getCenter(p.bbox)
    }));

    // Match with existing objects
    const usedIndices = new Set<number>();

    trackedObjectsRef.current.forEach((trackedObj, id) => {
      let bestMatchIndex = -1;
      let minDist = Infinity;

      detected.forEach((det, idx) => {
        if (usedIndices.has(idx)) return;
        const dist = getDistance(trackedObj.center, det.center);
        if (dist < minDist && dist < matchThreshold) {
          minDist = dist;
          bestMatchIndex = idx;
        }
      });

      if (bestMatchIndex !== -1) {
        // Update existing object
        const match = detected[bestMatchIndex];
        const velocity = minDist; // Distance moved per frame approx velocity
        const behavior = inferBehavior(velocity, match.bbox, canvasHeight);

        newTrackedMap.set(id, {
          id,
          bbox: match.bbox,
          class: match.class,
          score: match.score,
          lastSeen: currentFrameTime,
          velocity,
          behavior,
          center: match.center
        });
        usedIndices.add(bestMatchIndex);
      } else {
        // Object lost temporarily? Keep if recent, else drop
        if (currentFrameTime - trackedObj.lastSeen < 1000) {
           newTrackedMap.set(id, { ...trackedObj, velocity: 0 }); // Assume stopped if not seen
        }
      }
    });

    // Add new objects
    detected.forEach((det, idx) => {
      if (!usedIndices.has(idx)) {
        const id = nextObjectIdRef.current++;
        const behavior = inferBehavior(0, det.bbox, canvasHeight);
        newTrackedMap.set(id, {
          id,
          bbox: det.bbox,
          class: det.class,
          score: det.score,
          lastSeen: currentFrameTime,
          velocity: 0,
          behavior,
          center: det.center
        });
      }
    });

    trackedObjectsRef.current = newTrackedMap;
    return Array.from(newTrackedMap.values());
  };


  // --- AI Detection Loop ---
  useEffect(() => {
    if (!canvasRef.current || !videoRef.current) return;

    // If simulation, use the simple loop
    if (feedMode === 'SIMULATION') {
         runSimulationLoop();
         return;
    }

    // If camera is active but model not ready, do nothing yet
    if (feedMode === 'CAMERA' && (!isCameraActive || !model)) return;

    // Real Object Detection Loop
    let animationId: number;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    const video = videoRef.current;

    const runDetection = async () => {
        if (!ctx || !video || video.readyState !== 4) {
            animationId = requestAnimationFrame(runDetection);
            return;
        }

        // Match canvas size to video size
        if (canvas.width !== video.videoWidth || canvas.height !== video.videoHeight) {
            canvas.width = video.videoWidth;
            canvas.height = video.videoHeight;
        }

        // Detect objects
        const predictions = await model.detect(video);

        // Filter for farm animals or people
        const relevantClasses = ['cow', 'sheep', 'horse', 'dog', 'cat', 'bird', 'person', 'zebra', 'giraffe', 'elephant', 'bear'];
        const filteredPredictions = predictions.filter((p: any) => relevantClasses.includes(p.class));

        // Update Tracker & Behavior
        const trackedObjects = updateTrackedObjects(filteredPredictions, canvas.height);

        // Clear canvas
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        if (trackedObjects.length === 0) {
            // Draw "NO ANIMAL DETECTED"
            ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            ctx.fillStyle = '#ef4444'; // Red
            ctx.font = 'bold 24px Inter, sans-serif';
            ctx.textAlign = 'center';
            ctx.fillText('NO ANIMAL DETECTED', canvas.width / 2, canvas.height / 2);

            ctx.font = '14px Inter, sans-serif';
            ctx.fillStyle = '#ffffff';
            ctx.fillText('Move camera to scan barn area', canvas.width / 2, canvas.height / 2 + 30);
        } else {
            // Draw Bounding Boxes & Behavior
            trackedObjects.forEach((obj) => {
                const [x, y, width, height] = obj.bbox;
                const isAnimal = obj.class !== 'person';
                const color = isAnimal ? '#10b981' : '#f59e0b'; // Green for animal, Amber for person

                // Box
                ctx.strokeStyle = color;
                ctx.lineWidth = 4;
                ctx.strokeRect(x, y, width, height);

                // Label Background
                ctx.fillStyle = color;
                // Wider background for longer behavior text
                const labelText = `${obj.class.toUpperCase()}: ${obj.behavior}`;
                const textWidth = ctx.measureText(labelText).width;
                ctx.fillRect(x, y - 25, textWidth + 20, 25);

                // Text
                ctx.fillStyle = '#ffffff';
                ctx.font = 'bold 14px Inter, sans-serif';
                ctx.textAlign = 'left';
                ctx.fillText(
                    labelText, 
                    x + 5, 
                    y - 7
                );

                // Confidence
                ctx.fillStyle = 'rgba(255,255,255,0.8)';
                ctx.font = '10px Inter, sans-serif';
                ctx.fillText(`${Math.round(obj.score * 100)}%`, x + 5, y + 15);
            });
        }

        animationId = requestAnimationFrame(runDetection);
    };

    runDetection();

    return () => {
        cancelAnimationFrame(animationId);
    };
  }, [isCameraActive, feedMode, model]);


  // Separate simulation loop function to keep effect clean
  const runSimulationLoop = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationId: number;
    let frame = 0;

    const targets = [
        { x: 20, y: 30, dx: 0.2, dy: 0, label: 'Cow #882', status: 'Healthy', behavior: 'Grazing' },
        { x: 60, y: 50, dx: 0, dy: 0, label: 'Cow #891', status: 'Warning', behavior: 'Resting' }
    ];

    const draw = () => {
        if (!canvas || !ctx) return;
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        // Ensure default size for simulation if needed
        if (canvas.width !== 800) { canvas.width = 800; canvas.height = 450; }

        frame++;

        targets.forEach((target, i) => {
            // Simulate random movement changes for behavior demo
            if (frame % 200 === 0) {
               const r = Math.random();
               if (r > 0.6) { target.behavior = 'Walking'; target.dx = 0.5; }
               else if (r > 0.3) { target.behavior = 'Grazing'; target.dx = 0.1; }
               else { target.behavior = 'Resting'; target.dx = 0; }
            }

            target.x += target.dx;
            if (target.x < 10 || target.x > 80) target.dx *= -1;

            const boxX = (target.x / 100) * canvas.width;
            const boxY = (target.y / 100) * canvas.height;
            const boxW = 120;
            const boxH = target.behavior === 'Resting' ? 60 : 80; // Shorter if resting

            ctx.strokeStyle = target.status === 'Healthy' ? '#10b981' : '#f59e0b';
            ctx.lineWidth = 2;
            ctx.strokeRect(boxX, boxY, boxW, boxH);

            // Header
            ctx.fillStyle = target.status === 'Healthy' ? '#10b981' : '#f59e0b';
            ctx.fillRect(boxX, boxY - 24, boxW, 24);

            ctx.fillStyle = '#ffffff';
            ctx.font = 'bold 12px Inter, sans-serif';
            ctx.textAlign = 'left'; 
            ctx.fillText(target.label, boxX + 5, boxY - 8);

            // Details
            ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
            ctx.font = '11px Inter, sans-serif';
            ctx.fillText(`Status: ${target.status}`, boxX + 5, boxY + 15);
            ctx.fillStyle = '#fbbf24'; // Amber for behavior
            ctx.font = 'bold 11px Inter, sans-serif';
            ctx.fillText(`Action: ${target.behavior}`, boxX + 5, boxY + 28);
        });

        // Scanning line
        const time = Date.now() / 1000;
        const scanY = (Math.sin(time) + 1) / 2 * canvas.height;
        ctx.strokeStyle = 'rgba(99, 102, 241, 0.5)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(0, scanY);
        ctx.lineTo(canvas.width, scanY);
        ctx.stroke();

        animationId = requestAnimationFrame(draw);
    };
    draw();
    return () => cancelAnimationFrame(animationId);
  };


