    push: true
  });

  const [cropAlerts, setCropAlerts] = useState({
    irrigation: true,
    disease: true,
    nutrients: false,
    equipment: true
  });

  const [livestockAlerts, setLivestockAlerts] = useState({
    health: true,
    estrus: true,
    perimeter: true,
    predator: false
  });

  // Database Connection State
  const [dbConfig, setDbConfig] = useState({
    apiUrl: '',
    apiKey: '',
    connected: false
  });

  const [saved, setSaved] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState<'idle' | 'testing' | 'success' | 'failed'>('idle');

  useEffect(() => {
    // Load saved settings
    const savedUrl = localStorage.getItem('agri_api_url') || '';
    const savedKey = localStorage.getItem('agri_api_key') || '';
    if (savedUrl) {
        setDbConfig({ apiUrl: savedUrl, apiKey: savedKey, connected: true });
    }
  }, []);

  const handleSave = () => {
    // Save DB Config
    localStorage.setItem('agri_api_url', dbConfig.apiUrl);
    localStorage.setItem('agri_api_key', dbConfig.apiKey);

    setSaved(true);
    addNotification({ title: 'Settings Saved', message: 'Preferences and connection details updated.', type: 'SUCCESS' });
    setTimeout(() => setSaved(false), 2000);
  };

  const testConnection = async () => {
    if (!dbConfig.apiUrl) return;
    setConnectionStatus('testing');
    try {
        // Attempt a simple ping or fetch
        const controller = new AbortController();
        const id = setTimeout(() => controller.abort(), 5000); // 5s timeout

        const res = await fetch(`${dbConfig.apiUrl}/health`, { 
            method: 'GET',
            headers: { 'Authorization': `Bearer ${dbConfig.apiKey}` },
            signal: controller.signal
        });
        clearTimeout(id);

        if (res.ok) {
            setConnectionStatus('success');
            addNotification({ title: 'Connection Successful', message: 'Successfully reached the remote API.', type: 'SUCCESS' });
        } else {
            setConnectionStatus('failed');
            addNotification({ title: 'Connection Failed', message: `Server returned status: ${res.status}`, type: 'WARNING' });
        }
    } catch (e) {
        // Even if it fails (because the user doesn't actually have a backend), 
        // we show failed but save the config so they can implement it later.
        console.warn("Connection test failed", e);
        setConnectionStatus('failed');
        addNotification({ title: 'Network Error', message: 'Could not reach the provided endpoint.', type: 'WARNING' });
    }
  };

  const Toggle = ({ label, checked, onChange, icon: Icon, description }: any) => (
    <div className="flex items-center justify-between py-3">
      <div className="flex items-start gap-3">
        {Icon && <div className="mt-1 p-2 bg-slate-100 rounded-lg text-slate-600"><Icon size={18} /></div>}
        <div>
            <span className="font-medium text-slate-700 block">{label}</span>
            {description && <span className="text-xs text-slate-400">{description}</span>}
        </div>
      </div>
      <button 
        onClick={() => onChange(!checked)}
        className={`w-11 h-6 rounded-full transition-colors relative flex-shrink-0 ${checked ? 'bg-emerald-500' : 'bg-slate-300'}`}
      >
        <div className={`absolute top-1 left-1 bg-white w-4 h-4 rounded-full transition-transform shadow-sm ${checked ? 'translate-x-5' : 'translate-x-0'}`} />
      </button>
    </div>
  );

  return (
    <div className="max-w-5xl mx-auto space-y-6 pb-10">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Settings</h1>
          <p className="text-slate-500">Manage your farm preferences and database connections</p>
        </div>
        <button 
          onClick={handleSave}
          className={`flex items-center gap-2 px-6 py-2.5 rounded-lg transition-all shadow-md ${
            saved ? 'bg-emerald-100 text-emerald-700 border border-emerald-200' : 'bg-slate-900 text-white hover:bg-slate-800'
          }`}
        >
          {saved ? <CheckCircle size={18} /> : <Save size={18} />}
          <span className="font-medium">{saved ? 'Preferences Saved' : 'Save Changes'}</span>
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Database & Cloud Config */}
        <div className="lg:col-span-3">
             <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                <div className="flex items-center justify-between mb-6 pb-4 border-b border-slate-100">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-blue-100 rounded-lg text-blue-700">
                            <Database size={20} />
                        </div>
                        <div>
                            <h3 className="font-bold text-slate-800">Cloud Database Connection</h3>
                            <p className="text-sm text-slate-500">Connect your own backend API (PostgreSQL/MongoDB via REST)</p>
                        </div>
                    </div>
                    <div className="flex items-center gap-2">
                         {dbConfig.apiUrl ? (
                             <span className="flex items-center gap-1 text-xs font-medium text-emerald-600 bg-emerald-50 px-2 py-1 rounded">
                                 <Wifi size={14} /> Cloud Active
                             </span>
                         ) : (
                             <span className="flex items-center gap-1 text-xs font-medium text-slate-500 bg-slate-100 px-2 py-1 rounded">
                                 <WifiOff size={14} /> Using Local DB
                             </span>
                         )}
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 mb-1">API Endpoint URL</label>
                            <div className="relative">
                                <Server className="absolute left-3 top-2.5 text-slate-400" size={18} />
                                <input 
                                    type="text" 
                                    placeholder="https://api.yourfarm.com/v1" 
                                    value={dbConfig.apiUrl}
                                    onChange={(e) => setDbConfig({...dbConfig, apiUrl: e.target.value})}
                                    className="w-full pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm font-mono"
                                />
                            </div>
                            <p className="text-xs text-slate-500 mt-1">Must accept JSON requests. Routes expected: <code className="bg-slate-100 px-1 rounded">/crops</code>, <code className="bg-slate-100 px-1 rounded">/animals</code></p>
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 mb-1">API Key / Auth Token</label>
                            <input 
                                type="password" 
                                placeholder="sk_live_..." 
                                value={dbConfig.apiKey}
                                onChange={(e) => setDbConfig({...dbConfig, apiKey: e.target.value})}
                                className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm font-mono"
                            />
                        </div>
                    </div>

                    <div className="bg-slate-50 p-4 rounded-xl border border-slate-100 flex flex-col justify-between">
                        <div>
                            <h4 className="font-semibold text-slate-800 mb-2">Connection Status</h4>
                            <div className="flex items-center gap-2 mb-2">
                                <div className={`w-3 h-3 rounded-full ${
                                    connectionStatus === 'success' ? 'bg-emerald-500' :
                                    connectionStatus === 'failed' ? 'bg-rose-500' : 
                                    connectionStatus === 'testing' ? 'bg-yellow-400 animate-pulse' : 'bg-slate-300'
                                }`} />
                                <span className="text-sm font-medium text-slate-700">
                                    {connectionStatus === 'idle' ? 'Not Tested' :
                                     connectionStatus === 'testing' ? 'Testing Connection...' :
                                     connectionStatus === 'success' ? 'Connected Successfully' : 'Connection Failed'}
                                </span>
                            </div>
                            <p className="text-xs text-slate-500">
                                When connected, the dashboard will fetch real-time data from your server. If the connection drops, it automatically falls back to the local browser database.
                            </p>
                        </div>
                        <button 
                            onClick={testConnection}
                            disabled={!dbConfig.apiUrl || connectionStatus === 'testing'}
                            className="mt-4 w-full py-2 bg-white border border-slate-300 text-slate-700 font-medium rounded-lg hover:bg-slate-50 disabled:opacity-50 transition-colors text-sm"
                        >
                            Test Connection
                        </button>
                    </div>
                </div>
             </div>
        </div>

        {/* Notification Channels Column */}
        <div className="lg:col-span-1 space-y-6">
            <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                <h3 className="font-bold text-slate-800 mb-1 flex items-center gap-2">
                    <Bell size={18} className="text-indigo-600" /> Notification Channels
                </h3>
                <p className="text-sm text-slate-500 mb-5">Where should we send your alerts?</p>

                <div className="divide-y divide-slate-50">
                    <Toggle 
                    label="Email Alerts" 
                    description="Daily digests & critical alerts"
                    checked={channels.email} 
                    onChange={(v: boolean) => setChannels({...channels, email: v})} 
                    icon={Mail}
                    />
                    <Toggle 
                    label="SMS Notifications" 
                    description="Instant critical warnings"
                    checked={channels.sms} 
                    onChange={(v: boolean) => setChannels({...channels, sms: v})} 
                    icon={MessageSquare}
                    />
                    <Toggle 
                    label="Mobile Push" 
                    description="Real-time app notifications"
                    checked={channels.push} 
                    onChange={(v: boolean) => setChannels({...channels, push: v})} 
                    icon={Smartphone}
                    />
                </div>

                <div className="mt-6 p-4 bg-indigo-50 rounded-lg border border-indigo-100">
                    <p className="text-xs text-indigo-800 font-medium mb-1">Pro Tip</p>
                    <p className="text-xs text-slate-600">SMS notifications are the fastest way to receive critical predator or equipment failure alerts when you are in the field.</p>
                </div>
            </div>

            <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                <Shield size={18} className="text-slate-600" /> Security
                </h3>
                <div className="flex items-center justify-between py-2">
                    <div>
                        <p className="font-medium text-slate-700 text-sm">Two-Factor Auth</p>
                        <p className="text-xs text-slate-500">Extra layer of security</p>
                    </div>
                    <button className="text-emerald-600 font-medium text-xs hover:underline bg-emerald-50 px-3 py-1.5 rounded-full">Enable</button>
                </div>
                 <div className="flex items-center justify-between py-2 mt-2">
                    <div>
                        <p className="font-medium text-slate-700 text-sm">Farm Access Logs</p>
                        <p className="text-xs text-slate-500">View recent logins</p>
                    </div>
                    <button className="text-slate-600 font-medium text-xs hover:underline bg-slate-50 px-3 py-1.5 rounded-full">View</button>
                </div>
            </div>
        </div>

        {/* Specific Alert Config Column */}
        <div className="lg:col-span-2 space-y-6">

          {/* Crop Alerts */}
          <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
            <div className="flex items-center gap-3 mb-6 pb-4 border-b border-slate-100">
                <div className="p-2 bg-emerald-100 rounded-lg text-emerald-700">
                    <Sprout size={20} />
                </div>
                <div>
                    <h3 className="font-bold text-slate-800">Crop Alert Configuration</h3>
                    <p className="text-sm text-slate-500">Customize sensitivity for field monitoring</p>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-4">
               <Toggle 
                label="Water Stress & Irrigation" 
                checked={cropAlerts.irrigation} 
                onChange={(v: boolean) => setCropAlerts({...cropAlerts, irrigation: v})} 
              />
              <Toggle 
                label="Disease & Pest Detection" 
                checked={cropAlerts.disease} 
                onChange={(v: boolean) => setCropAlerts({...cropAlerts, disease: v})} 
              />
               <Toggle 
                label="Nutrient Deficiencies" 
                checked={cropAlerts.nutrients} 
                onChange={(v: boolean) => setCropAlerts({...cropAlerts, nutrients: v})} 
              />
              <Toggle 
                label="Drone/Sensor Equipment Status" 
                checked={cropAlerts.equipment} 
                onChange={(v: boolean) => setCropAlerts({...cropAlerts, equipment: v})} 
              />
            </div>
          </div>

          {/* Livestock Alerts */}
          <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
             <div className="flex items-center gap-3 mb-6 pb-4 border-b border-slate-100">
                <div className="p-2 bg-amber-100 rounded-lg text-amber-700">
                    <PawPrint size={20} />
                </div>
                <div>
                    <h3 className="font-bold text-slate-800">Livestock Alert Configuration</h3>
                    <p className="text-sm text-slate-500">Customize alerts for animal health and safety</p>
                </div>
            </div>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-4">
               <Toggle 
                label="Health Anomalies (Temp/HR)" 
                checked={livestockAlerts.health} 
                onChange={(v: boolean) => setLivestockAlerts({...livestockAlerts, health: v})} 
              />
              <Toggle 
                label="Estrus / Breeding Cycle" 
                checked={livestockAlerts.estrus} 
                onChange={(v: boolean) => setLivestockAlerts({...livestockAlerts, estrus: v})} 
              />
               <Toggle 
                label="Geofence / Perimeter Breach" 
                checked={livestockAlerts.perimeter} 
                onChange={(v: boolean) => setLivestockAlerts({...livestockAlerts, perimeter: v})} 
              />
              <Toggle 
                label="Predator Detection (Wolf/Coyote)" 
                checked={livestockAlerts.predator} 
                onChange={(v: boolean) => setLivestockAlerts({...livestockAlerts, predator: v})} 
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export enum HealthStatus {
  HEALTHY = 'Healthy',
  WARNING = 'Warning',
  CRITICAL = 'Critical',
  UNKNOWN = 'Unknown'
}

export enum AnalysisType {
  CROP = 'CROP',
  LIVESTOCK = 'LIVESTOCK'
}

export interface CropHistoryPoint {
  date: string; // ISO Date string
  ndvi: number;
}

export interface CropData {
  id: string;
  name: string;
  type: string;
  fieldId: string;
  plantingDate: string;
  healthScore: number; // 0-100
  ndvi: number; // -1 to 1
  soilMoisture: number; // %
  lastScanUrl?: string;
  status: HealthStatus;
  alerts: string[];
  history: CropHistoryPoint[]; // Historical data for graphs
}

export interface AnimalData {
  id: string;
  species: string;
  tagId: string;
  ageMonths: number;
  weightKg: number;
  temperature: number; // Celsius
  activityLevel: 'Resting' | 'Grazing' | 'Moving' | 'Agitated';
  healthScore: number;
  status: HealthStatus;
  lastCheckup: string;
  imageUrl?: string;
}

export interface WeatherData {
  location: string;
  temp: number;
  humidity: number;
  condition: string;
  windSpeed: number;
  rainfall: number;
}

export interface AIAnalysisResult {
  detectedSubject: string;
  condition: string;
  confidence: number;
  issues: string[];
  recommendations: string[];
  rawAnalysis: string;
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { 
  Upload, 
  Scan, 
  Droplets, 
  CheckCircle,
  FileText,
  Sprout,
  Loader2,
  Download,
  Settings,
  Map,
  Layers,
  ThermometerSun,
  Eye,
  Maximize2,
  Palette
} from 'lucide-react';
import { MOCK_CROPS } from '../constants';
import { CropData, HealthStatus, AIAnalysisResult } from '../types';
import { analyzeCropImage } from '../services/geminiService';
import { ApiService } from '../services/api';
import { dbService } from '../services/db';
import { ExportService } from '../services/exportService';
import { ResponsiveContainer, LineChart, Line, CartesianGrid, XAxis, YAxis, Tooltip, ReferenceLine } from 'recharts';
import { useNotifications } from '../context/NotificationContext';

type OverlayType = 'NONE' | 'NDVI' | 'THERMAL';
type NdviColorScheme = 'RG' | 'SPECTRAL' | 'DIVERGING';

export const CropDashboard: React.FC = () => {
  const { addNotification } = useNotifications();
  const [selectedCrop, setSelectedCrop] = useState<CropData | null>(null);
  const [crops, setCrops] = useState<CropData[]>(MOCK_CROPS);

  // Single Plant/Leaf Analysis State
  const [analysisImage, setAnalysisImage] = useState<string | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [analysisResult, setAnalysisResult] = useState<AIAnalysisResult | null>(null);

  // Map / Drone State
  const [mapImage, setMapImage] = useState<string>("https://images.unsplash.com/photo-1500382017468-9049fed747ef?ixlib=rb-4.0.3&auto=format&fit=crop&w=1600&q=80"); // Default placeholder
  const [overlayType, setOverlayType] = useState<OverlayType>('NONE');
  const [overlayOpacity, setOverlayOpacity] = useState(0.7);
  const [ndviColorScheme, setNdviColorScheme] = useState<NdviColorScheme>('RG');
  const mapInputRef = useRef<HTMLInputElement>(null);

  // NDVI Configuration State
  const [warningThreshold, setWarningThreshold] = useState(0.4);
  const [healthyThreshold, setHealthyThreshold] = useState(0.7);

  // Chart Interaction State
  const [draggingThreshold, setDraggingThreshold] = useState<'healthy' | 'warning' | null>(null);
  const chartContainerRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Load saved map from DB on mount
  useEffect(() => {
    const loadSavedMap = async () => {
        try {
            const saved = await dbService.getUpload('current-drone-map');
            if (saved) {
                setMapImage(saved.dataUrl);
            }
        } catch (e) {
            console.error("Failed to load saved map", e);
        }
    };
    loadSavedMap();
  }, []);

  // Set default selected crop once crops are loaded
  useEffect(() => {
    if (crops.length > 0 && !selectedCrop) {
        setSelectedCrop(crops[0]);
    }
  }, [crops, selectedCrop]);

  useEffect(() => {
    // Poll for live crop data
    const interval = setInterval(async () => {
      const data = await ApiService.getCrops();
      setCrops(data);
      // Update selected crop if it exists in the new data
      if (selectedCrop) {
        const updated = data.find(c => c.id === selectedCrop.id);
        if (updated) setSelectedCrop(updated);
      }
    }, 5000);
    return () => clearInterval(interval);
  }, [selectedCrop]);

  // Handle Dragging Logic for Chart Thresholds
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!draggingThreshold || !chartContainerRef.current) return;

      const rect = chartContainerRef.current.getBoundingClientRect();
      const marginTop = 20;
      const marginBottom = 30;
      const chartHeight = rect.height - marginTop - marginBottom;

      const relativeY = e.clientY - rect.top - marginTop;
      let newValue = 1 - (relativeY / chartHeight);

      newValue = Math.max(0, Math.min(1, newValue));
      newValue = Math.round(newValue * 100) / 100;

      if (draggingThreshold === 'healthy') {
        if (newValue > warningThreshold) setHealthyThreshold(newValue);
      } else {
        if (newValue < healthyThreshold) setWarningThreshold(newValue);
      }
    };

    const handleMouseUp = () => {
      if (draggingThreshold) {
         addNotification({
            title: 'Threshold Updated',
            message: `NDVI ${draggingThreshold} threshold adjusted.`,
            type: 'INFO'
         });
      }
      setDraggingThreshold(null);
    };

    if (draggingThreshold) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      document.body.style.userSelect = 'none';
    }

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
      document.body.style.userSelect = '';
    };
  }, [draggingThreshold, warningThreshold, healthyThreshold, addNotification]);

  // Derived state: Apply threshold logic to crops dynamically
  const displayedCrops = useMemo(() => {
    return crops.map(crop => {
        let dynamicStatus = HealthStatus.CRITICAL;
        if (crop.ndvi >= healthyThreshold) {
            dynamicStatus = HealthStatus.HEALTHY;
        } else if (crop.ndvi >= warningThreshold) {
            dynamicStatus = HealthStatus.WARNING;
        }
        return { ...crop, status: dynamicStatus };
    });
  }, [crops, warningThreshold, healthyThreshold]);

  // Image Upload Handlers
  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const result = reader.result as string;
        setAnalysisImage(result);
        setAnalysisResult(null); 
        // Save to DB
        await ApiService.saveImage(`analysis-${Date.now()}`, 'CROP', result);
        addNotification({
            title: 'Image Uploaded',
            message: 'Crop image ready for analysis.',
            type: 'INFO'
        });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleMapUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const result = reader.result as string;
        setMapImage(result);
        // Save to DB with a fixed ID so it persists as the current map
        await ApiService.saveImage('current-drone-map', 'MAP', result);
        addNotification({
            title: 'Drone Map Updated',
            message: 'New field map loaded successfully.',
            type: 'SUCCESS'
        });
      };
      reader.readAsDataURL(file);
    }
  };

  const triggerUpload = () => fileInputRef.current?.click();
  const triggerMapUpload = () => mapInputRef.current?.click();

  const runAnalysis = async () => {
    if (!analysisImage) return;
    setAnalyzing(true);
    addNotification({ title: 'Analysis Started', message: 'Processing image with Gemini Vision AI...', type: 'INFO' });

    try {
        const result = await analyzeCropImage(analysisImage.split(',')[1]);
        setAnalysisResult(result);
        addNotification({ 
            title: 'Analysis Complete', 
            message: `Identified: ${result.detectedSubject} (${result.confidence}%)`, 
            type: 'SUCCESS' 
        });
    } catch (e) {
        addNotification({ title: 'Analysis Failed', message: 'Could not process image.', type: 'WARNING' });
    } finally {
        setAnalyzing(false);
    }
  };

  const handleExportData = () => {
    const dataToExport = displayedCrops.map(c => ({
        ID: c.fieldId,
        Name: c.name,
        Type: c.type,
        NDVI: c.ndvi,
        Moisture: c.soilMoisture,
        Status: c.status,
        Alerts: c.alerts.join('; ')
    }));
    ExportService.exportToCSV(dataToExport, 'my_field_data.csv');
    addNotification({ title: 'Data Exported', message: 'Field data downloaded as CSV.', type: 'INFO' });
  };

  const handleDownloadPDF = () => {
    if (analysisResult && analysisImage) {
        ExportService.generateAnalysisPDF(analysisResult, analysisImage, `Crop Analysis: ${analysisResult.detectedSubject}`);
        addNotification({ title: 'Report Downloaded', message: 'PDF Analysis report generated.', type: 'SUCCESS' });
    }
  };

  // Helper to get colors for NDVI overlay
  const getNdviColors = (scheme: NdviColorScheme) => {
    switch(scheme) {
        case 'SPECTRAL': 
            return { 
                low: '#d946ef', // Fuchsia
                mid: '#f43f5e', // Rose
                high: '#3b82f6', // Blue
                bg: '#3b82f6',
                gradient: 'from-fuchsia-500 via-rose-500 to-blue-500',
                labels: ['Dense/Wet', 'Stress', 'Healthy']
            };
        case 'DIVERGING': 
            return { 
                low: '#b91c1c', // Dark Red
                mid: '#f3f4f6', // Gray/White
                high: '#15803d', // Dark Green
                bg: '#15803d',
                gradient: 'from-red-700 via-gray-100 to-green-700',
                labels: ['Dead/Soil', 'Mix', 'Lush']
            };
        case 'RG': 
        default: 
            return { 
                low: '#ef4444', // Red
                mid: '#eab308', // Yellow
                high: '#22c55e', // Green
                bg: '#22c55e',
                gradient: 'from-red-500 via-yellow-400 to-green-500',
                labels: ['Critical', 'Warning', 'Healthy']
            };
    }
  };

