                    </div>
                    <div className={`px-2 py-1 rounded text-xs font-bold ${
                        animal.status === HealthStatus.HEALTHY ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'
                    }`}>
                        {animal.status === HealthStatus.HEALTHY ? t('healthy') : t('warning')}
                    </div>
                    </div>

                    <div className="grid grid-cols-3 gap-2">
                        <div className="bg-slate-50 p-2 rounded border border-slate-100">
                            <div className="text-xs text-slate-500 flex items-center gap-1">
                                <Thermometer size={12} /> {t('temp')}
                            </div>
                            <div className={`font-semibold transition-colors ${animal.temperature > 39.5 ? 'text-rose-600' : 'text-slate-800'}`}>
                                {animal.temperature.toFixed(1)}°C
                            </div>
