export const LivestockDashboard: React.FC = () => {
  const { addNotification } = useNotifications();
  const { t } = useLanguage();

  // State for Real-time Data
  const [animals, setAnimals] = useState<AnimalData[]>(MOCK_ANIMALS);
  const [barnEnv, setBarnEnv] = useState({
      temp: 22.4,
      humidity: 45,
      co2: 412,
      quality: 'Good'
  });

  const [analyzingId, setAnalyzingId] = useState<string | null>(null);
  const [analysisResults, setAnalysisResults] = useState<Record<string, AIAnalysisResult>>({});
  const [showRecommendations, setShowRecommendations] = useState(false);
  const [recommendations, setRecommendations] = useState<any[]>([]);

  // Camera & Live Feed State
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isCameraActive, setIsCameraActive] = useState(false);
  const [cameraError, setCameraError] = useState<string | null>(null);
  const [feedMode, setFeedMode] = useState<'SIMULATION' | 'CAMERA'>('SIMULATION');
  const [viewMode, setViewMode] = useState<'NORMAL' | 'THERMAL'>('NORMAL');

  // AI Model State
  const [model, setModel] = useState<any>(null);
  const [modelLoading, setModelLoading] = useState(false);

  // Tracking State Refs
  const trackedObjectsRef = useRef<Map<number, TrackedObject>>(new Map());
  const nextObjectIdRef = useRef(1);
  const latestPredictionsRef = useRef<any[]>([]);
  const isDetectingRef = useRef(false);
  const requestRef = useRef<number>();
  const streamRef = useRef<MediaStream | null>(null);

  // --- Model Loading (Lazy) ---
  useEffect(() => {
    // Only load model if we switch to camera mode
    if (feedMode === 'CAMERA' && !model && !modelLoading) {
        const loadModel = async () => {
            setModelLoading(true);
            try {
                await tf.ready();
                const loadedModel = await cocoSsd.load({ base: 'lite_mobilenet_v2' });
                setModel(loadedModel);
                console.log("TensorFlow Lite Model Loaded");
            } catch (err) {
                console.error("Failed to load TensorFlow model", err);
                addNotification({ title: 'AI Error', message: 'Failed to load computer vision model.', type: 'WARNING' });
            } finally {
                setModelLoading(false);
            }
        };
        setTimeout(loadModel, 500);
    }
  }, [feedMode, model, modelLoading, addNotification]);

  // --- Real-time Data Simulation Loop (Sensors) ---
  useEffect(() => {
    const fetchBaseData = async () => {
      const data = await ApiService.getAnimals();
      setAnimals(data);
    };
    fetchBaseData();

    const animalInterval = setInterval(() => {
        setAnimals(prevAnimals => prevAnimals.map(animal => {
            const tempFluctuation = (Math.random() - 0.5) * 0.2;
            const weightFluctuation = (Math.random() - 0.5) * 0.05;

            let newTemp = parseFloat((animal.temperature + tempFluctuation).toFixed(1));
            if (newTemp < 37.5) newTemp = 37.5;
            if (newTemp > 41.0) newTemp = 41.0;

            let status = animal.status;
            let activity = animal.activityLevel;

            if (newTemp > 39.5 && status === HealthStatus.HEALTHY) {
                status = HealthStatus.WARNING;
                activity = 'Agitated';
            } else if (newTemp < 39.0 && status === HealthStatus.WARNING) {
                status = HealthStatus.HEALTHY;
            }

            return {
                ...animal,
                temperature: newTemp,
                weightKg: parseFloat((animal.weightKg + weightFluctuation).toFixed(2)),
                status: status,
                activityLevel: activity
            };
        }));
    }, SIMULATION_UPDATE_MS);

    const barnInterval = setInterval(() => {
        setBarnEnv(prev => {
            const tChange = (Math.random() - 0.5) * 0.1;
            const hChange = (Math.random() - 0.5) * 1;

            const newTemp = parseFloat((prev.temp + tChange).toFixed(1));
            const newHum = Math.round(prev.humidity + hChange);
            const newCo2 = Math.round(prev.co2 + (Math.random() - 0.5) * 5);

            let quality = 'Good';
            if (newCo2 > 1000) quality = 'Poor';
            else if (newCo2 > 600) quality = 'Fair';

            return {
                temp: newTemp,
                humidity: newHum,
                co2: newCo2,
                quality
            };
        });
    }, 5000);

    return () => {
        clearInterval(animalInterval);
        clearInterval(barnInterval);
    };
  }, []);

  // --- Live Camera Management ---

  // Clean up current stream logic
  const stopStream = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => {
        track.stop();
        streamRef.current?.removeTrack(track);
      });
      streamRef.current = null;
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
  };

  const startCamera = useCallback(async () => {
    // Stop any existing stream internally first
    stopStream();

    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        setCameraError("Camera API not supported in this browser");
        setFeedMode('SIMULATION');
        return;
    }

    try {
      let stream: MediaStream;

      try {
          stream = await navigator.mediaDevices.getUserMedia({ 
              video: { width: { ideal: 1280 }, height: { ideal: 720 }, facingMode: 'environment' } 
          });
      } catch (err) {
          console.warn("HD constraint failed, retrying with defaults...", err);
          stream = await navigator.mediaDevices.getUserMedia({ 
              video: { facingMode: 'environment' } 
          });
      }

      streamRef.current = stream;

      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.onloadedmetadata = async () => {
            try {
                await videoRef.current?.play();
                setIsCameraActive(true);
                setCameraError(null);
                addNotification({ title: 'Camera Active', message: 'Live AI surveillance feed started.', type: 'INFO' });
            } catch (playErr) {
                console.error("Video play failed", playErr);
                setCameraError("Video playback blocked");
            }
        };
      }
    } catch (err) {
      setCameraError("Camera unavailable. Another app may be using it.");
      console.error(err);
      setFeedMode('SIMULATION');
      addNotification({ title: 'Camera Failed', message: 'Could not access camera device.', type: 'WARNING' });
    }
  }, [addNotification]);

  useEffect(() => {
    let mounted = true;

    if (feedMode === 'CAMERA') {
      if (mounted) startCamera();
    } else {
      stopStream();
      setIsCameraActive(false);
    }

    return () => {
      mounted = false;
      stopStream();
    };
  }, [feedMode, startCamera]);

  // --- Utility Functions ---
  const getCenter = (bbox: [number, number, number, number]) => ({
    x: bbox[0] + bbox[2] / 2,
    y: bbox[1] + bbox[3] / 2
  });

  const getDistance = (p1: { x: number, y: number }, p2: { x: number, y: number }) => {
    return Math.sqrt(Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2));
  };

  const inferBehavior = (velocity: number, bbox: [number, number, number, number], canvasHeight: number): string => {
    const [, y, w, h] = bbox;
    const aspectRatio = w / h;
    const bottomY = y + h;
    if (velocity > 2.5) return "Walking";
    if (aspectRatio > 1.6) return "Resting";
    if (bottomY > canvasHeight * 0.85) return "Feeding";
    return "Standing";
  };

  const updateTrackedObjects = (predictions: any[], canvasHeight: number) => {
    const newTrackedMap = new Map<number, TrackedObject>();
    const currentFrameTime = Date.now();
    const matchThreshold = 150; 

    const detected = predictions.map(p => ({
      bbox: p.bbox,
      class: p.class,
      score: p.score,
      center: getCenter(p.bbox)
    }));

    const usedIndices = new Set<number>();

    trackedObjectsRef.current.forEach((trackedObj, id) => {
      let bestMatchIndex = -1;
      let minDist = Infinity;

      detected.forEach((det, idx) => {
        if (usedIndices.has(idx)) return;
        const dist = getDistance(trackedObj.center, det.center);
        if (dist < minDist && dist < matchThreshold) {
          minDist = dist;
          bestMatchIndex = idx;
        }
      });

      if (bestMatchIndex !== -1) {
        const match = detected[bestMatchIndex];
        const velocity = minDist;
        const behavior = inferBehavior(velocity, match.bbox, canvasHeight);

        newTrackedMap.set(id, {
          id,
          bbox: match.bbox,
          class: match.class,
          score: match.score,
          lastSeen: currentFrameTime,
          velocity,
          behavior,
          center: match.center
        });
        usedIndices.add(bestMatchIndex);
      } else {
        if (currentFrameTime - trackedObj.lastSeen < 800) {
           newTrackedMap.set(id, { ...trackedObj, velocity: 0 });
        }
      }
    });

    detected.forEach((det, idx) => {
      if (!usedIndices.has(idx)) {
        const id = nextObjectIdRef.current++;
        const behavior = inferBehavior(0, det.bbox, canvasHeight);
        newTrackedMap.set(id, {
          id,
          bbox: det.bbox,
          class: det.class,
          score: det.score,
          lastSeen: currentFrameTime,
          velocity: 0,
          behavior,
          center: det.center
        });
      }
    });

    trackedObjectsRef.current = newTrackedMap;
    return Array.from(newTrackedMap.values());
  };

  // --- Optimized Loop: Detection (Throttled) ---
  useEffect(() => {
    if (feedMode !== 'CAMERA' || !model || !isCameraActive) return;

    const intervalId = setInterval(async () => {
        if (isDetectingRef.current || !videoRef.current) return;

        isDetectingRef.current = true;
        try {
            if (videoRef.current.readyState === 4) {
                const predictions = await model.detect(videoRef.current);
                const relevantClasses = ['cow', 'sheep', 'horse', 'dog', 'cat', 'person', 'zebra', 'giraffe', 'elephant', 'bear'];
                latestPredictionsRef.current = predictions.filter((p: any) => relevantClasses.includes(p.class));
            }
        } catch (e) {
            console.warn("Detection error (skipped frame)", e);
        } finally {
            isDetectingRef.current = false;
        }
    }, DETECTION_INTERVAL_MS);

    return () => clearInterval(intervalId);
  }, [feedMode, model, isCameraActive]);

  // --- Optimized Loop: Rendering (60fps) ---
  useEffect(() => {
    const runLoop = () => {
        if (feedMode === 'SIMULATION') {
            renderSimulationFrame();
        } else if (feedMode === 'CAMERA' && isCameraActive) {
            renderCameraFrame();
        }
        requestRef.current = requestAnimationFrame(runLoop);
    };

    requestRef.current = requestAnimationFrame(runLoop);
    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [feedMode, viewMode, isCameraActive]);


  // --- Render Functions ---

  const renderCameraFrame = () => {
    const canvas = canvasRef.current;
    const video = videoRef.current;
    if (!canvas || !video) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    if (video.readyState === 4) {
        if (canvas.width !== video.videoWidth || canvas.height !== video.videoHeight) {
            canvas.width = video.videoWidth;
            canvas.height = video.videoHeight;
        }
    }

    const trackedObjects = updateTrackedObjects(latestPredictionsRef.current, canvas.height);

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (trackedObjects.length > 0) {
        trackedObjects.forEach((obj) => {
            drawObjectOverlay(ctx, obj, viewMode);
        });

        if (viewMode === 'THERMAL') {
                ctx.fillStyle = 'rgba(0, 0, 50, 0.3)'; 
                ctx.globalCompositeOperation = 'destination-over';
                ctx.fillRect(0, 0, canvas.width, canvas.height);
                ctx.globalCompositeOperation = 'source-over';
        }
    }
  };

  const simTargetsRef = useRef([
    { ...MOCK_ANIMALS[0], x: 20, y: 30, dx: 0.2 },
    { ...MOCK_ANIMALS[1], x: 60, y: 50, dx: 0 }
  ]);

  const renderSimulationFrame = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    if (canvas.width !== 800) { canvas.width = 800; canvas.height = 450; }

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    simTargetsRef.current.forEach((target) => {
        if (Math.random() > 0.98) {
            target.dx = (Math.random() - 0.5) * 1.5;
        }
        target.x += target.dx;
        if (target.x < 5 || target.x > 85) target.dx *= -1;
    });

    simTargetsRef.current.forEach((target, i) => {
        const liveData = animals.find(a => a.id === target.id) || target;

        const boxX = (target.x / 100) * canvas.width;
        const boxY = (target.y / 100) * canvas.height;
        const boxW = 120;
        const boxH = 80;

        if (viewMode === 'THERMAL') {
            const centerX = boxX + boxW / 2;
            const centerY = boxY + boxH / 2;
            const gradient = ctx.createRadialGradient(centerX, centerY, 5, centerX, centerY, boxW);

            gradient.addColorStop(0, liveData.temperature > 39 ? '#ef4444' : '#f97316'); 
            gradient.addColorStop(1, 'rgba(0,0,255,0)');

            ctx.fillStyle = gradient;
            ctx.fillRect(boxX - 30, boxY - 30, boxW + 60, boxH + 60);

            ctx.fillStyle = '#fff';
            ctx.font = 'bold 12px monospace';
            ctx.fillText(`${liveData.temperature.toFixed(1)}°C`, boxX, boxY - 10);
        } else {
            ctx.strokeStyle = liveData.status === HealthStatus.HEALTHY ? '#10b981' : '#f59e0b';
            ctx.lineWidth = 2;
            ctx.strokeRect(boxX, boxY, boxW, boxH);

            ctx.fillStyle = liveData.status === HealthStatus.HEALTHY ? '#10b981' : '#f59e0b';
            ctx.fillRect(boxX, boxY - 24, boxW, 24);

            ctx.fillStyle = '#ffffff';
            ctx.font = 'bold 12px Inter, sans-serif';
            ctx.textAlign = 'left'; 
            ctx.fillText(liveData.tagId, boxX + 5, boxY - 8);

            ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
            ctx.font = '11px Inter, sans-serif';
            ctx.fillText(`Status: ${liveData.status}`, boxX + 5, boxY + 15);
            ctx.fillStyle = '#fbbf24'; 
            ctx.font = 'bold 11px Inter, sans-serif';
            ctx.fillText(`Temp: ${liveData.temperature.toFixed(1)}°C`, boxX + 5, boxY + 28);
        }
    });

    if (viewMode === 'THERMAL') {
        ctx.fillStyle = 'rgba(0, 20, 60, 0.4)'; 
        ctx.globalCompositeOperation = 'destination-over';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.globalCompositeOperation = 'source-over';
    }

    const time = Date.now() / 1500;
    const scanY = (Math.sin(time) + 1) / 2 * canvas.height;
    ctx.strokeStyle = viewMode === 'THERMAL' ? 'rgba(255, 100, 0, 0.3)' : 'rgba(99, 102, 241, 0.3)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(0, scanY);
    ctx.lineTo(canvas.width, scanY);
    ctx.stroke();
  };

  const drawObjectOverlay = (ctx: CanvasRenderingContext2D, obj: TrackedObject, mode: string) => {
    const [x, y, width, height] = obj.bbox;
    const isAnimal = obj.class !== 'person';

    if (mode === 'THERMAL') {
        const centerX = x + width / 2;
        const centerY = y + height / 2;
        const radius = Math.max(width, height) / 1.5;

        const gradient = ctx.createRadialGradient(centerX, centerY, 1, centerX, centerY, radius);

        if (isAnimal) {
            gradient.addColorStop(0, 'rgba(255, 0, 0, 0.8)');
            gradient.addColorStop(0.5, 'rgba(255, 165, 0, 0.5)');
            gradient.addColorStop(1, 'rgba(0, 0, 255, 0)');
        } else {
            gradient.addColorStop(0, 'rgba(255, 140, 0, 0.8)');
            gradient.addColorStop(1, 'rgba(0, 0, 255, 0)');
        }

        ctx.fillStyle = gradient;
        ctx.fillRect(x - width/2, y - height/2, width * 2, height * 2);

        ctx.fillStyle = '#ffffff';
        ctx.font = 'bold 12px monospace';
        const tempSim = isAnimal ? (38 + Math.random()).toFixed(1) : (36 + Math.random()).toFixed(1);
        ctx.fillText(`${tempSim}°C`, x, y - 5);
    } else {
        const color = isAnimal ? '#10b981' : '#f59e0b';

        ctx.strokeStyle = color;
        ctx.lineWidth = 3;
        ctx.strokeRect(x, y, width, height);

        const labelText = `${obj.class.toUpperCase()}: ${obj.behavior}`;
        const textWidth = ctx.measureText(labelText).width;

        ctx.fillStyle = color;
        ctx.fillRect(x, y - 25, textWidth + 20, 25);

        ctx.fillStyle = '#ffffff';
        ctx.font = 'bold 14px Inter, sans-serif';
        ctx.textAlign = 'left';
        ctx.fillText(labelText, x + 5, y - 7);

        ctx.fillStyle = 'rgba(255,255,255,0.8)';
        ctx.font = '10px Inter, sans-serif';
        ctx.fillText(`${Math.round(obj.score * 100)}%`, x + 5, y + 15);
    }
  };

  const handleScanAnimal = async (animal: AnimalData) => {
    if (!animal.imageUrl) return;
    setAnalyzingId(animal.id);
    addNotification({ title: 'Scanning Animal', message: `AI analysis started for ${animal.tagId}`, type: 'INFO' });

    try {
        const response = await fetch(animal.imageUrl);
        const blob = await response.blob();
        const reader = new FileReader();
        reader.onloadend = async () => {
            const base64 = reader.result as string;
            const result = await analyzeLivestockFrame(base64.split(',')[1]);
            setAnalysisResults(prev => ({ ...prev, [animal.id]: result }));
            setAnalyzingId(null);
            addNotification({ title: 'Scan Complete', message: `Health insights ready for ${animal.tagId}`, type: 'SUCCESS' });
        };
        reader.readAsDataURL(blob);
    } catch (e) {
        console.error("Error analyzing animal", e);
        setAnalyzingId(null);
        addNotification({ title: 'Scan Failed', message: `Could not analyze ${animal.tagId}`, type: 'WARNING' });
    }
  };

  const handleExportData = () => {
    const dataToExport = animals.map(a => ({
        Tag: a.tagId,
        Species: a.species,
        Age: a.ageMonths,
        Weight: a.weightKg,
        Temp: a.temperature,
        Activity: a.activityLevel,
        Status: a.status,
        Timestamp: new Date().toISOString()
    }));
    ExportService.exportToCSV(dataToExport, 'livestock_metrics_live.csv');
    addNotification({ title: 'Data Exported', message: 'Livestock metrics CSV downloaded with real-time values.', type: 'INFO' });
  };

  const handleViewRecommendations = async () => {
    setShowRecommendations(true);
    const realTimeRecs = animals
        .filter(a => a.temperature > 39 || a.activityLevel === 'Agitated')
        .map(a => {
            const isEstrus = a.temperature > 38.5 && a.activityLevel === 'Agitated';
            const isSick = a.temperature > 39.5 && a.activityLevel === 'Resting';

            return {
                id: a.id,
                animalId: a.tagId,
                confidence: isEstrus ? 92 : (isSick ? 88 : 65),
                window: isEstrus ? 'Now - 12h' : 'Immediate',
                note: isEstrus ? t('estrus_detected') : (isSick ? t('high_temp_alert') : 'Monitor closely')
            };
        });

    if (realTimeRecs.length === 0) {
        setRecommendations([{ id: 'none', animalId: 'N/A', confidence: 100, window: '-', note: 'No anomalies detected in herd.' }]);
    } else {
        setRecommendations(realTimeRecs);
    }
  };

  const calculatedHealthData = useMemo(() => {
    const currentAvgScore = animals.reduce((acc, curr) => acc + curr.healthScore, 0) / animals.length;
    const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
    return days.map((day, i) => ({
        name: day,
        score: Math.round(currentAvgScore + Math.sin(i) * 5)
    }));
  }, [animals]);

  const breedingCount = animals.filter(a => a.temperature > 38.5 && a.activityLevel === 'Agitated').length;

  return (
    <div className="space-y-6 relative">
      {/* Recommendations Modal */}
      {showRecommendations && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-fade-in">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-md overflow-hidden">
                <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-indigo-600 text-white">
                    <h3 className="font-bold flex items-center gap-2">
                        <HeartPulse size={20} /> {t('breeding_cycle')}
                    </h3>
                    <button onClick={() => setShowRecommendations(false)} className="hover:bg-indigo-700 p-1 rounded-full">
                        <X size={20} />
                    </button>
                </div>
                <div className="p-4 space-y-3">
                    {recommendations.length === 0 ? (
                        <div className="text-center py-8 text-slate-500">Loading insights...</div>
                    ) : (
                        recommendations.map(rec => (
                            <div key={rec.id} className="p-3 bg-indigo-50 rounded-lg border border-indigo-100">
                                <div className="flex justify-between mb-1">
                                    <span className="font-bold text-indigo-900">{rec.animalId}</span>
                                    <span className="text-xs bg-white px-2 py-0.5 rounded text-indigo-600 font-bold border border-indigo-200">
                                        {rec.confidence}% {t('confidence')}
                                    </span>
                                </div>
                                <p className="text-sm text-slate-700 mb-1">Window: <span className="font-semibold">{rec.window}</span></p>
                                <p className="text-xs text-slate-500">{rec.note}</p>
                            </div>
                        ))
                    )}
                </div>
                <div className="p-4 bg-slate-50 text-center">
                    <button onClick={() => setShowRecommendations(false)} className="text-sm text-indigo-600 font-medium hover:underline">
                        Close Insights
                    </button>
                </div>
            </div>
        </div>
      )}

      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">{t('livestock_monitoring')}</h1>
          <p className="text-slate-500">{t('livestock_subtitle')}</p>
        </div>
        <div className="flex items-center space-x-2">
            <button 
                onClick={handleExportData}
                className="flex items-center space-x-2 px-4 py-2 bg-white border border-slate-300 rounded-lg text-sm font-medium hover:bg-slate-50 transition-colors"
            >
                <FileText size={16} />
                <span>{t('export_csv')}</span>
            </button>
        </div>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">

        {/* Main Column */}
        <div className="xl:col-span-2 space-y-6">

            {/* Live Surveillance Feed */}
            <div className="bg-slate-900 rounded-xl overflow-hidden shadow-lg border border-slate-700 relative group">
                <div className="p-3 bg-black/40 backdrop-blur absolute top-0 left-0 right-0 z-10 flex justify-between items-center border-b border-white/10">
                    <div className="flex items-center gap-2">
                        <div className="flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-red-500/20 text-red-500 border border-red-500/30">
                            <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse" />
                            <span className="text-xs font-bold tracking-wide">LIVE</span>
                        </div>
                        <span className="text-slate-200 text-sm font-medium">{t('live_feed')}</span>
                    </div>

                    <div className="flex items-center gap-2">
                         <button
                            onClick={() => setViewMode(prev => prev === 'NORMAL' ? 'THERMAL' : 'NORMAL')}
                            className={`flex items-center gap-1 px-3 py-1 rounded-md text-xs font-medium transition-all mr-2 ${viewMode === 'THERMAL' ? 'bg-orange-600 text-white' : 'bg-slate-700 text-slate-300'}`}
                         >
                            {viewMode === 'THERMAL' ? <Flame size={12} /> : <Eye size={12} />}
                            {viewMode === 'THERMAL' ? t('thermal_vision') : t('normal_vision')}
                         </button>

                        {modelLoading && feedMode === 'CAMERA' && (
                             <span className="text-xs text-yellow-400 flex items-center gap-1 animate-pulse mr-2">
                                <Loader2 size={12} className="animate-spin" /> Init AI...
                             </span>
                        )}
                        <div className="flex bg-slate-800 rounded-lg p-0.5 border border-slate-700">
                            <button 
                                onClick={() => setFeedMode('SIMULATION')}
                                className={`px-3 py-1 rounded-md text-xs font-medium transition-all ${feedMode === 'SIMULATION' ? 'bg-slate-600 text-white shadow' : 'text-slate-400 hover:text-slate-200'}`}
                            >
                                {t('simulation')}
                            </button>
                            <button 
                                onClick={() => setFeedMode('CAMERA')}
                                className={`px-3 py-1 rounded-md text-xs font-medium transition-all ${feedMode === 'CAMERA' ? 'bg-indigo-600 text-white shadow' : 'text-slate-400 hover:text-slate-200'}`}
                            >
                                {t('camera')}
                            </button>
                        </div>
                    </div>
                </div>

                <div className="relative aspect-video bg-black flex items-center justify-center">
                    {feedMode === 'CAMERA' ? (
                        <video 
                            ref={videoRef}
                            autoPlay 
                            muted 
                            playsInline 
                            className="w-full h-full object-cover"
                            style={{ filter: viewMode === 'THERMAL' ? 'grayscale(100%) contrast(120%)' : 'none' }} 
                        />
                    ) : (
                        <div className="w-full h-full relative">
                            <img 
                                src="https://images.unsplash.com/photo-1545464528-6c82a5a5198e?auto=format&fit=crop&q=80&w=1600" 
                                className="w-full h-full object-cover opacity-60"
                                style={{ filter: viewMode === 'THERMAL' ? 'grayscale(100%) contrast(120%)' : 'none' }}
                                alt="Simulation Background"
                            />
                            <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                                <p className="text-slate-400 text-sm font-mono tracking-widest uppercase">Simulation Feed Active</p>
                            </div>
                        </div>
                    )}

                    <canvas 
                        ref={canvasRef}
                        className="absolute inset-0 pointer-events-none w-full h-full"
                        width={800}
                        height={450}
                        style={{ mixBlendMode: viewMode === 'THERMAL' ? 'screen' : 'normal' }}
                    />

                    {cameraError && (
                        <div className="absolute inset-0 flex items-center justify-center bg-black/80 z-20">
                            <div className="text-center p-6 bg-slate-800 rounded-xl border border-red-500/50 max-w-sm">
                                <Video size={48} className="mx-auto text-red-500 mb-4" />
                                <h3 className="text-white font-bold mb-2">Camera Unavailable</h3>
                                <p className="text-slate-400 text-sm mb-4">{cameraError}</p>
                                <button 
                                    onClick={() => setFeedMode('SIMULATION')}
                                    className="px-4 py-2 bg-slate-700 hover:bg-slate-600 text-white rounded-lg text-sm font-medium transition-colors"
                                >
                                    Switch to Simulation
                                </button>
                            </div>
                        </div>
                    )}
                </div>

                <div className="p-3 bg-slate-900 border-t border-slate-800 flex justify-between text-xs text-slate-400">
                    <div className="flex gap-4">
                        <span className="flex items-center gap-1"><Scan size={14} className="text-indigo-400" /> {t('obj_detection')}: {model ? 'ON' : 'OFF'}</span>
                        <span className="flex items-center gap-1"><Activity size={14} className="text-emerald-400" /> {t('behavior_analysis')}: ACTIVE</span>
                    </div>
                    <div className="flex gap-4 font-mono">
                        <span>FPS: {feedMode === 'CAMERA' ? 'Live (Optimized)' : '60'}</span>
                    </div>
                </div>
            </div>

            {/* Individual Animal Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {animals.map((animal) => (
                <div key={animal.id} className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden hover:shadow-md transition-shadow">
                <div className="relative aspect-video bg-slate-900 group">
                    <img 
                        src={animal.imageUrl} 
                        alt={animal.species} 
                        className="w-full h-full object-cover opacity-90 group-hover:opacity-100 transition-opacity"
                    />

                    <div className="absolute bottom-0 left-0 right-0 p-2 bg-gradient-to-t from-black/80 to-transparent flex justify-between items-end text-white text-xs">
                        <span className="flex items-center gap-1">
                            <Thermometer size={12} className={animal.temperature > 39 ? 'text-red-400' : 'text-emerald-400'} />
                            {animal.temperature.toFixed(1)}°C
                        </span>
                        <span>LIVE</span>
                    </div>

                    <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity bg-black/20 backdrop-blur-[1px]">
                        <button 
                            onClick={() => handleScanAnimal(animal)}
                            disabled={analyzingId === animal.id}
                            className="bg-white text-slate-900 px-4 py-2 rounded-full font-medium shadow-lg hover:scale-105 transition-transform flex items-center gap-2"
                        >
                            {analyzingId === animal.id ? (
                                <span className="animate-spin">⌛</span>
                            ) : (
                                <Camera size={18} />
                            )}
                            <span>{t('quick_scan')}</span>
                        </button>
                    </div>
                </div>

                {analysisResults[animal.id] && (
                    <div className="bg-indigo-50 p-3 border-b border-indigo-100 animate-fade-in">
                        <p className="text-sm font-bold text-indigo-900 mb-1">AI Insight:</p>
                        <p className="text-xs text-indigo-800 leading-relaxed mb-2">
                            {analysisResults[animal.id].condition} - {analysisResults[animal.id].issues[0] || "No issues detected"}
                        </p>
                        <div className="flex flex-wrap gap-1">
                            {analysisResults[animal.id].recommendations.slice(0, 2).map((rec, i) => (
                                <span key={i} className="text-[10px] bg-white border border-indigo-200 px-2 py-0.5 rounded text-indigo-700">
                                    {rec}
                                </span>
                            ))}
                        </div>
                    </div>
                )}

                <div className="p-4">
                    <div className="flex justify-between items-start mb-4">
                    <div>
                        <h3 className="font-bold text-slate-900">{animal.tagId}</h3>
                        <p className="text-xs text-slate-500">{animal.species} • {animal.ageMonths} mo</p>
                    </div>
                    <div className={`px-2 py-1 rounded text-xs font-bold ${
                        animal.status === HealthStatus.HEALTHY ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'
                    }`}>
                        {animal.status === HealthStatus.HEALTHY ? t('healthy') : t('warning')}
                    </div>
                    </div>

                    <div className="grid grid-cols-3 gap-2">
                        <div className="bg-slate-50 p-2 rounded border border-slate-100">
                            <div className="text-xs text-slate-500 flex items-center gap-1">
                                <Thermometer size={12} /> {t('temp')}
                            </div>
                            <div className={`font-semibold transition-colors ${animal.temperature > 39.5 ? 'text-rose-600' : 'text-slate-800'}`}>
                                {animal.temperature.toFixed(1)}°C
                            </div>
                        </div>
                        <div className="bg-slate-50 p-2 rounded border border-slate-100">
                            <div className="text-xs text-slate-500 flex items-center gap-1">
                                <Activity size={12} /> Activity
                            </div>
                            <div className="font-semibold text-slate-800">{animal.activityLevel}</div>
                        </div>
                        <div className="bg-slate-50 p-2 rounded border border-slate-100">
                            <div className="text-xs text-slate-500 flex items-center gap-1">
                                <Video size={12} /> Weight
                            </div>
                            <div className="font-semibold text-slate-800">{animal.weightKg}kg</div>
                        </div>
                    </div>
                </div>
                </div>
            ))}
            </div>
        </div>

        {/* Sidebar Stats */}
        <div className="space-y-6">
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
                <h3 className="font-semibold text-slate-800 mb-4">{t('herd_health')}</h3>
                <div className="h-48">
                    <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={calculatedHealthData}>
                            <XAxis dataKey="name" fontSize={10} tickLine={false} axisLine={false} />
                            <Tooltip cursor={{fill: 'transparent'}} contentStyle={{borderRadius: '8px', border:'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}} />
                            <Bar dataKey="score" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={20} />
                        </BarChart>
                    </ResponsiveContainer>
                </div>
                <div className="mt-4 pt-4 border-t border-slate-100">
                    <div className="flex justify-between items-center text-sm">
                        <span className="text-slate-500">Avg. Daily Gain</span>
                        <span className="font-medium text-emerald-600">+1.2 kg</span>
                    </div>
                    <div className="flex justify-between items-center text-sm mt-2">
                        <span className="text-slate-500">Predicted Yield</span>
                        <span className="font-medium text-blue-600">High</span>
                    </div>
                </div>
            </div>

            <div className="bg-gradient-to-br from-indigo-600 to-purple-700 p-6 rounded-xl shadow-lg text-white">
                <div className="flex items-start justify-between">
                    <div>
                        <h3 className="font-bold text-lg mb-1">{t('breeding_cycle')}</h3>
                        <p className="text-indigo-100 text-sm">Real-time AI Analysis</p>
                    </div>
                    <div className="bg-white/20 p-2 rounded-lg">
                        <Activity size={20} />
                    </div>
                </div>
                <div className="mt-6">
                    <p className="text-3xl font-bold">{breedingCount}</p>
                    <p className="text-sm text-indigo-200">Animals showing high activity & heat signs</p>
                </div>
                <button 
                  onClick={handleViewRecommendations}
                  className="mt-4 w-full py-2 bg-white/10 hover:bg-white/20 rounded-lg text-sm font-medium transition-colors"
                >
                    {t('view_recs')}
                </button>
            </div>

            {/* Environmental Stats */}
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
                 <div className="flex justify-between items-center mb-4">
                     <h3 className="font-semibold text-slate-800">{t('barn_env')}</h3>
                     <span className="text-xs text-green-600 bg-green-50 px-2 py-1 rounded-full flex items-center gap-1 animate-pulse">
                         <div className="w-1.5 h-1.5 bg-green-600 rounded-full"></div> Live
                     </span>
                 </div>
                 <div className="space-y-4">
                     <div className="flex items-center justify-between">
                         <div className="flex items-center gap-2 text-slate-600">
                             <Thermometer size={16} /> <span className="text-sm">{t('temp')}</span>
                         </div>
                         <span className="font-mono font-medium text-slate-900">{barnEnv.temp}°C</span>
                     </div>
                     <div className="w-full bg-slate-100 rounded-full h-1.5">
                         <div className="bg-emerald-500 h-1.5 rounded-full transition-all duration-1000" style={{width: `${(barnEnv.temp / 40) * 100}%`}}></div>
                     </div>

                     <div className="flex items-center justify-between mt-2">
                         <div className="flex items-center gap-2 text-slate-600">
                             <Activity size={16} /> <span className="text-sm">{t('weather_humidity')}</span>
                         </div>
                         <span className="font-mono font-medium text-slate-900">{barnEnv.humidity}%</span>
                     </div>
                     <div className="w-full bg-slate-100 rounded-full h-1.5">
                         <div className="bg-blue-500 h-1.5 rounded-full transition-all duration-1000" style={{width: `${barnEnv.humidity}%`}}></div>
                     </div>

                     <div className="flex items-center justify-between mt-2">
                         <div className="flex items-center gap-2 text-slate-600">
                             <Power size={16} /> <span className="text-sm">{t('air_quality')}</span>
                         </div>
                         <span className={`font-mono font-medium ${barnEnv.quality === 'Good' ? 'text-emerald-600' : 'text-amber-600'}`}>{barnEnv.quality}</span>
                     </div>
                 </div>
            </div>
        </div>
      </div>
    </div>
  );
};

export enum HealthStatus {
  HEALTHY = 'Healthy',
  WARNING = 'Warning',
  CRITICAL = 'Critical',
  UNKNOWN = 'Unknown'
}

export enum AnalysisType {
  CROP = 'CROP',
  LIVESTOCK = 'LIVESTOCK'
}

export interface CropHistoryPoint {
  date: string; // ISO Date string
  ndvi: number;
}

export interface CropData {
  id: string;
  name: string;
  type: string;
  fieldId: string;
  plantingDate: string;
  healthScore: number; // 0-100
  ndvi: number; // -1 to 1
  soilMoisture: number; // %
  lastScanUrl?: string;
  status: HealthStatus;
  alerts: string[];
  history: CropHistoryPoint[]; // Historical data for graphs
}

export interface GeoLocation {
  lat: number;
  lng: number;
}

export interface LocationHistoryPoint extends GeoLocation {
  timestamp: string;
}

export interface AnimalData {
  id: string;
  species: string;
  breed?: string; // Specific breed identification
  tagId: string;
  ageMonths: number;
  weightKg: number;
  temperature: number; // Celsius
  activityLevel: 'Resting' | 'Grazing' | 'Moving' | 'Agitated';
  healthScore: number;
  status: HealthStatus;
  lastCheckup: string;
  imageUrl?: string;
  location: GeoLocation;
  locationHistory: LocationHistoryPoint[];
}

export interface WeatherData {
  location: string;
  temp: number;
  humidity: number;
  condition: string;
  windSpeed: number;
  rainfall: number;
}

export interface AIAnalysisResult {
  detectedSubject: string;
  condition: string;
  confidence: number;
  issues: string[];
  recommendations: string[];
  rawAnalysis: string;
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { 
  Activity, 
  Thermometer, 
  Video,
  Camera,
  X,
  HeartPulse,
  Power,
  Scan,
  Loader2,
  FileText,
  Flame,
  Eye,
  Map as MapIcon,
  Navigation,
  Crosshair
} from 'lucide-react';
import { MOCK_ANIMALS } from '../constants';
import { AnimalData, HealthStatus, AIAnalysisResult, GeoLocation } from '../types';
import { analyzeLivestockFrame } from '../services/geminiService';
import { ApiService } from '../services/api';
import { ExportService } from '../services/exportService';
import { BarChart, Bar, XAxis, Tooltip, ResponsiveContainer } from 'recharts';
import { useNotifications } from '../context/NotificationContext';
import { useLanguage } from '../context/LanguageContext';

// @ts-ignore
import * as tf from '@tensorflow/tfjs';
// @ts-ignore
import * as cocoSsd from '@tensorflow-models/coco-ssd';

// Performance Configuration
const DETECTION_INTERVAL_MS = 200; // Cap AI to 5 FPS to reduce load
const SIMULATION_UPDATE_MS = 2000;
// Higher threshold to reduce false positives
const CONFIDENCE_THRESHOLD = 0.65; 

// Tracking Types
interface TrackedObject {
  id: number;
  bbox: [number, number, number, number]; // x, y, w, h
  class: string;
  breed?: string; // Inferred breed
  score: number;
  lastSeen: number;
  velocity: number;
  behavior: string;
  center: { x: number, y: number };
}

export const LivestockDashboard: React.FC = () => {
  const { addNotification } = useNotifications();
  const { t } = useLanguage();

  // State for Real-time Data
  const [animals, setAnimals] = useState<AnimalData[]>(MOCK_ANIMALS);
  const [barnEnv, setBarnEnv] = useState({
      temp: 22.4,
      humidity: 45,
      co2: 412,
      quality: 'Good'
  });

  const [analyzingId, setAnalyzingId] = useState<string | null>(null);
  const [analysisResults, setAnalysisResults] = useState<Record<string, AIAnalysisResult>>({});
  const [showRecommendations, setShowRecommendations] = useState(false);
  const [recommendations, setRecommendations] = useState<any[]>([]);

  // Camera & Live Feed State
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const mapCanvasRef = useRef<HTMLCanvasElement>(null);

  const [isCameraActive, setIsCameraActive] = useState(false);
  const [cameraError, setCameraError] = useState<string | null>(null);
  const [feedMode, setFeedMode] = useState<'SIMULATION' | 'CAMERA'>('SIMULATION');
  const [viewMode, setViewMode] = useState<'NORMAL' | 'THERMAL' | 'MAP'>('NORMAL');
  const [isAnyAnimalDetected, setIsAnyAnimalDetected] = useState(false);

  // AI Model State
  const [model, setModel] = useState<any>(null);
  const [modelLoading, setModelLoading] = useState(false);

  // Tracking State Refs
  const trackedObjectsRef = useRef<Map<number, TrackedObject>>(new Map());
  const nextObjectIdRef = useRef(1);
  const latestPredictionsRef = useRef<any[]>([]);
  const isDetectingRef = useRef(false);
  const requestRef = useRef<number>();
  const streamRef = useRef<MediaStream | null>(null);

  // Map settings
  const FARM_CENTER = { lat: 36.7378, lng: -119.7871 };
  const MAP_ZOOM_FACTOR = 150000; // Multiplier for gps to pixel conversion

  // --- Model Loading (Lazy) ---
  useEffect(() => {
    if (feedMode === 'CAMERA' && !model && !modelLoading) {
        const loadModel = async () => {
            setModelLoading(true);
            try {
                await tf.ready();
                // Load lite_mobilenet_v2 for speed
                const loadedModel = await cocoSsd.load({ base: 'lite_mobilenet_v2' });
                setModel(loadedModel);
                console.log("TensorFlow Lite Model Loaded");
            } catch (err) {
                console.error("Failed to load TensorFlow model", err);
                addNotification({ title: 'AI Error', message: 'Failed to load computer vision model.', type: 'WARNING' });
            } finally {
                setModelLoading(false);
            }
        };
        setTimeout(loadModel, 500);
    }
  }, [feedMode, model, modelLoading, addNotification]);

  // --- Real-time Data Simulation Loop (Sensors & GPS) ---
  useEffect(() => {
    const fetchBaseData = async () => {
      const data = await ApiService.getAnimals();
      setAnimals(data);
    };
    fetchBaseData();

    // 1. Live Animal Telemetry & GPS Simulation
    const animalInterval = setInterval(() => {
        setAnimals(prevAnimals => prevAnimals.map(animal => {
            const tempFluctuation = (Math.random() - 0.5) * 0.2;
            const weightFluctuation = (Math.random() - 0.5) * 0.05;

            // Temperature update
            let newTemp = parseFloat((animal.temperature + tempFluctuation).toFixed(1));
            if (newTemp < 37.5) newTemp = 37.5;
            if (newTemp > 41.0) newTemp = 41.0;

            let status = animal.status;
            let activity = animal.activityLevel;

            if (newTemp > 39.5 && status === HealthStatus.HEALTHY) {
                status = HealthStatus.WARNING;
                activity = 'Agitated';
            } else if (newTemp < 39.0 && status === HealthStatus.WARNING) {
                status = HealthStatus.HEALTHY;
            }

            // GPS Movement Simulation (Random walk)
            const moveLat = (Math.random() - 0.5) * 0.0001;
            const moveLng = (Math.random() - 0.5) * 0.0001;

            const newLocation = {
                lat: (animal.location?.lat || FARM_CENTER.lat) + moveLat,
                lng: (animal.location?.lng || FARM_CENTER.lng) + moveLng
            };

            // Maintain history trail (keep last 20 points)
            const newHistoryPoint = { ...newLocation, timestamp: new Date().toISOString() };
            const history = animal.locationHistory ? [...animal.locationHistory, newHistoryPoint] : [newHistoryPoint];
            if (history.length > 20) history.shift();

            return {
                ...animal,
                temperature: newTemp,
                weightKg: parseFloat((animal.weightKg + weightFluctuation).toFixed(2)),
                status: status,
                activityLevel: activity,
                location: newLocation,
                locationHistory: history
            };
        }));
    }, SIMULATION_UPDATE_MS);

    // 2. Barn Environment Sensors
    const barnInterval = setInterval(() => {
        setBarnEnv(prev => {
            const tChange = (Math.random() - 0.5) * 0.1;
            const hChange = (Math.random() - 0.5) * 1;
            const newTemp = parseFloat((prev.temp + tChange).toFixed(1));
            const newHum = Math.round(prev.humidity + hChange);
            const newCo2 = Math.round(prev.co2 + (Math.random() - 0.5) * 5);
            let quality = 'Good';
            if (newCo2 > 1000) quality = 'Poor';
            else if (newCo2 > 600) quality = 'Fair';
            return { temp: newTemp, humidity: newHum, co2: newCo2, quality };
        });
    }, 5000);

    return () => {
        clearInterval(animalInterval);
        clearInterval(barnInterval);
    };
  }, []);

  // --- Live Camera Management ---
  const stopStream = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => {
        track.stop();
        streamRef.current?.removeTrack(track);
      });
      streamRef.current = null;
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
  };

  const startCamera = useCallback(async () => {
    stopStream();
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        setCameraError("Camera API not supported");
        setFeedMode('SIMULATION');
        return;
    }

    try {
      let stream: MediaStream;
      try {
          stream = await navigator.mediaDevices.getUserMedia({ 
              video: { width: { ideal: 1280 }, height: { ideal: 720 }, facingMode: 'environment' } 
          });
      } catch (err) {
          console.warn("HD constraint failed, retrying defaults...", err);
          stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      }

      streamRef.current = stream;

      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.onloadedmetadata = async () => {
            try {
                await videoRef.current?.play();
                setIsCameraActive(true);
                setCameraError(null);
                addNotification({ title: 'Camera Active', message: 'Live AI surveillance feed started.', type: 'INFO' });
            } catch (playErr) {
                console.error("Video play failed", playErr);
                setCameraError("Video playback blocked");
            }
        };
      }
    } catch (err) {
      setCameraError("Camera unavailable.");
      console.error(err);
      setFeedMode('SIMULATION');
    }
  }, [addNotification]);

  useEffect(() => {
    let mounted = true;
    if (feedMode === 'CAMERA' && viewMode !== 'MAP') {
      if (mounted) startCamera();
    } else {
      stopStream();
      setIsCameraActive(false);
    }
    return () => {
      mounted = false;
      stopStream();
    };
  }, [feedMode, viewMode, startCamera]);

  // --- Logic ---
  const getCenter = (bbox: [number, number, number, number]) => ({
    x: bbox[0] + bbox[2] / 2,
    y: bbox[1] + bbox[3] / 2
  });

  const getDistance = (p1: { x: number, y: number }, p2: { x: number, y: number }) => {
    return Math.sqrt(Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2));
  };

  const inferBehavior = (velocity: number, bbox: [number, number, number, number], canvasHeight: number): string => {
    const [, y, w, h] = bbox;
    const aspectRatio = w / h;
    const bottomY = y + h;
    if (velocity > 2.5) return "Moving";
    if (aspectRatio > 1.6) return "Resting";
    if (bottomY > canvasHeight * 0.85) return "Feeding";
    return "Standing";
  };

  const inferBreed = (animalClass: string): string => {
    // Heuristic: Cycle through known farm breeds for the demo based on detection class
    if (animalClass === 'cow') return Math.random() > 0.5 ? 'Holstein' : 'Angus';
    if (animalClass === 'sheep') return 'Merino';
    if (animalClass === 'horse') return 'Quarter Horse';
    return 'Unknown Mix';
  };

  const updateTrackedObjects = (predictions: any[], canvasHeight: number) => {
    const newTrackedMap = new Map<number, TrackedObject>();
    const currentFrameTime = Date.now();
    const matchThreshold = 150; 

    // Filter predictions rigorously
    const detected = predictions
      .filter((p: any) => p.score > CONFIDENCE_THRESHOLD)
      .map((p: any) => ({
        bbox: p.bbox,
        class: p.class,
        score: p.score,
        center: getCenter(p.bbox)
      }));

    setIsAnyAnimalDetected(detected.length > 0);

    const usedIndices = new Set<number>();

    trackedObjectsRef.current.forEach((trackedObj, id) => {
      let bestMatchIndex = -1;
      let minDist = Infinity;

      detected.forEach((det: any, idx: number) => {
        if (usedIndices.has(idx)) return;
        if (det.class !== trackedObj.class) return; // Strict class matching

        const dist = getDistance(trackedObj.center, det.center);
        if (dist < minDist && dist < matchThreshold) {
          minDist = dist;
          bestMatchIndex = idx;
        }
      });

      if (bestMatchIndex !== -1) {
        const match = detected[bestMatchIndex];
        const velocity = minDist;
        const behavior = inferBehavior(velocity, match.bbox, canvasHeight);

        newTrackedMap.set(id, {
          id,
          bbox: match.bbox,
          class: match.class,
          breed: trackedObj.breed || inferBreed(match.class), // Persist breed
          score: match.score,
          lastSeen: currentFrameTime,
          velocity,
          behavior,
          center: match.center
        });
        usedIndices.add(bestMatchIndex);
      } else {
        // Reduced persistence time to 500ms to clear "ghost" detections faster
        if (currentFrameTime - trackedObj.lastSeen < 500) {
           newTrackedMap.set(id, { ...trackedObj, velocity: 0 });
        }
      }
    });

    detected.forEach((det: any, idx: number) => {
      if (!usedIndices.has(idx)) {
        const id = nextObjectIdRef.current++;
        const behavior = inferBehavior(0, det.bbox, canvasHeight);
        newTrackedMap.set(id, {
          id,
          bbox: det.bbox,
          class: det.class,
          breed: inferBreed(det.class),
          score: det.score,
          lastSeen: currentFrameTime,
          velocity: 0,
          behavior,
          center: det.center
        });
      }
    });

    trackedObjectsRef.current = newTrackedMap;
    return Array.from(newTrackedMap.values());
  };

  // --- Detection Loop ---
  useEffect(() => {
    if (feedMode !== 'CAMERA' || !model || !isCameraActive || viewMode === 'MAP') return;

    const intervalId = setInterval(async () => {
        if (isDetectingRef.current || !videoRef.current) return;

        isDetectingRef.current = true;
        try {
            if (videoRef.current.readyState === 4) {
                const predictions = await model.detect(videoRef.current);
                // Strict whitelist for livestock
                const allowed = ['cow', 'sheep', 'horse', 'dog', 'cat', 'bear', 'bird']; 
                latestPredictionsRef.current = predictions.filter((p: any) => allowed.includes(p.class));
            }
        } catch (e) {
            console.warn("Detection skipped", e);
        } finally {
            isDetectingRef.current = false;
        }
    }, DETECTION_INTERVAL_MS);

    return () => clearInterval(intervalId);
  }, [feedMode, model, isCameraActive, viewMode]);

  // --- Rendering Loop ---
  useEffect(() => {
    const runLoop = () => {
        if (viewMode === 'MAP') {
            renderMapFrame();
        } else if (feedMode === 'SIMULATION') {
            renderSimulationFrame();
        } else if (feedMode === 'CAMERA' && isCameraActive) {
            renderCameraFrame();
        }
        requestRef.current = requestAnimationFrame(runLoop);
    };

    requestRef.current = requestAnimationFrame(runLoop);
    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [feedMode, viewMode, isCameraActive, animals]); // animals dependency needed for map updates

  // --- Draw Functions ---

  const renderMapFrame = () => {
      const canvas = mapCanvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      // Ensure canvas size
      if (canvas.width !== 800) { canvas.width = 800; canvas.height = 450; }

      // Clear
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Draw Base Map (Simulated as a simple grid/field)
      ctx.fillStyle = '#f0fdf4'; // Light green background
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Draw Grid Lines (Fields)
      ctx.strokeStyle = '#dcfce7';
      ctx.lineWidth = 1;
      for (let i = 0; i < canvas.width; i += 100) {
          ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, canvas.height); ctx.stroke();
      }
      for (let i = 0; i < canvas.height; i += 100) {
          ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(canvas.width, i); ctx.stroke();
      }

      // Draw Animals and Trails
      animals.forEach(animal => {
          if (!animal.location) return;

          // Convert Lat/Lng to Pixel coordinates relative to Farm Center
          const x = canvas.width / 2 + (animal.location.lng - FARM_CENTER.lng) * MAP_ZOOM_FACTOR;
          const y = canvas.height / 2 - (animal.location.lat - FARM_CENTER.lat) * MAP_ZOOM_FACTOR;

          // Draw History Trail
          if (animal.locationHistory && animal.locationHistory.length > 1) {
              ctx.beginPath();
              ctx.strokeStyle = animal.status === HealthStatus.HEALTHY ? 'rgba(16, 185, 129, 0.4)' : 'rgba(245, 158, 11, 0.4)';
              ctx.lineWidth = 2;
              animal.locationHistory.forEach((point, idx) => {
                  const px = canvas.width / 2 + (point.lng - FARM_CENTER.lng) * MAP_ZOOM_FACTOR;
                  const py = canvas.height / 2 - (point.lat - FARM_CENTER.lat) * MAP_ZOOM_FACTOR;
                  if (idx === 0) ctx.moveTo(px, py);
                  else ctx.lineTo(px, py);
              });
              ctx.stroke();
          }

          // Draw Marker
          ctx.beginPath();
          ctx.arc(x, y, 6, 0, 2 * Math.PI);
          ctx.fillStyle = animal.status === HealthStatus.HEALTHY ? '#10b981' : '#f59e0b';
          ctx.fill();
          ctx.strokeStyle = '#fff';
          ctx.lineWidth = 2;
          ctx.stroke();

          // Draw Label
          ctx.fillStyle = '#1e293b';
          ctx.font = 'bold 10px Inter';
          ctx.fillText(animal.tagId, x + 8, y + 3);
      });

      // Draw Farm Center
      const cx = canvas.width / 2;
      const cy = canvas.height / 2;
      ctx.fillStyle = '#3b82f6';
      ctx.beginPath(); ctx.arc(cx, cy, 8, 0, 2 * Math.PI); ctx.fill();
      ctx.fillStyle = '#fff';
      ctx.font = '10px Inter';
      ctx.fillText("HQ", cx - 6, cy + 3);
  };

  const renderCameraFrame = () => {
    const canvas = canvasRef.current;
    const video = videoRef.current;
    if (!canvas || !video) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    if (video.readyState === 4) {
        if (canvas.width !== video.videoWidth || canvas.height !== video.videoHeight) {
            canvas.width = video.videoWidth;
            canvas.height = video.videoHeight;
        }
    }

    const trackedObjects = updateTrackedObjects(latestPredictionsRef.current, canvas.height);

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (trackedObjects.length > 0) {
        trackedObjects.forEach((obj) => {
            drawObjectOverlay(ctx, obj, viewMode);
        });

        if (viewMode === 'THERMAL') {
                ctx.fillStyle = 'rgba(0, 0, 50, 0.3)'; 
                ctx.globalCompositeOperation = 'destination-over';
                ctx.fillRect(0, 0, canvas.width, canvas.height);
                ctx.globalCompositeOperation = 'source-over';
        }
    }
  };

  const simTargetsRef = useRef([
    { ...MOCK_ANIMALS[0], x: 20, y: 30, dx: 0.2 },
    { ...MOCK_ANIMALS[1], x: 60, y: 50, dx: 0 }
  ]);

  const renderSimulationFrame = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    if (canvas.width !== 800) { canvas.width = 800; canvas.height = 450; }
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Simulation updates
    simTargetsRef.current.forEach((target) => {
        if (Math.random() > 0.98) target.dx = (Math.random() - 0.5) * 1.5;
        target.x += target.dx;
        if (target.x < 5 || target.x > 85) target.dx *= -1;
    });

    setIsAnyAnimalDetected(true); // Always detected in sim

    simTargetsRef.current.forEach((target) => {
        const liveData = animals.find(a => a.id === target.id) || target;
        const boxX = (target.x / 100) * canvas.width;
        const boxY = (target.y / 100) * canvas.height;
        const boxW = 120;
        const boxH = 80;

        if (viewMode === 'THERMAL') {
            const centerX = boxX + boxW / 2;
            const centerY = boxY + boxH / 2;
            const gradient = ctx.createRadialGradient(centerX, centerY, 5, centerX, centerY, boxW);
            gradient.addColorStop(0, liveData.temperature > 39 ? '#ef4444' : '#f97316'); 
            gradient.addColorStop(1, 'rgba(0,0,255,0)');
            ctx.fillStyle = gradient;
            ctx.fillRect(boxX - 30, boxY - 30, boxW + 60, boxH + 60);
            ctx.fillStyle = '#fff';
            ctx.font = 'bold 12px monospace';
            ctx.fillText(`${liveData.temperature.toFixed(1)}°C`, boxX, boxY - 10);
        } else {
            ctx.strokeStyle = liveData.status === HealthStatus.HEALTHY ? '#10b981' : '#f59e0b';
            ctx.lineWidth = 2;
            ctx.strokeRect(boxX, boxY, boxW, boxH);
            ctx.fillStyle = liveData.status === HealthStatus.HEALTHY ? '#10b981' : '#f59e0b';
            ctx.fillRect(boxX, boxY - 24, boxW, 24);
            ctx.fillStyle = '#ffffff';
            ctx.font = 'bold 12px Inter, sans-serif';
            ctx.textAlign = 'left'; 
            ctx.fillText(`${liveData.tagId} (${liveData.breed || liveData.species})`, boxX + 5, boxY - 8);
            ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
            ctx.font = '11px Inter, sans-serif';
            ctx.fillText(`Status: ${liveData.status}`, boxX + 5, boxY + 15);
        }
    });

    if (viewMode === 'THERMAL') {
        ctx.fillStyle = 'rgba(0, 20, 60, 0.4)'; 
        ctx.globalCompositeOperation = 'destination-over';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.globalCompositeOperation = 'source-over';
    }
  };

  const drawObjectOverlay = (ctx: CanvasRenderingContext2D, obj: TrackedObject, mode: string) => {
    const [x, y, width, height] = obj.bbox;

    if (mode === 'THERMAL') {
        const centerX = x + width / 2;
        const centerY = y + height / 2;
        const radius = Math.max(width, height) / 1.5;
        const gradient = ctx.createRadialGradient(centerX, centerY, 1, centerX, centerY, radius);
        gradient.addColorStop(0, 'rgba(255, 0, 0, 0.8)');
        gradient.addColorStop(0.5, 'rgba(255, 165, 0, 0.5)');
        gradient.addColorStop(1, 'rgba(0, 0, 255, 0)');
        ctx.fillStyle = gradient;
        ctx.fillRect(x - width/2, y - height/2, width * 2, height * 2);
    } else {
        const color = '#10b981';
        ctx.strokeStyle = color;
        ctx.lineWidth = 3;
        ctx.strokeRect(x, y, width, height);

        // Display Breed if we have inferred it, otherwise class
        const labelText = `${(obj.breed || obj.class).toUpperCase()}: ${obj.behavior}`;
        const textWidth = ctx.measureText(labelText).width;

        ctx.fillStyle = color;
        ctx.fillRect(x, y - 25, textWidth + 20, 25);
        ctx.fillStyle = '#ffffff';
        ctx.font = 'bold 14px Inter, sans-serif';
        ctx.fillText(labelText, x + 5, y - 7);

        ctx.fillStyle = 'rgba(255,255,255,0.8)';
        ctx.font = '10px Inter, sans-serif';
        ctx.fillText(`${Math.round(obj.score * 100)}%`, x + 5, y + 15);
    }
  };

  const handleScanAnimal = async (animal: AnimalData) => {
    if (!animal.imageUrl) return;
    setAnalyzingId(animal.id);
    addNotification({ title: 'Scanning Animal', message: `AI analysis started for ${animal.tagId}`, type: 'INFO' });
    try {
        const response = await fetch(animal.imageUrl);
        const blob = await response.blob();
        const reader = new FileReader();
        reader.onloadend = async () => {
            const base64 = reader.result as string;
            const result = await analyzeLivestockFrame(base64.split(',')[1]);
            setAnalysisResults(prev => ({ ...prev, [animal.id]: result }));
            setAnalyzingId(null);
            addNotification({ title: 'Scan Complete', message: `Health insights ready for ${animal.tagId}`, type: 'SUCCESS' });
        };
        reader.readAsDataURL(blob);
    } catch (e) {
        console.error("Error analyzing animal", e);
        setAnalyzingId(null);
        addNotification({ title: 'Scan Failed', message: `Could not analyze ${animal.tagId}`, type: 'WARNING' });
    }
  };

  const handleExportData = () => {
    const dataToExport = animals.map(a => ({
        Tag: a.tagId,
        Breed: a.breed || a.species,
        Weight: a.weightKg,
        Temp: a.temperature,
        Location: `${a.location?.lat.toFixed(5)}, ${a.location?.lng.toFixed(5)}`,
        Status: a.status,
        Timestamp: new Date().toISOString()
    }));
    ExportService.exportToCSV(dataToExport, 'livestock_metrics_live.csv');
    addNotification({ title: 'Data Exported', message: 'Livestock CSV downloaded with GPS data.', type: 'INFO' });
  };

  const handleViewRecommendations = async () => {
    setShowRecommendations(true);
    const realTimeRecs = animals
        .filter(a => a.temperature > 39 || a.activityLevel === 'Agitated')
        .map(a => {
            const isEstrus = a.temperature > 38.5 && a.activityLevel === 'Agitated';
            const isSick = a.temperature > 39.5 && a.activityLevel === 'Resting';
            return {
                id: a.id,
                animalId: a.tagId,
                confidence: isEstrus ? 92 : (isSick ? 88 : 65),
                window: isEstrus ? 'Now - 12h' : 'Immediate',
                note: isEstrus ? t('estrus_detected') : (isSick ? t('high_temp_alert') : 'Monitor closely')
            };
        });
    setRecommendations(realTimeRecs.length ? realTimeRecs : [{ id: 'none', animalId: 'N/A', confidence: 100, window: '-', note: 'No anomalies detected.' }]);
  };

  const calculatedHealthData = useMemo(() => {
    const currentAvgScore = animals.reduce((acc, curr) => acc + curr.healthScore, 0) / animals.length;
    const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
    return days.map((day, i) => ({ name: day, score: Math.round(currentAvgScore + Math.sin(i) * 5) }));
  }, [animals]);

  const breedingCount = animals.filter(a => a.temperature > 38.5 && a.activityLevel === 'Agitated').length;

  return (
    <div className="space-y-6 relative">
      {/* Recommendations Modal */}
      {showRecommendations && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-fade-in">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-md overflow-hidden">
                <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-indigo-600 text-white">
                    <h3 className="font-bold flex items-center gap-2">
                        <HeartPulse size={20} /> {t('breeding_cycle')}
                    </h3>
                    <button onClick={() => setShowRecommendations(false)} className="hover:bg-indigo-700 p-1 rounded-full"><X size={20} /></button>
                </div>
                <div className="p-4 space-y-3">
                    {recommendations.map(rec => (
                        <div key={rec.id} className="p-3 bg-indigo-50 rounded-lg border border-indigo-100">
                            <div className="flex justify-between mb-1">
                                <span className="font-bold text-indigo-900">{rec.animalId}</span>
                                <span className="text-xs bg-white px-2 py-0.5 rounded text-indigo-600 font-bold border border-indigo-200">{rec.confidence}% {t('confidence')}</span>
                            </div>
                            <p className="text-sm text-slate-700 mb-1">Window: <span className="font-semibold">{rec.window}</span></p>
                            <p className="text-xs text-slate-500">{rec.note}</p>
                        </div>
                    ))}
                </div>
            </div>
        </div>
      )}

      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">{t('livestock_monitoring')}</h1>
          <p className="text-slate-500">{t('livestock_subtitle')}</p>
        </div>
        <div className="flex items-center space-x-2">
            <button onClick={handleExportData} className="flex items-center space-x-2 px-4 py-2 bg-white border border-slate-300 rounded-lg text-sm font-medium hover:bg-slate-50 transition-colors">
                <FileText size={16} /> <span>{t('export_csv')}</span>
            </button>
        </div>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">

        {/* Main Column */}
        <div className="xl:col-span-2 space-y-6">

            {/* Live Surveillance / Map Feed */}
            <div className="bg-slate-900 rounded-xl overflow-hidden shadow-lg border border-slate-700 relative group">
                <div className="p-3 bg-black/40 backdrop-blur absolute top-0 left-0 right-0 z-10 flex justify-between items-center border-b border-white/10">
                    <div className="flex items-center gap-2">
                        <div className="flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-red-500/20 text-red-500 border border-red-500/30">
                            <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse" />
                            <span className="text-xs font-bold tracking-wide">LIVE</span>
                        </div>
                        <span className="text-slate-200 text-sm font-medium">{t('live_feed')}</span>
                    </div>

                    <div className="flex items-center gap-2">
                         <button onClick={() => { setViewMode('MAP'); setFeedMode('SIMULATION'); }} className={`flex items-center gap-1 px-3 py-1 rounded-md text-xs font-medium transition-all ${viewMode === 'MAP' ? 'bg-indigo-600 text-white' : 'text-slate-300 hover:bg-slate-800'}`}>
                             <MapIcon size={12} /> Map GPS
                         </button>
                         <button onClick={() => setViewMode('THERMAL')} className={`flex items-center gap-1 px-3 py-1 rounded-md text-xs font-medium transition-all ${viewMode === 'THERMAL' ? 'bg-orange-600 text-white' : 'text-slate-300 hover:bg-slate-800'}`}>
                            <Flame size={12} /> {t('thermal_vision')}
                         </button>
                         <button onClick={() => setViewMode('NORMAL')} className={`flex items-center gap-1 px-3 py-1 rounded-md text-xs font-medium transition-all ${viewMode === 'NORMAL' ? 'bg-emerald-600 text-white' : 'text-slate-300 hover:bg-slate-800'}`}>
                            <Eye size={12} /> {t('normal_vision')}
                         </button>
                         <div className="w-px h-4 bg-slate-700 mx-1"></div>
                         <button onClick={() => setFeedMode(feedMode === 'CAMERA' ? 'SIMULATION' : 'CAMERA')} className={`flex items-center gap-1 px-3 py-1 rounded-md text-xs font-medium transition-all ${feedMode === 'CAMERA' ? 'bg-blue-600' : 'bg-slate-700'}`}>
                             {feedMode === 'CAMERA' ? 'Cam On' : 'Sim Mode'}
                         </button>
                    </div>
                </div>

                <div className="relative aspect-video bg-black flex items-center justify-center overflow-hidden">
                    {/* Map View */}
                    {viewMode === 'MAP' && (
                        <div className="w-full h-full bg-slate-100 relative">
                             <canvas ref={mapCanvasRef} className="w-full h-full block" />
                             <div className="absolute bottom-4 right-4 bg-white/90 p-2 rounded text-xs text-slate-600 shadow border border-slate-200">
                                 <div className="font-bold mb-1">GPS Tracking Active</div>
                                 <div>Lat: {FARM_CENTER.lat.toFixed(4)}</div>
                                 <div>Lng: {FARM_CENTER.lng.toFixed(4)}</div>
                             </div>
                        </div>
                    )}

                    {/* Camera/Sim View */}
                    {viewMode !== 'MAP' && (
                        <>
                            {feedMode === 'CAMERA' ? (
                                <video ref={videoRef} autoPlay muted playsInline className="w-full h-full object-cover" style={{ filter: viewMode === 'THERMAL' ? 'grayscale(100%) contrast(120%)' : 'none' }} />
                            ) : (
                                <div className="w-full h-full relative">
                                    <img src="https://images.unsplash.com/photo-1545464528-6c82a5a5198e?auto=format&fit=crop&q=80&w=1600" className="w-full h-full object-cover opacity-60" style={{ filter: viewMode === 'THERMAL' ? 'grayscale(100%) contrast(120%)' : 'none' }} alt="Simulation" />
                                </div>
                            )}
                            <canvas ref={canvasRef} className="absolute inset-0 pointer-events-none w-full h-full" width={800} height={450} style={{ mixBlendMode: viewMode === 'THERMAL' ? 'screen' : 'normal' }} />

                            {/* "No Animals" Overlay */}
                            {!isAnyAnimalDetected && feedMode === 'CAMERA' && !cameraError && (
                                <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 bg-black/60 backdrop-blur-sm px-6 py-3 rounded-full border border-white/20 animate-pulse">
                                    <p className="text-white text-sm font-medium flex items-center gap-2">
                                        <Crosshair size={16} /> Scanning sector... No animals detected
                                    </p>
                                </div>
                            )}

                            {cameraError && (
                                <div className="absolute inset-0 flex items-center justify-center bg-black/80 z-20">
                                    <div className="text-center p-6 bg-slate-800 rounded-xl border border-red-500/50 max-w-sm">
                                        <Video size={48} className="mx-auto text-red-500 mb-4" />
                                        <h3 className="text-white font-bold mb-2">Camera Unavailable</h3>
                                        <p className="text-slate-400 text-sm mb-4">{cameraError}</p>
                                        <button onClick={() => setFeedMode('SIMULATION')} className="px-4 py-2 bg-slate-700 hover:bg-slate-600 text-white rounded-lg text-sm font-medium">Switch to Simulation</button>
                                    </div>
                                </div>
                            )}
                        </>
                    )}
                </div>
            </div>

            {/* Individual Animal Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {animals.map((animal) => (
                <div key={animal.id} className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden hover:shadow-md transition-shadow">
                <div className="relative aspect-video bg-slate-900 group">
                    <img src={animal.imageUrl} alt={animal.species} className="w-full h-full object-cover opacity-90 group-hover:opacity-100 transition-opacity" />
                    <div className="absolute bottom-0 left-0 right-0 p-2 bg-gradient-to-t from-black/80 to-transparent flex justify-between items-end text-white text-xs">
                        <span className="flex items-center gap-1"><Thermometer size={12} className={animal.temperature > 39 ? 'text-red-400' : 'text-emerald-400'} /> {animal.temperature.toFixed(1)}°C</span>
                        <span className="flex items-center gap-1"><Navigation size={12} /> GPS Active</span>
                    </div>
                    <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity bg-black/20 backdrop-blur-[1px]">
                        <button onClick={() => handleScanAnimal(animal)} disabled={analyzingId === animal.id} className="bg-white text-slate-900 px-4 py-2 rounded-full font-medium shadow-lg hover:scale-105 transition-transform flex items-center gap-2">
                            {analyzingId === animal.id ? <span className="animate-spin">⌛</span> : <Camera size={18} />} <span>{t('quick_scan')}</span>
                        </button>
                    </div>
                </div>

                {analysisResults[animal.id] && (
                    <div className="bg-indigo-50 p-3 border-b border-indigo-100 animate-fade-in">
                        <p className="text-sm font-bold text-indigo-900 mb-1">AI Insight:</p>
                        <p className="text-xs text-indigo-800 leading-relaxed mb-2">{analysisResults[animal.id].condition} - {analysisResults[animal.id].issues[0] || "No issues detected"}</p>
                        <div className="flex flex-wrap gap-1">
                            {analysisResults[animal.id].recommendations.slice(0, 2).map((rec, i) => (<span key={i} className="text-[10px] bg-white border border-indigo-200 px-2 py-0.5 rounded text-indigo-700">{rec}</span>))}
                        </div>
                    </div>
                )}

                <div className="p-4">
                    <div className="flex justify-between items-start mb-4">
                    <div>
                        <h3 className="font-bold text-slate-900">{animal.tagId} <span className="text-slate-400 font-normal text-xs">({animal.breed || animal.species})</span></h3>
                        <p className="text-xs text-slate-500">Last GPS: {animal.location ? `${animal.location.lat.toFixed(4)}, ${animal.location.lng.toFixed(4)}` : 'Signal Lost'}</p>
                    </div>
                    <div className={`px-2 py-1 rounded text-xs font-bold ${animal.status === HealthStatus.HEALTHY ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'}`}>
                        {animal.status === HealthStatus.HEALTHY ? t('healthy') : t('warning')}
                    </div>
                    </div>

                    <div className="grid grid-cols-3 gap-2">
                        <div className="bg-slate-50 p-2 rounded border border-slate-100">
                            <div className="text-xs text-slate-500 flex items-center gap-1"><Thermometer size={12} /> {t('temp')}</div>
                            <div className={`font-semibold transition-colors ${animal.temperature > 39.5 ? 'text-rose-600' : 'text-slate-800'}`}>{animal.temperature.toFixed(1)}°C</div>
                        </div>
                        <div className="bg-slate-50 p-2 rounded border border-slate-100">
                            <div className="text-xs text-slate-500 flex items-center gap-1"><Activity size={12} /> Activity</div>
                            <div className="font-semibold text-slate-800">{animal.activityLevel}</div>
                        </div>
                        <div className="bg-slate-50 p-2 rounded border border-slate-100">
                            <div className="text-xs text-slate-500 flex items-center gap-1"><Video size={12} /> Weight</div>
                            <div className="font-semibold text-slate-800">{animal.weightKg}kg</div>
                        </div>
                    </div>
                </div>
                </div>
            ))}
            </div>
        </div>

        {/* Sidebar Stats */}
        <div className="space-y-6">
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
                <h3 className="font-semibold text-slate-800 mb-4">{t('herd_health')}</h3>
                <div className="h-48">
                    <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={calculatedHealthData}>
                            <XAxis dataKey="name" fontSize={10} tickLine={false} axisLine={false} />
                            <Tooltip cursor={{fill: 'transparent'}} contentStyle={{borderRadius: '8px', border:'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}} />
                            <Bar dataKey="score" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={20} />
                        </BarChart>
                    </ResponsiveContainer>
                </div>
            </div>

            <div className="bg-gradient-to-br from-indigo-600 to-purple-700 p-6 rounded-xl shadow-lg text-white">
                <div className="flex items-start justify-between">
                    <div>
                        <h3 className="font-bold text-lg mb-1">{t('breeding_cycle')}</h3>
                        <p className="text-indigo-100 text-sm">Real-time AI Analysis</p>
                    </div>
                    <div className="bg-white/20 p-2 rounded-lg"><Activity size={20} /></div>
                </div>
                <div className="mt-6">
                    <p className="text-3xl font-bold">{breedingCount}</p>
                    <p className="text-sm text-indigo-200">Animals showing high activity & heat signs</p>
                </div>
                <button onClick={handleViewRecommendations} className="mt-4 w-full py-2 bg-white/10 hover:bg-white/20 rounded-lg text-sm font-medium transition-colors">{t('view_recs')}</button>
            </div>

            {/* Environmental Stats */}
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
                 <div className="flex justify-between items-center mb-4">
                     <h3 className="font-semibold text-slate-800">{t('barn_env')}</h3>
                     <span className="text-xs text-green-600 bg-green-50 px-2 py-1 rounded-full flex items-center gap-1 animate-pulse"><div className="w-1.5 h-1.5 bg-green-600 rounded-full"></div> Live</span>
                 </div>
                 <div className="space-y-4">
                     <div className="flex items-center justify-between">
                         <div className="flex items-center gap-2 text-slate-600"><Thermometer size={16} /> <span className="text-sm">{t('temp')}</span></div>
                         <span className="font-mono font-medium text-slate-900">{barnEnv.temp}°C</span>
                     </div>
                     <div className="w-full bg-slate-100 rounded-full h-1.5"><div className="bg-emerald-500 h-1.5 rounded-full transition-all duration-1000" style={{width: `${(barnEnv.temp / 40) * 100}%`}}></div></div>
                     <div className="flex items-center justify-between mt-2">
                         <div className="flex items-center gap-2 text-slate-600"><Activity size={16} /> <span className="text-sm">{t('weather_humidity')}</span></div>
                         <span className="font-mono font-medium text-slate-900">{barnEnv.humidity}%</span>
                     </div>
                     <div className="w-full bg-slate-100 rounded-full h-1.5"><div className="bg-blue-500 h-1.5 rounded-full transition-all duration-1000" style={{width: `${barnEnv.humidity}%`}}></div></div>
                     <div className="flex items-center justify-between mt-2">
                         <div className="flex items-center gap-2 text-slate-600"><Power size={16} /> <span className="text-sm">{t('air_quality')}</span></div>
                         <span className={`font-mono font-medium ${barnEnv.quality === 'Good' ? 'text-emerald-600' : 'text-amber-600'}`}>{barnEnv.quality}</span>
                     </div>
                 </div>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { 
  Activity, 
  Thermometer, 
  Video,
  Camera,
  X,
  HeartPulse,
  Power,
  Scan,
  Loader2,
  FileText,
  Flame,
  Eye,
  Map as MapIcon,
  Navigation,
  Crosshair,
  LocateFixed
} from 'lucide-react';
import { MOCK_ANIMALS } from '../constants';
import { AnimalData, HealthStatus, AIAnalysisResult, GeoLocation } from '../types';
import { analyzeLivestockFrame } from '../services/geminiService';
import { ApiService } from '../services/api';
import { ExportService } from '../services/exportService';
import { BarChart, Bar, XAxis, Tooltip, ResponsiveContainer } from 'recharts';
import { useNotifications } from '../context/NotificationContext';
import { useLanguage } from '../context/LanguageContext';

// @ts-ignore
import * as tf from '@tensorflow/tfjs';
// @ts-ignore
import * as cocoSsd from '@tensorflow-models/coco-ssd';

// Performance Configuration
const DETECTION_INTERVAL_MS = 200; // Cap AI to 5 FPS to reduce load
const SIMULATION_UPDATE_MS = 2000;
const CONFIDENCE_THRESHOLD = 0.60; 

// Tracking Types
interface TrackedObject {
  id: number;
  bbox: [number, number, number, number]; // x, y, w, h
  class: string;
  breed?: string; // Inferred breed
  score: number;
  lastSeen: number;
  velocity: number;
  behavior: string;
  center: { x: number, y: number };
}

export const LivestockDashboard: React.FC = () => {
  const { addNotification } = useNotifications();
  const { t } = useLanguage();

  // State for Real-time Data
  const [animals, setAnimals] = useState<AnimalData[]>(MOCK_ANIMALS);
  const [barnEnv, setBarnEnv] = useState({
      temp: 22.4,
      humidity: 45,
      co2: 412,
      quality: 'Good'
  });

  const [analyzingId, setAnalyzingId] = useState<string | null>(null);
  const [analysisResults, setAnalysisResults] = useState<Record<string, AIAnalysisResult>>({});
  const [showRecommendations, setShowRecommendations] = useState(false);
  const [recommendations, setRecommendations] = useState<any[]>([]);

  // Camera & Live Feed State
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const mapCanvasRef = useRef<HTMLCanvasElement>(null);

  const [isCameraActive, setIsCameraActive] = useState(false);
  const [cameraError, setCameraError] = useState<string | null>(null);
  const [feedMode, setFeedMode] = useState<'SIMULATION' | 'CAMERA'>('SIMULATION');
  const [viewMode, setViewMode] = useState<'NORMAL' | 'THERMAL' | 'MAP'>('NORMAL');
  const [isAnyAnimalDetected, setIsAnyAnimalDetected] = useState(false);

  // AI Model State
  const [model, setModel] = useState<any>(null);
  const [modelLoading, setModelLoading] = useState(false);

  // Tracking State Refs
  const trackedObjectsRef = useRef<Map<number, TrackedObject>>(new Map());
  const nextObjectIdRef = useRef(1);
  const latestPredictionsRef = useRef<any[]>([]);
  const isDetectingRef = useRef(false);
  const requestRef = useRef<number>();
  const streamRef = useRef<MediaStream | null>(null);

  // Map settings
  const FARM_CENTER = { lat: 36.7378, lng: -119.7871 };
  const MAP_ZOOM_FACTOR = 10000; // Adjusted for better visual scale

  // --- Model Loading (Lazy) ---
  useEffect(() => {
    if (feedMode === 'CAMERA' && !model && !modelLoading) {
        const loadModel = async () => {
            setModelLoading(true);
            try {
                await tf.ready();
                // Load lite_mobilenet_v2 for speed
                const loadedModel = await cocoSsd.load({ base: 'lite_mobilenet_v2' });
                setModel(loadedModel);
                console.log("TensorFlow Lite Model Loaded");
            } catch (err) {
                console.error("Failed to load TensorFlow model", err);
                addNotification({ title: 'AI Error', message: 'Failed to load computer vision model.', type: 'WARNING' });
            } finally {
                setModelLoading(false);
            }
        };
        setTimeout(loadModel, 500);
    }
  }, [feedMode, model, modelLoading, addNotification]);

  // --- Real-time Data Simulation Loop (Sensors) ---
  useEffect(() => {
    const fetchBaseData = async () => {
      const data = await ApiService.getAnimals();
      setAnimals(data);
    };
    fetchBaseData();

    // 1. Live Animal Telemetry
    const animalInterval = setInterval(() => {
        setAnimals(prevAnimals => prevAnimals.map(animal => {
            const tempFluctuation = (Math.random() - 0.5) * 0.2;
            const weightFluctuation = (Math.random() - 0.5) * 0.05;

            // Temperature update
            let newTemp = parseFloat((animal.temperature + tempFluctuation).toFixed(1));
            if (newTemp < 37.5) newTemp = 37.5;
            if (newTemp > 41.0) newTemp = 41.0;

            let status = animal.status;
            let activity = animal.activityLevel;

            if (newTemp > 39.5 && status === HealthStatus.HEALTHY) {
                status = HealthStatus.WARNING;
                activity = 'Agitated';
            } else if (newTemp < 39.0 && status === HealthStatus.WARNING) {
                status = HealthStatus.HEALTHY;
            }

            // GPS Logic: Only simulate if NOT in Camera mode
            // If in Camera mode, GPS is driven by detection loop
            let newLocation = animal.location;

            // Fallback simulation if camera is off or in SIM mode
            if (feedMode === 'SIMULATION' || !isCameraActive) {
                const moveLat = (Math.random() - 0.5) * 0.00005;
                const moveLng = (Math.random() - 0.5) * 0.00005;
                newLocation = {
                    lat: (animal.location?.lat || FARM_CENTER.lat) + moveLat,
                    lng: (animal.location?.lng || FARM_CENTER.lng) + moveLng
                };
            }

            // Maintain history trail (keep last 20 points)
            // Note: If Camera mode, this is updated in the detection loop instead
            let locationHistory = animal.locationHistory;
            if (feedMode === 'SIMULATION' || !isCameraActive) {
                const newHistoryPoint = { ...newLocation, timestamp: new Date().toISOString() };
                locationHistory = animal.locationHistory ? [...animal.locationHistory, newHistoryPoint] : [newHistoryPoint];
                if (locationHistory.length > 20) locationHistory.shift();
            }

            return {
                ...animal,
                temperature: newTemp,
                weightKg: parseFloat((animal.weightKg + weightFluctuation).toFixed(2)),
                status: status,
                activityLevel: activity,
                location: newLocation,
                locationHistory: locationHistory
            };
        }));
    }, SIMULATION_UPDATE_MS);

    // 2. Barn Environment Sensors
    const barnInterval = setInterval(() => {
        setBarnEnv(prev => {
            const tChange = (Math.random() - 0.5) * 0.1;
            const hChange = (Math.random() - 0.5) * 1;
            const newTemp = parseFloat((prev.temp + tChange).toFixed(1));
            const newHum = Math.round(prev.humidity + hChange);
            const newCo2 = Math.round(prev.co2 + (Math.random() - 0.5) * 5);
            let quality = 'Good';
            if (newCo2 > 1000) quality = 'Poor';
            else if (newCo2 > 600) quality = 'Fair';
            return { temp: newTemp, humidity: newHum, co2: newCo2, quality };
        });
    }, 5000);

    return () => {
        clearInterval(animalInterval);
        clearInterval(barnInterval);
    };
  }, [feedMode, isCameraActive]); // Re-run if feedMode changes to switch GPS source logic

  // --- Live Camera Management ---
  const stopStream = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => {
        track.stop();
        streamRef.current?.removeTrack(track);
      });
      streamRef.current = null;
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
  };

  const startCamera = useCallback(async () => {
    stopStream();
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        setCameraError("Camera API not supported");
        setFeedMode('SIMULATION');
        return;
    }

    try {
      let stream: MediaStream;
      try {
          stream = await navigator.mediaDevices.getUserMedia({ 
              video: { width: { ideal: 1280 }, height: { ideal: 720 }, facingMode: 'environment' } 
          });
      } catch (err) {
          console.warn("HD constraint failed, retrying defaults...", err);
          stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      }

      streamRef.current = stream;

      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.onloadedmetadata = async () => {
            try {
                await videoRef.current?.play();
                setIsCameraActive(true);
                setCameraError(null);
                addNotification({ title: 'Camera Active', message: 'Live AI surveillance feed started.', type: 'INFO' });
            } catch (playErr) {
                console.error("Video play failed", playErr);
                setCameraError("Video playback blocked");
            }
        };
      }
    } catch (err) {
      setCameraError("Camera unavailable.");
      console.error(err);
      setFeedMode('SIMULATION');
    }
  }, [addNotification]);

  // Handle Camera Lifecycle
  useEffect(() => {
    let mounted = true;
    // We keep camera active even in MAP view if feedMode is CAMERA
    if (feedMode === 'CAMERA') {
      if (mounted) startCamera();
    } else {
      stopStream();
      setIsCameraActive(false);
    }
    return () => {
      mounted = false;
      stopStream();
    };
  }, [feedMode, startCamera]);

  // --- Logic ---
  const getCenter = (bbox: [number, number, number, number]) => ({
    x: bbox[0] + bbox[2] / 2,
    y: bbox[1] + bbox[3] / 2
  });

  const getDistance = (p1: { x: number, y: number }, p2: { x: number, y: number }) => {
    return Math.sqrt(Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2));
  };

  const inferBehavior = (velocity: number, bbox: [number, number, number, number], canvasHeight: number): string => {
    const [, y, w, h] = bbox;
    const aspectRatio = w / h;
    const bottomY = y + h;
    if (velocity > 2.5) return "Moving";
    if (aspectRatio > 1.6) return "Resting";
    if (bottomY > canvasHeight * 0.85) return "Feeding";
    return "Standing";
  };

  const inferBreed = (animalClass: string): string => {
    if (animalClass === 'cow') return Math.random() > 0.5 ? 'Holstein' : 'Angus';
    if (animalClass === 'sheep') return 'Merino';
    if (animalClass === 'horse') return 'Quarter Horse';
    return 'Unknown Mix';
  };

  // Convert Camera Screen Coordinates to Geo-Offsets
  const updateAnimalLocationsFromCamera = (trackedObjs: TrackedObject[], canvasWidth: number, canvasHeight: number) => {
      if (trackedObjs.length === 0) return;

      setAnimals(prevAnimals => {
          // Clone to avoid mutation
          const nextAnimals = [...prevAnimals];

          // Heuristic: Map detected objects to animals in order
          // In a real app, this would use ID re-identification embeddings
          trackedObjs.forEach((obj, idx) => {
              if (idx < nextAnimals.length) {
                  const animal = nextAnimals[idx];

                  // Normalize coordinates (-0.5 to 0.5) relative to center of screen
                  const normX = (obj.center.x / canvasWidth) - 0.5;
                  const normY = (obj.center.y / canvasHeight) - 0.5;

                  // Projection Scale (Adjust these to map pixel movement to lat/lng movement)
                  // Lat is Y (inverted typically, up is North), Lng is X
                  // Small factors because lat/lng degrees are huge distances
                  const latOffset = -normY * 0.0005; // Negative because screen Y goes down, Lat goes up (North)
                  const lngOffset = normX * 0.0005;

                  const newLat = FARM_CENTER.lat + latOffset;
                  const newLng = FARM_CENTER.lng + lngOffset;

                  animal.location = { lat: newLat, lng: newLng };

                  // Update History
                  const newPoint = { lat: newLat, lng: newLng, timestamp: new Date().toISOString() };
                  const history = animal.locationHistory ? [...animal.locationHistory, newPoint] : [newPoint];
                  if (history.length > 50) history.shift(); // Keep longer history for smoother trails
                  animal.locationHistory = history;

                  // Also update activity based on camera
                  animal.activityLevel = obj.behavior as any;
              }
          });
          return nextAnimals;
      });
  };

  const updateTrackedObjects = (predictions: any[], canvasWidth: number, canvasHeight: number) => {
    const newTrackedMap = new Map<number, TrackedObject>();
    const currentFrameTime = Date.now();
    const matchThreshold = 150; 

    const detected = predictions
      .filter((p: any) => p.score > CONFIDENCE_THRESHOLD)
      .map((p: any) => ({
        bbox: p.bbox,
        class: p.class,
        score: p.score,
        center: getCenter(p.bbox)
      }));

    setIsAnyAnimalDetected(detected.length > 0);

    const usedIndices = new Set<number>();

    // Sort detected by X to keep consistent ordering (helps with mapping to stable animal IDs)
    detected.sort((a: any, b: any) => a.center.x - b.center.x);

    trackedObjectsRef.current.forEach((trackedObj, id) => {
      let bestMatchIndex = -1;
      let minDist = Infinity;

      detected.forEach((det: any, idx: number) => {
        if (usedIndices.has(idx)) return;
        if (det.class !== trackedObj.class) return;

        const dist = getDistance(trackedObj.center, det.center);
        if (dist < minDist && dist < matchThreshold) {
          minDist = dist;
          bestMatchIndex = idx;
        }
      });

      if (bestMatchIndex !== -1) {
        const match = detected[bestMatchIndex];
        const velocity = minDist;
        const behavior = inferBehavior(velocity, match.bbox, canvasHeight);

        newTrackedMap.set(id, {
          id,
          bbox: match.bbox,
          class: match.class,
          breed: trackedObj.breed,
          score: match.score,
          lastSeen: currentFrameTime,
          velocity,
          behavior,
          center: match.center
        });
        usedIndices.add(bestMatchIndex);
      }
    });

    detected.forEach((det: any, idx: number) => {
      if (!usedIndices.has(idx)) {
        const id = nextObjectIdRef.current++;
        const behavior = inferBehavior(0, det.bbox, canvasHeight);
        newTrackedMap.set(id, {
          id,
          bbox: det.bbox,
          class: det.class,
          breed: inferBreed(det.class),
          score: det.score,
          lastSeen: currentFrameTime,
          velocity: 0,
          behavior,
          center: det.center
        });
      }
    });

    trackedObjectsRef.current = newTrackedMap;
    const trackedList = Array.from(newTrackedMap.values());

    // Update GPS coords based on these tracked objects
    updateAnimalLocationsFromCamera(trackedList, canvasWidth, canvasHeight);

    return trackedList;
  };

  // --- Detection Loop ---
  useEffect(() => {
    // Continue detecting even in MAP view if Camera is the data source
    if (feedMode !== 'CAMERA' || !model || !isCameraActive) return;

    const intervalId = setInterval(async () => {
        if (isDetectingRef.current || !videoRef.current) return;

        isDetectingRef.current = true;
        try {
            if (videoRef.current.readyState === 4) {
                const predictions = await model.detect(videoRef.current);
                const allowed = ['cow', 'sheep', 'horse', 'dog', 'cat', 'bear', 'bird']; 
                latestPredictionsRef.current = predictions.filter((p: any) => allowed.includes(p.class));
            }
        } catch (e) {
            console.warn("Detection skipped", e);
        } finally {
            isDetectingRef.current = false;
        }
    }, DETECTION_INTERVAL_MS);

    return () => clearInterval(intervalId);
  }, [feedMode, model, isCameraActive]);

  // --- Rendering Loop ---
  useEffect(() => {
    const runLoop = () => {
        if (viewMode === 'MAP') {
            renderMapFrame();
        } else if (feedMode === 'SIMULATION') {
            renderSimulationFrame();
        } else if (feedMode === 'CAMERA' && isCameraActive && viewMode !== 'MAP') {
            renderCameraFrame();
        }
        requestRef.current = requestAnimationFrame(runLoop);
    };

    requestRef.current = requestAnimationFrame(runLoop);
    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [feedMode, viewMode, isCameraActive, animals]);

  // --- Draw Functions ---

  const renderMapFrame = () => {
      const canvas = mapCanvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      if (canvas.width !== 800) { canvas.width = 800; canvas.height = 450; }

      // Clear
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Draw Satellite-style Map Background
      ctx.fillStyle = '#0f172a'; // Dark Slate
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Grid Lines
      ctx.strokeStyle = '#1e293b';
      ctx.lineWidth = 1;
      const gridSize = 50;
      for (let i = 0; i < canvas.width; i += gridSize) {
          ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, canvas.height); ctx.stroke();
      }
      for (let i = 0; i < canvas.height; i += gridSize) {
          ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(canvas.width, i); ctx.stroke();
      }

      // Draw Drone POV indicators (if in camera mode)
      if (feedMode === 'CAMERA') {
          ctx.strokeStyle = 'rgba(16, 185, 129, 0.2)';
          ctx.lineWidth = 2;
          ctx.strokeRect(canvas.width * 0.1, canvas.height * 0.1, canvas.width * 0.8, canvas.height * 0.8);

          ctx.fillStyle = 'rgba(16, 185, 129, 0.1)';
          ctx.fillText("LIVE SENSOR DATA FEED", 20, 30);
      }

      // Draw Animals and Trails
      animals.forEach(animal => {
          if (!animal.location) return;

          // Convert Lat/Lng to Pixel
          const x = canvas.width / 2 + (animal.location.lng - FARM_CENTER.lng) * MAP_ZOOM_FACTOR;
          const y = canvas.height / 2 - (animal.location.lat - FARM_CENTER.lat) * MAP_ZOOM_FACTOR;

          // Draw History Trail
          if (animal.locationHistory && animal.locationHistory.length > 1) {
              ctx.beginPath();
              // Fade out trail
              const gradient = ctx.createLinearGradient(
                  x, y, 
                  canvas.width / 2 + (animal.locationHistory[0].lng - FARM_CENTER.lng) * MAP_ZOOM_FACTOR,
                  canvas.height / 2 - (animal.locationHistory[0].lat - FARM_CENTER.lat) * MAP_ZOOM_FACTOR
              );
              gradient.addColorStop(0, animal.status === HealthStatus.HEALTHY ? 'rgba(16, 185, 129, 0.8)' : 'rgba(245, 158, 11, 0.8)');
              gradient.addColorStop(1, 'rgba(0,0,0,0)');

              ctx.strokeStyle = gradient;
              ctx.lineWidth = 2;

              ctx.moveTo(x, y); // Start at current
              // Draw backwards through history
              for (let i = animal.locationHistory.length - 1; i >= 0; i--) {
                  const pt = animal.locationHistory[i];
                  const px = canvas.width / 2 + (pt.lng - FARM_CENTER.lng) * MAP_ZOOM_FACTOR;
                  const py = canvas.height / 2 - (pt.lat - FARM_CENTER.lat) * MAP_ZOOM_FACTOR;
                  ctx.lineTo(px, py);
              }
              ctx.stroke();
          }

          // Draw Marker
          ctx.beginPath();
          ctx.arc(x, y, 6, 0, 2 * Math.PI);
          ctx.fillStyle = animal.status === HealthStatus.HEALTHY ? '#10b981' : '#f59e0b';
          ctx.shadowBlur = 10;
          ctx.shadowColor = ctx.fillStyle;
          ctx.fill();
          ctx.shadowBlur = 0;

          ctx.strokeStyle = '#fff';
          ctx.lineWidth = 2;
          ctx.stroke();

          // Draw Label
          ctx.fillStyle = '#e2e8f0';
          ctx.font = 'bold 11px Inter';
          ctx.fillText(`${animal.tagId}`, x + 10, y + 4);
          ctx.font = '10px Inter';
          ctx.fillStyle = '#94a3b8';
          ctx.fillText(`${animal.breed || animal.species}`, x + 10, y + 16);
      });

      // Draw Farm Center
      const cx = canvas.width / 2;
      const cy = canvas.height / 2;
      ctx.fillStyle = '#3b82f6';
      ctx.beginPath(); ctx.arc(cx, cy, 8, 0, 2 * Math.PI); ctx.fill();
      ctx.fillStyle = '#fff';
      ctx.textAlign = 'center';
      ctx.fillText("HQ", cx, cy + 20);
      ctx.textAlign = 'left';
  };

  const renderCameraFrame = () => {
    const canvas = canvasRef.current;
    const video = videoRef.current;
    if (!canvas || !video) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    if (video.readyState === 4) {
        if (canvas.width !== video.videoWidth || canvas.height !== video.videoHeight) {
            canvas.width = video.videoWidth;
            canvas.height = video.videoHeight;
        }
    }

    // Pass canvas dimensions to update logic for GPS projection
    const trackedObjects = updateTrackedObjects(latestPredictionsRef.current, canvas.width, canvas.height);

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (trackedObjects.length > 0) {
        trackedObjects.forEach((obj) => {
            drawObjectOverlay(ctx, obj, viewMode);
        });

        if (viewMode === 'THERMAL') {
                ctx.fillStyle = 'rgba(0, 0, 50, 0.3)'; 
                ctx.globalCompositeOperation = 'destination-over';
                ctx.fillRect(0, 0, canvas.width, canvas.height);
                ctx.globalCompositeOperation = 'source-over';
        }
    }
  };

  const simTargetsRef = useRef([
    { ...MOCK_ANIMALS[0], x: 20, y: 30, dx: 0.2 },
    { ...MOCK_ANIMALS[1], x: 60, y: 50, dx: 0 }
  ]);

  const renderSimulationFrame = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    if (canvas.width !== 800) { canvas.width = 800; canvas.height = 450; }
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Simulation updates (visual only)
    simTargetsRef.current.forEach((target) => {
        if (Math.random() > 0.98) target.dx = (Math.random() - 0.5) * 1.5;
        target.x += target.dx;
        if (target.x < 5 || target.x > 85) target.dx *= -1;
    });

    setIsAnyAnimalDetected(true); // Always detected in sim

    simTargetsRef.current.forEach((target) => {
        const liveData = animals.find(a => a.id === target.id) || target;
        const boxX = (target.x / 100) * canvas.width;
        const boxY = (target.y / 100) * canvas.height;
        const boxW = 120;
        const boxH = 80;

        if (viewMode === 'THERMAL') {
            const centerX = boxX + boxW / 2;
            const centerY = boxY + boxH / 2;
            const gradient = ctx.createRadialGradient(centerX, centerY, 5, centerX, centerY, boxW);
            gradient.addColorStop(0, liveData.temperature > 39 ? '#ef4444' : '#f97316'); 
            gradient.addColorStop(1, 'rgba(0,0,255,0)');
            ctx.fillStyle = gradient;
            ctx.fillRect(boxX - 30, boxY - 30, boxW + 60, boxH + 60);
            ctx.fillStyle = '#fff';
            ctx.font = 'bold 12px monospace';
            ctx.fillText(`${liveData.temperature.toFixed(1)}°C`, boxX, boxY - 10);
        } else {
            ctx.strokeStyle = liveData.status === HealthStatus.HEALTHY ? '#10b981' : '#f59e0b';
            ctx.lineWidth = 2;
            ctx.strokeRect(boxX, boxY, boxW, boxH);
            ctx.fillStyle = liveData.status === HealthStatus.HEALTHY ? '#10b981' : '#f59e0b';
            ctx.fillRect(boxX, boxY - 24, boxW, 24);
            ctx.fillStyle = '#ffffff';
            ctx.font = 'bold 12px Inter, sans-serif';
            ctx.textAlign = 'left'; 
            ctx.fillText(`${liveData.tagId} (${liveData.breed || liveData.species})`, boxX + 5, boxY - 8);
            ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
            ctx.font = '11px Inter, sans-serif';
            ctx.fillText(`Status: ${liveData.status}`, boxX + 5, boxY + 15);
        }
    });

    if (viewMode === 'THERMAL') {
        ctx.fillStyle = 'rgba(0, 20, 60, 0.4)'; 
        ctx.globalCompositeOperation = 'destination-over';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.globalCompositeOperation = 'source-over';
    }
  };

  const drawObjectOverlay = (ctx: CanvasRenderingContext2D, obj: TrackedObject, mode: string) => {
    const [x, y, width, height] = obj.bbox;

    if (mode === 'THERMAL') {
        const centerX = x + width / 2;
        const centerY = y + height / 2;
        const radius = Math.max(width, height) / 1.5;
        const gradient = ctx.createRadialGradient(centerX, centerY, 1, centerX, centerY, radius);
        gradient.addColorStop(0, 'rgba(255, 0, 0, 0.8)');
        gradient.addColorStop(0.5, 'rgba(255, 165, 0, 0.5)');
        gradient.addColorStop(1, 'rgba(0, 0, 255, 0)');
        ctx.fillStyle = gradient;
        ctx.fillRect(x - width/2, y - height/2, width * 2, height * 2);
    } else {
        const color = '#10b981';
        ctx.strokeStyle = color;
        ctx.lineWidth = 3;
        ctx.strokeRect(x, y, width, height);

        // Display Breed if we have inferred it, otherwise class
        const labelText = `${(obj.breed || obj.class).toUpperCase()}: ${obj.behavior}`;
        const textWidth = ctx.measureText(labelText).width;

        ctx.fillStyle = color;
        ctx.fillRect(x, y - 25, textWidth + 20, 25);
        ctx.fillStyle = '#ffffff';
        ctx.font = 'bold 14px Inter, sans-serif';
        ctx.fillText(labelText, x + 5, y - 7);

        ctx.fillStyle = 'rgba(255,255,255,0.8)';
        ctx.font = '10px Inter, sans-serif';
        ctx.fillText(`${Math.round(obj.score * 100)}%`, x + 5, y + 15);
    }
  };

  const handleScanAnimal = async (animal: AnimalData) => {
    if (!animal.imageUrl) return;
    setAnalyzingId(animal.id);
    addNotification({ title: 'Scanning Animal', message: `AI analysis started for ${animal.tagId}`, type: 'INFO' });
    try {
        const response = await fetch(animal.imageUrl);
        const blob = await response.blob();
        const reader = new FileReader();
        reader.onloadend = async () => {
            const base64 = reader.result as string;
            const result = await analyzeLivestockFrame(base64.split(',')[1]);
            setAnalysisResults(prev => ({ ...prev, [animal.id]: result }));
            setAnalyzingId(null);
            addNotification({ title: 'Scan Complete', message: `Health insights ready for ${animal.tagId}`, type: 'SUCCESS' });
        };
        reader.readAsDataURL(blob);
    } catch (e) {
        console.error("Error analyzing animal", e);
        setAnalyzingId(null);
        addNotification({ title: 'Scan Failed', message: `Could not analyze ${animal.tagId}`, type: 'WARNING' });
    }
  };

  const handleExportData = () => {
    const dataToExport = animals.map(a => ({
        Tag: a.tagId,
        Breed: a.breed || a.species,
        Weight: a.weightKg,
        Temp: a.temperature,
        Location: `${a.location?.lat.toFixed(5)}, ${a.location?.lng.toFixed(5)}`,
        Status: a.status,
        Timestamp: new Date().toISOString()
    }));
    ExportService.exportToCSV(dataToExport, 'livestock_metrics_live.csv');
    addNotification({ title: 'Data Exported', message: 'Livestock CSV downloaded with GPS data.', type: 'INFO' });
  };

  const handleViewRecommendations = async () => {
    setShowRecommendations(true);
    const realTimeRecs = animals
        .filter(a => a.temperature > 39 || a.activityLevel === 'Agitated')
        .map(a => {
            const isEstrus = a.temperature > 38.5 && a.activityLevel === 'Agitated';
            const isSick = a.temperature > 39.5 && a.activityLevel === 'Resting';
            return {
                id: a.id,
                animalId: a.tagId,
                confidence: isEstrus ? 92 : (isSick ? 88 : 65),
                window: isEstrus ? 'Now - 12h' : 'Immediate',
                note: isEstrus ? t('estrus_detected') : (isSick ? t('high_temp_alert') : 'Monitor closely')
            };
        });
    setRecommendations(realTimeRecs.length ? realTimeRecs : [{ id: 'none', animalId: 'N/A', confidence: 100, window: '-', note: 'No anomalies detected.' }]);
  };

  const calculatedHealthData = useMemo(() => {
    const currentAvgScore = animals.reduce((acc, curr) => acc + curr.healthScore, 0) / animals.length;
    const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
    return days.map((day, i) => ({ name: day, score: Math.round(currentAvgScore + Math.sin(i) * 5) }));
  }, [animals]);

  const breedingCount = animals.filter(a => a.temperature > 38.5 && a.activityLevel === 'Agitated').length;

  return (
    <div className="space-y-6 relative">
      {/* Recommendations Modal */}
      {showRecommendations && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-fade-in">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-md overflow-hidden">
                <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-indigo-600 text-white">
                    <h3 className="font-bold flex items-center gap-2">
                        <HeartPulse size={20} /> {t('breeding_cycle')}
                    </h3>
                    <button onClick={() => setShowRecommendations(false)} className="hover:bg-indigo-700 p-1 rounded-full"><X size={20} /></button>
                </div>
                <div className="p-4 space-y-3">
                    {recommendations.map(rec => (
                        <div key={rec.id} className="p-3 bg-indigo-50 rounded-lg border border-indigo-100">
                            <div className="flex justify-between mb-1">
                                <span className="font-bold text-indigo-900">{rec.animalId}</span>
                                <span className="text-xs bg-white px-2 py-0.5 rounded text-indigo-600 font-bold border border-indigo-200">{rec.confidence}% {t('confidence')}</span>
                            </div>
                            <p className="text-sm text-slate-700 mb-1">Window: <span className="font-semibold">{rec.window}</span></p>
                            <p className="text-xs text-slate-500">{rec.note}</p>
                        </div>
                    ))}
                </div>
            </div>
        </div>
      )}

      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">{t('livestock_monitoring')}</h1>
          <p className="text-slate-500">{t('livestock_subtitle')}</p>
        </div>
        <div className="flex items-center space-x-2">
            <button onClick={handleExportData} className="flex items-center space-x-2 px-4 py-2 bg-white border border-slate-300 rounded-lg text-sm font-medium hover:bg-slate-50 transition-colors">
                <FileText size={16} /> <span>{t('export_csv')}</span>
            </button>
        </div>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">

        {/* Main Column */}
        <div className="xl:col-span-2 space-y-6">

            {/* Live Surveillance / Map Feed */}
            <div className="bg-slate-900 rounded-xl overflow-hidden shadow-lg border border-slate-700 relative group">
                <div className="p-3 bg-black/40 backdrop-blur absolute top-0 left-0 right-0 z-10 flex justify-between items-center border-b border-white/10">
                    <div className="flex items-center gap-2">
                        <div className="flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-red-500/20 text-red-500 border border-red-500/30">
                            <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse" />
                            <span className="text-xs font-bold tracking-wide">LIVE</span>
