                                 <div className="font-mono">Lat: {FARM_CENTER.lat.toFixed(4)}</div>
                                 <div className="font-mono">Lng: {FARM_CENTER.lng.toFixed(4)}</div>
                                 <div className="mt-1 text-slate-500">{feedMode === 'CAMERA' ? 'Source: Live Cam Projection' : 'Source: Simulation'}</div>
                             </div>
                        </div>
                    )}

                    {/* Camera Video - Always rendered if CAMERA mode, just hidden if MAP view */}
                    {feedMode === 'CAMERA' && (
                         <video 
                            ref={videoRef} 
                            autoPlay 
                            muted 
                            playsInline 
                            className={`w-full h-full object-cover absolute inset-0 ${viewMode === 'MAP' ? 'opacity-0 pointer-events-none' : 'z-0'}`} 
                            style={{ filter: viewMode === 'THERMAL' ? 'grayscale(100%) contrast(120%)' : 'none' }} 
                        />
                    )}

                    {/* Simulation Image - Only if Sim Mode */}
                    {feedMode === 'SIMULATION' && viewMode !== 'MAP' && (
                        <div className="w-full h-full relative z-0">
                            <img src="https://images.unsplash.com/photo-1545464528-6c82a5a5198e?auto=format&fit=crop&q=80&w=1600" className="w-full h-full object-cover opacity-60" style={{ filter: viewMode === 'THERMAL' ? 'grayscale(100%) contrast(120%)' : 'none' }} alt="Simulation" />
                        </div>
