                    {/* Canvas Overlay for Detections (Only visible in camera/sim views) */}
                    <canvas 
                        ref={canvasRef} 
                        className={`absolute inset-0 pointer-events-none w-full h-full ${viewMode === 'MAP' ? 'hidden' : 'z-10'}`} 
                        width={800} 
                        height={450} 
                        style={{ mixBlendMode: viewMode === 'THERMAL' ? 'screen' : 'normal' }} 
