                    {/* "No Animals" Overlay */}
                    {viewMode !== 'MAP' && !isAnyAnimalDetected && feedMode === 'CAMERA' && !cameraError && (
                        <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 bg-black/60 backdrop-blur-sm px-6 py-3 rounded-full border border-white/20 animate-pulse z-20">
