            </div>

            <div className="bg-gradient-to-br from-indigo-600 to-purple-700 p-6 rounded-xl shadow-lg text-white">
                <div className="flex items-start justify-between">
                    <div>
                        <h3 className="font-bold text-lg mb-1">{t('breeding_cycle')}</h3>
