// @ts-ignore
import * as tf from '@tensorflow/tfjs';
// @ts-ignore
import * as cocoSsd from '@tensorflow-models/coco-ssd';

// Performance Configuration
const DETECTION_INTERVAL_MS = 200; // Cap AI to 5 FPS to reduce load
const SIMULATION_UPDATE_MS = 2000;
const CONFIDENCE_THRESHOLD = 0.60; 
const LIVE_REPORT_INTERVAL_MS = 30000; // Auto-analyze live feeds every 30 seconds

// Tracking Types
interface TrackedObject {
  id: number;
  bbox: [number, number, number, number]; // x, y, w, h
  class: string;
  breed?: string; // Inferred breed
  score: number;
  lastSeen: number;
  velocity: number;
  behavior: string;
  center: { x: number, y: number };
}

// Internal Component: Individual Live Animal Feed
const LiveAnimalFeed: React.FC<{
  animalId: string;
  deviceId?: string;
  onAnalysisUpdate: (id: string, result: AIAnalysisResult) => void;
  onError: (id: string, error: string) => void;
}> = ({ animalId, deviceId, onAnalysisUpdate, onError }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isScanning, setIsScanning] = useState(false);
  const streamRef = useRef<MediaStream | null>(null);

  // Start Camera
  useEffect(() => {
    const startFeed = async () => {
      try {
        const constraints = {
            video: { 
                deviceId: deviceId ? { exact: deviceId } : undefined,
                width: { ideal: 640 },
                height: { ideal: 360 }
            }
        };
        const stream = await navigator.mediaDevices.getUserMedia(constraints);
        streamRef.current = stream;
        if (videoRef.current) {
            videoRef.current.srcObject = stream;
        }
      } catch (e) {
        console.error("Failed to start animal feed", e);
        onError(animalId, "Camera access denied or unavailable");
      }
    };
    startFeed();

    return () => {
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }
    };
  }, [deviceId, animalId, onError]);

  // Auto-Analysis Interval
  useEffect(() => {
    const captureAndAnalyze = async () => {
        if (!videoRef.current || !canvasRef.current || videoRef.current.paused || videoRef.current.ended) return;

        setIsScanning(true);
        try {
            const ctx = canvasRef.current.getContext('2d');
            canvasRef.current.width = videoRef.current.videoWidth;
            canvasRef.current.height = videoRef.current.videoHeight;
            ctx?.drawImage(videoRef.current, 0, 0);

            const base64 = canvasRef.current.toDataURL('image/jpeg', 0.8).split(',')[1];
            const result = await analyzeLivestockFrame(base64);
            onAnalysisUpdate(animalId, result);
        } catch (e) {
            console.warn("Auto-analysis failed", e);
        } finally {
            setIsScanning(false);
        }
    };

    // Initial scan after startup delay
    const initialTimer = setTimeout(captureAndAnalyze, 2000);
    // Periodic scan
    const interval = setInterval(captureAndAnalyze, LIVE_REPORT_INTERVAL_MS);

    return () => {
        clearTimeout(initialTimer);
        clearInterval(interval);
    };
  }, [animalId, onAnalysisUpdate]);

  return (
    <div className="relative w-full h-full bg-black">
        <video 
            ref={videoRef} 
            autoPlay 
            muted 
            playsInline 
            className="w-full h-full object-cover" 
        />
        <canvas ref={canvasRef} className="hidden" />

        {/* Live Status Badge */}
        <div className="absolute top-2 left-2 flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-red-500/80 text-white backdrop-blur-sm z-10">
            <div className="w-1.5 h-1.5 rounded-full bg-white animate-pulse" />
            <span className="text-[10px] font-bold tracking-wide uppercase">Live Feed</span>
        </div>

        {/* Scanning Indicator */}
        {isScanning && (
            <div className="absolute top-2 right-2 flex items-center gap-1 px-2 py-1 rounded-md bg-black/60 text-white backdrop-blur-sm">
                <Loader2 size={12} className="animate-spin text-emerald-400" />
                <span className="text-[10px] font-medium">Updating Report...</span>
            </div>
        )}
    </div>
  );
};


