  // Configuration Modal
  const [configuringId, setConfiguringId] = useState<string | null>(null);
  const [configForm, setConfigForm] = useState({
      name: '',
      deviceId: '',
      weight: 0,
      temp: 0,
      breed: ''
  });

  // Map Refs
  const mapCanvasRef = useRef<HTMLCanvasElement>(null);
  const FARM_CENTER = { lat: 36.7378, lng: -119.7871 };
  const MAP_ZOOM_FACTOR = 10000;

  // -- Initialization --
  useEffect(() => {
    // Load devices
    const getDevices = async () => {
        try {
            const devices = await navigator.mediaDevices.enumerateDevices();
            const cameras = devices.filter(d => d.kind === 'videoinput');
            setVideoDevices(cameras);
        } catch (e) {
            console.warn("Could not list video devices", e);
        }
    };
    getDevices();

    // Load saved slots (simulated persistence)
    const saved = localStorage.getItem('livestock_slots');
    if (saved) {
        try {
            setAnimals(JSON.parse(saved));
        } catch (e) {
            console.error("Failed to load slots", e);
        }
    }
  }, []);

  // Save slots on change
  useEffect(() => {
      localStorage.setItem('livestock_slots', JSON.stringify(animals));
  }, [animals]);

  // -- Handlers --

  const handleAddSlot = () => {
      const newSlot: ExtendedAnimalData = {
          id: Date.now().toString(),
          tagId: 'New Slot',
          species: 'Unknown',
          ageMonths: 0,
          weightKg: 0,
          temperature: 0,
          activityLevel: 'Resting',
          healthScore: 0,
          status: HealthStatus.UNKNOWN,
          lastCheckup: new Date().toISOString(),
          location: { lat: FARM_CENTER.lat + (Math.random() * 0.001), lng: FARM_CENTER.lng + (Math.random() * 0.001) },
          locationHistory: [],
          isConfigured: false
      };
      setAnimals(prev => [...prev, newSlot]);
  };

  const handleDeleteSlot = (id: string) => {
      if (confirm("Are you sure you want to remove this camera slot?")) {
        setAnimals(prev => prev.filter(a => a.id !== id));
        addNotification({ title: 'Slot Removed', message: 'Camera slot deleted.', type: 'INFO' });
      }
  };

  const openConfig = (animal: ExtendedAnimalData) => {
      setConfiguringId(animal.id);
      setConfigForm({
          name: animal.tagId === 'New Slot' ? '' : animal.tagId,
          deviceId: animal.deviceId || '',
          weight: animal.weightKg,
          temp: animal.temperature,
          breed: animal.breed || ''
      });
  };

  const saveConfig = () => {
      if (!configuringId) return;

      setAnimals(prev => prev.map(a => {
          if (a.id === configuringId) {
              return {
                  ...a,
                  tagId: configForm.name || 'Unnamed',
                  deviceId: configForm.deviceId,
                  weightKg: configForm.weight,
                  temperature: configForm.temp,
                  breed: configForm.breed,
                  isConfigured: true,
                  status: HealthStatus.UNKNOWN // Reset status until AI scans it
              };
          }
          return a;
      }));
      setConfiguringId(null);
      addNotification({ title: 'Slot Configured', message: 'Camera and metadata updated.', type: 'SUCCESS' });
  };

  const handleLiveAnalysisUpdate = (id: string, result: AIAnalysisResult) => {
     setAnalysisResults(prev => ({ ...prev, [id]: result }));

     // Update the animal state with AI derived data (Activity, Health)
     setAnimals(prev => prev.map(a => {
         if (a.id === id) {
             let newStatus = HealthStatus.HEALTHY;
             if (result.condition.toLowerCase().includes('warning')) newStatus = HealthStatus.WARNING;
             if (result.condition.toLowerCase().includes('critical')) newStatus = HealthStatus.CRITICAL;

             return {
                 ...a,
                 status: newStatus,
                 healthScore: result.confidence,
                 activityLevel: 'Grazing', // In a real app, AI would return specific activity enum
                 lastAnalysisTime: Date.now()
             };
         }
         return a;
     }));
  };

  const handleFeedError = (id: string, error: string) => {
     addNotification({ title: 'Camera Error', message: error, type: 'WARNING' });
  };

  const handleExportData = () => {
    const dataToExport = animals.map(a => ({
        Tag: a.tagId,
        Breed: a.breed || a.species,
        Weight: a.weightKg,
        Temp: a.temperature,
        Location: `${a.location?.lat.toFixed(5)}, ${a.location?.lng.toFixed(5)}`,
        Status: a.status,
        Timestamp: new Date().toISOString()
    }));
    ExportService.exportToCSV(dataToExport, 'livestock_metrics_live.csv');
  };

  // -- Render Map --
  useEffect(() => {
      if (viewMode !== 'MAP' || !mapCanvasRef.current) return;

      const canvas = mapCanvasRef.current;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      canvas.width = 800;
      canvas.height = 450;

      // Draw Background
      ctx.fillStyle = '#0f172a';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Grid
      ctx.strokeStyle = '#1e293b';
      ctx.lineWidth = 1;
      for (let i = 0; i < canvas.width; i += 50) { ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, canvas.height); ctx.stroke(); }
      for (let i = 0; i < canvas.height; i += 50) { ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(canvas.width, i); ctx.stroke(); }

      // Draw Animals
      animals.forEach(animal => {
          // If no camera/configured, maybe don't show on map? Or show as inactive.
          if (!animal.isConfigured) return;

          const x = canvas.width / 2 + (animal.location.lng - FARM_CENTER.lng) * MAP_ZOOM_FACTOR;
          const y = canvas.height / 2 - (animal.location.lat - FARM_CENTER.lat) * MAP_ZOOM_FACTOR;

          ctx.beginPath();
          ctx.arc(x, y, 6, 0, 2 * Math.PI);
          ctx.fillStyle = animal.status === HealthStatus.HEALTHY ? '#10b981' : animal.status === HealthStatus.UNKNOWN ? '#94a3b8' : '#f59e0b';
          ctx.shadowBlur = 10;
          ctx.shadowColor = ctx.fillStyle;
          ctx.fill();
          ctx.shadowBlur = 0;

          ctx.strokeStyle = '#fff';
          ctx.lineWidth = 2;
          ctx.stroke();

          ctx.fillStyle = '#e2e8f0';
          ctx.font = 'bold 11px Inter';
          ctx.fillText(animal.tagId, x + 10, y + 4);
      });

      // HQ Center
      const cx = canvas.width / 2;
      const cy = canvas.height / 2;
      ctx.fillStyle = '#3b82f6';
      ctx.beginPath(); ctx.arc(cx, cy, 8, 0, 2 * Math.PI); ctx.fill();
      ctx.fillStyle = '#fff';
      ctx.textAlign = 'center';
      ctx.fillText("HQ", cx, cy + 20);

  }, [viewMode, animals]);

  // Derived Stats
  const activeCount = animals.filter(a => a.isConfigured && a.deviceId).length;
  const alertCount = animals.filter(a => a.status === HealthStatus.WARNING || a.status === HealthStatus.CRITICAL).length;

  const healthData = useMemo(() => {
     // Simple bar chart of health scores of active animals
     return animals
        .filter(a => a.isConfigured)
        .map(a => ({ name: a.tagId, score: a.healthScore }));
  }, [animals]);

  return (
    <div className="space-y-6 relative pb-20">

      {/* Configuration Modal */}
      {configuringId && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-md overflow-hidden">
                <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-900 text-white">
                    <h3 className="font-bold flex items-center gap-2">
                        <Settings size={18} /> Configure Slot
                    </h3>
                    <button onClick={() => setConfiguringId(null)}><X size={20} /></button>
                </div>
                <div className="p-6 space-y-4">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Slot Name / Tag ID</label>
                        <input 
                            type="text" 
                            className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-emerald-500 outline-none"
                            placeholder="e.g. COW-101"
                            value={configForm.name}
                            onChange={e => setConfigForm({...configForm, name: e.target.value})}
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Video Source</label>
                        <select 
                            className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-emerald-500 outline-none"
                            value={configForm.deviceId}
                            onChange={e => setConfigForm({...configForm, deviceId: e.target.value})}
                        >
                            <option value="">-- Select Camera --</option>
                            {videoDevices.map(d => (
                                <option key={d.deviceId} value={d.deviceId}>{d.label || `Camera ${d.deviceId.slice(0,5)}...`}</option>
                            ))}
                        </select>
                        <p className="text-xs text-slate-500 mt-1">Select the webcam or feed monitoring this animal.</p>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 mb-1">Breed (Optional)</label>
                            <input 
                                type="text" 
                                className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-emerald-500 outline-none"
                                placeholder="Angus"
                                value={configForm.breed}
                                onChange={e => setConfigForm({...configForm, breed: e.target.value})}
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 mb-1">Weight (kg)</label>
                            <input 
                                type="number" 
                                className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-emerald-500 outline-none"
                                placeholder="0"
                                value={configForm.weight}
                                onChange={e => setConfigForm({...configForm, weight: parseFloat(e.target.value) || 0})}
                            />
                        </div>
                    </div>
                    <button 
                        onClick={saveConfig}
                        className="w-full bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-2 rounded-lg transition-colors flex items-center justify-center gap-2"
                    >
                        <Save size={18} /> Save Configuration
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">{t('livestock_monitoring')}</h1>
          <p className="text-slate-500">Manage camera slots and view real-time AI analysis</p>
        </div>
        <div className="flex items-center gap-3">
             <button onClick={() => setViewMode(viewMode === 'MAP' ? 'NORMAL' : 'MAP')} className={`flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-colors ${viewMode === 'MAP' ? 'bg-indigo-600 text-white' : 'bg-white border border-slate-300 text-slate-700'}`}>
                 <MapIcon size={18} /> {viewMode === 'MAP' ? 'Close Map' : 'Map View'}
             </button>
             <button onClick={handleAddSlot} className="flex items-center gap-2 px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg font-medium shadow-sm transition-colors">
                <Plus size={18} /> Add Camera Slot
            </button>
            <button onClick={handleExportData} className="p-2 bg-white border border-slate-300 rounded-lg text-slate-600 hover:bg-slate-50">
                <FileText size={18} />
            </button>
        </div>
      </div>

      {/* Map Overlay (Full Width) */}
      {viewMode === 'MAP' && (
           <div className="bg-slate-900 rounded-xl overflow-hidden shadow-lg border border-slate-700 relative h-[500px] animate-fade-in">
                <canvas ref={mapCanvasRef} className="w-full h-full block" />
                <div className="absolute bottom-4 left-4 bg-black/70 backdrop-blur p-4 rounded-lg text-slate-300 text-sm">
                    <p className="font-bold text-white mb-1">GPS Tracking</p>
                    <p>Showing locations for {activeCount} active camera slots.</p>
                </div>
           </div>
      )}

      {/* Camera Grid */}
      {animals.length === 0 ? (
          <div className="text-center py-20 bg-slate-100 rounded-xl border-2 border-dashed border-slate-300">
              <Camera size={48} className="mx-auto text-slate-400 mb-4" />
              <h3 className="text-lg font-semibold text-slate-600">No Camera Slots Added</h3>
              <p className="text-slate-500 mb-6">Create a slot to start monitoring your livestock.</p>
              <button onClick={handleAddSlot} className="px-6 py-2 bg-emerald-600 text-white rounded-lg font-medium hover:bg-emerald-700 transition-colors">
                  Create First Slot
              </button>
          </div>
      ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
            {animals.map(animal => (
                <div key={animal.id} className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden group hover:shadow-md transition-shadow">
                    {/* Header */}
                    <div className="p-3 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                        <div className="flex items-center gap-2">
                            <span className={`w-2 h-2 rounded-full ${animal.isConfigured && animal.deviceId ? 'bg-green-500 animate-pulse' : 'bg-slate-300'}`} />
                            <h3 className="font-bold text-slate-800">{animal.tagId}</h3>
                        </div>
                        <div className="flex items-center gap-1">
                            <button onClick={() => openConfig(animal)} className="p-1.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded transition-colors" title="Configure">
                                <Settings size={16} />
                            </button>
                            <button onClick={() => handleDeleteSlot(animal.id)} className="p-1.5 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded transition-colors" title="Delete">
                                <Trash2 size={16} />
                            </button>
                        </div>
                    </div>

                    {/* Feed Area */}
                    <div className="aspect-video bg-slate-900 relative">
                        {animal.isConfigured && animal.deviceId ? (
                            <LiveAnimalFeed 
                                animal={animal} 
                                onAnalysisUpdate={handleLiveAnalysisUpdate} 
                                onError={handleFeedError} 
                            />
                        ) : (
                            <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-500 bg-slate-100">
                                <VideoOff size={32} className="mb-2 opacity-50" />
                                <p className="text-sm font-medium">No Camera Added</p>
                                <button onClick={() => openConfig(animal)} className="mt-3 px-4 py-1.5 bg-white border border-slate-300 rounded text-xs font-medium hover:bg-slate-50 text-indigo-600">
                                    + Add Camera
                                </button>
                            </div>
                        )}

                        {/* Thermal Overlay Toggle */}
                        {animal.isConfigured && animal.deviceId && (
                             <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                <div className="bg-black/50 backdrop-blur text-white text-[10px] px-2 py-1 rounded">
                                    AI Active
                                </div>
                             </div>
                        )}
                    </div>

                    {/* Stats & AI Data */}
                    {animal.isConfigured ? (
                        <div className="p-4 space-y-3">
                            {/* Analysis Result Box */}
                            {analysisResults[animal.id] ? (
                                <div className="bg-indigo-50 p-3 rounded-lg border border-indigo-100">
                                    <div className="flex justify-between items-center mb-1">
                                        <span className="text-xs font-bold text-indigo-900 uppercase">AI Detected</span>
                                        <span className="text-[10px] bg-white text-indigo-600 px-1.5 rounded border border-indigo-200">{analysisResults[animal.id].confidence}% Conf.</span>
                                    </div>
                                    <p className="text-sm text-indigo-800 font-medium">{analysisResults[animal.id].condition}</p>
                                    <p className="text-xs text-indigo-600 mt-1">{analysisResults[animal.id].issues[0] || 'Monitoring...'}</p>
                                </div>
                            ) : (
                                <div className="text-xs text-slate-400 italic text-center py-2">
                                    Waiting for AI analysis...
                                </div>
                            )}

                            {/* Metrics Grid - Only show non-zero/known */}
                            <div className="grid grid-cols-3 gap-2">
                                <div className="bg-slate-50 p-2 rounded border border-slate-100">
                                    <div className="text-[10px] text-slate-500 uppercase tracking-wider mb-0.5">Temp</div>
                                    <div className="font-semibold text-sm text-slate-800">{animal.temperature > 0 ? `${animal.temperature}°C` : '--'}</div>
                                </div>
                                <div className="bg-slate-50 p-2 rounded border border-slate-100">
                                    <div className="text-[10px] text-slate-500 uppercase tracking-wider mb-0.5">Weight</div>
                                    <div className="font-semibold text-sm text-slate-800">{animal.weightKg > 0 ? `${animal.weightKg}kg` : '--'}</div>
                                </div>
                                <div className="bg-slate-50 p-2 rounded border border-slate-100">
                                    <div className="text-[10px] text-slate-500 uppercase tracking-wider mb-0.5">Status</div>
                                    <div className={`font-semibold text-sm ${
                                        animal.status === HealthStatus.HEALTHY ? 'text-emerald-600' : 
                                        animal.status === HealthStatus.WARNING ? 'text-amber-600' : 'text-slate-800'
                                    }`}>
                                        {animal.status === HealthStatus.UNKNOWN ? '--' : animal.status}
                                    </div>
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="p-4 text-center">
                            <p className="text-sm text-slate-400">Configure this slot to view data.</p>
                        </div>
                    )}
                </div>
            ))}
          </div>
      )}

      {/* Sidebar / Stats Footer */}
      {animals.length > 0 && (
          <div className="mt-8 grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
                  <h3 className="font-bold text-slate-800 mb-2">System Status</h3>
                  <div className="space-y-2">
                      <div className="flex justify-between text-sm">
                          <span className="text-slate-500">Active Cameras</span>
                          <span className="font-medium">{activeCount} / {animals.length}</span>
                      </div>
                      <div className="flex justify-between text-sm">
                          <span className="text-slate-500">Alerts</span>
                          <span className="font-medium text-amber-600">{alertCount}</span>
                      </div>
                  </div>
              </div>
              <div className="md:col-span-2 bg-white p-6 rounded-xl shadow-sm border border-slate-200 h-48">
                  <h3 className="font-bold text-slate-800 mb-2">Health Distribution (Active Slots)</h3>
                   <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={healthData}>
                            <XAxis dataKey="name" fontSize={10} tickLine={false} axisLine={false} />
                            <Tooltip cursor={{fill: 'transparent'}} contentStyle={{borderRadius: '8px', border:'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}} />
                            <Bar dataKey="score" fill="#10b981" radius={[4, 4, 0, 0]} barSize={30} />
                        </BarChart>
                    </ResponsiveContainer>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { 
  Activity, 
  Thermometer, 
  Video,
  Camera,
  X,
  HeartPulse,
  Power,
  Scan,
  Loader2,
  FileText,
  Flame,
  Eye,
  Map as MapIcon,
  Navigation,
  Crosshair,
  LocateFixed,
  Settings,
  Plus,
  Trash2,
  VideoOff,
  MoreVertical,
  Save,
  RefreshCw
} from 'lucide-react';
import { AnimalData, HealthStatus, AIAnalysisResult, GeoLocation } from '../types';
import { analyzeLivestockFrame } from '../services/geminiService';
import { ExportService } from '../services/exportService';
import { BarChart, Bar, XAxis, Tooltip, ResponsiveContainer } from 'recharts';
import { useNotifications } from '../context/NotificationContext';
import { useLanguage } from '../context/LanguageContext';

// @ts-ignore
import * as tf from '@tensorflow/tfjs';
// @ts-ignore
import * as cocoSsd from '@tensorflow-models/coco-ssd';

// Configuration
const LIVE_REPORT_INTERVAL_MS = 30000; // Auto-analyze live feeds every 30 seconds
const CONFIDENCE_THRESHOLD = 0.60;

interface ExtendedAnimalData extends AnimalData {
  deviceId?: string; // Camera Device ID
  isConfigured: boolean;
  lastAnalysisTime?: number;
  manualBreed?: string;
  manualWeight?: number;
  manualTemp?: number;
}

interface TrackedObject {
  bbox: [number, number, number, number];
  class: string;
  score: number;
}

// Internal Component: Individual Live Animal Feed
const LiveAnimalFeed: React.FC<{
  animal: ExtendedAnimalData;
  viewMode: 'NORMAL' | 'THERMAL' | 'MAP';
  onAnalysisUpdate: (id: string, result: AIAnalysisResult) => void;
  onError: (id: string, error: string) => void;
}> = ({ animal, viewMode, onAnalysisUpdate, onError }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [model, setModel] = useState<any>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const requestRef = useRef<number>();

  // Load TF Model locally for bounding boxes / thermal heatmap
  useEffect(() => {
    const loadModel = async () => {
        try {
            await tf.ready();
            const loaded = await cocoSsd.load({ base: 'lite_mobilenet_v2' });
            setModel(loaded);
        } catch (e) {
            console.error("TF Load Error", e);
        }
    };
    loadModel();
  }, []);

  // Start Camera
  useEffect(() => {
    const startFeed = async () => {
      if (!animal.deviceId) return;

      // Stop previous stream
      if (streamRef.current) {
          streamRef.current.getTracks().forEach(t => t.stop());
      }

      try {
        // Handle "Default" selection
        const constraints: MediaStreamConstraints = {
            video: animal.deviceId === 'default' 
                ? { facingMode: 'environment' }
                : { deviceId: { exact: animal.deviceId } }
        };

        const stream = await navigator.mediaDevices.getUserMedia(constraints);
        streamRef.current = stream;

        if (videoRef.current) {
            videoRef.current.srcObject = stream;
            videoRef.current.play().catch(e => console.error("Play error", e));
        }
      } catch (e) {
        console.error("Failed to start animal feed", e);
        onError(animal.id, "Camera unavailable. Check permissions.");
      }
    };
    startFeed();

    return () => {
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }
    };
  }, [animal.deviceId, animal.id, onError]);

  // Detection & Rendering Loop
  const detectFrame = useCallback(async () => {
    if (!videoRef.current || !canvasRef.current || !model || videoRef.current.readyState !== 4) return;

    const video = videoRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    if (canvas.width !== video.videoWidth) {
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
    }

    // Detect objects
    const predictions = await model.detect(video);
    const validPredictions: TrackedObject[] = predictions.filter((p: any) => 
        ['cow', 'sheep', 'horse', 'dog', 'cat', 'bear', 'bird'].includes(p.class) && 
        p.score > CONFIDENCE_THRESHOLD
    );

    // Clear Canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw Overlays
    validPredictions.forEach(pred => {
        const [x, y, w, h] = pred.bbox;

        if (viewMode === 'THERMAL') {
            // Draw Heatmap Blob
            const centerX = x + w / 2;
            const centerY = y + h / 2;
            const radius = Math.max(w, h) * 0.8;

            // Create radial gradient for "heat"
            const gradient = ctx.createRadialGradient(centerX, centerY, 10, centerX, centerY, radius);
            gradient.addColorStop(0, 'rgba(255, 0, 0, 0.8)');   // Hot center (Red)
            gradient.addColorStop(0.4, 'rgba(255, 165, 0, 0.6)'); // Warm mid (Orange)
            gradient.addColorStop(0.7, 'rgba(255, 255, 0, 0.3)'); // Cool edge (Yellow)
            gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');      // Cold transparent

            ctx.fillStyle = gradient;
            ctx.fillRect(x - w, y - h, w * 3, h * 3); // Draw slightly larger than box for glow effect

            // Add temp text
            ctx.fillStyle = '#fff';
            ctx.font = 'bold 12px monospace';
            const simulatedTemp = (37 + Math.random()).toFixed(1); // Simulating based on detection
            ctx.fillText(`${simulatedTemp}°C`, x, y - 5);

        } else {
            // Normal Bounding Box
            ctx.strokeStyle = '#10b981';
            ctx.lineWidth = 2;
            ctx.strokeRect(x, y, w, h);

            // Label
            ctx.fillStyle = '#10b981';
            const label = `${pred.class.toUpperCase()} ${Math.round(pred.score * 100)}%`;
            const textWidth = ctx.measureText(label).width;
            ctx.fillRect(x, y - 20, textWidth + 10, 20);

            ctx.fillStyle = '#fff';
            ctx.font = 'bold 11px Inter';
            ctx.fillText(label, x + 5, y - 6);
        }
    });

    // If Thermal Mode, overlay a blue tint on the whole canvas (using composite mode to keep heat spots bright)
    if (viewMode === 'THERMAL') {
        ctx.globalCompositeOperation = 'destination-over';
        ctx.fillStyle = 'rgba(0, 20, 80, 0.6)'; // Deep blue cold background
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.globalCompositeOperation = 'source-over';
    }

  }, [model, viewMode]);

  useEffect(() => {
    let animationId: number;
    const loop = async () => {
        await detectFrame();
        animationId = requestAnimationFrame(loop);
    };
    loop();
    return () => cancelAnimationFrame(animationId);
  }, [detectFrame]);

  // Auto-Analysis Interval (Gemini)
  useEffect(() => {
    const captureAndAnalyze = async () => {
        if (!videoRef.current || !canvasRef.current || videoRef.current.paused || videoRef.current.ended) return;

        setIsScanning(true);
        try {
            // Use a temporary canvas to capture the raw video frame (without overlays)
            const tempCanvas = document.createElement('canvas');
            tempCanvas.width = videoRef.current.videoWidth;
            tempCanvas.height = videoRef.current.videoHeight;
            const ctx = tempCanvas.getContext('2d');
            ctx?.drawImage(videoRef.current, 0, 0);

            const base64 = tempCanvas.toDataURL('image/jpeg', 0.8).split(',')[1];

            // Analyze with Gemini
            const result = await analyzeLivestockFrame(base64);
            onAnalysisUpdate(animal.id, result);
        } catch (e) {
            console.warn("Auto-analysis failed", e);
        } finally {
            setIsScanning(false);
        }
    };

    // Initial scan after delay
    const initialTimer = setTimeout(captureAndAnalyze, 3000);
    // Periodic scan
    const interval = setInterval(captureAndAnalyze, LIVE_REPORT_INTERVAL_MS);

    return () => {
        clearTimeout(initialTimer);
        clearInterval(interval);
    };
  }, [animal.id, onAnalysisUpdate]);

  return (
    <div className="relative w-full h-full bg-black flex items-center justify-center overflow-hidden">
        {/* CSS Filter for Thermal Effect on the video element itself */}
        <video 
            ref={videoRef} 
            autoPlay 
            muted 
            playsInline 
            className="w-full h-full object-cover" 
            style={{ 
                filter: viewMode === 'THERMAL' ? 'grayscale(100%) contrast(1.2) brightness(0.8)' : 'none' 
            }}
        />

        {/* Canvas for Overlays (Heatmap / Bounding Boxes) */}
        <canvas 
            ref={canvasRef} 
            className="absolute inset-0 w-full h-full object-cover pointer-events-none" 
            style={{ mixBlendMode: viewMode === 'THERMAL' ? 'screen' : 'normal' }}
        />

        {/* Live Status Badge */}
        <div className="absolute top-2 left-2 flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-red-500/80 text-white backdrop-blur-sm z-10">
            <div className="w-1.5 h-1.5 rounded-full bg-white animate-pulse" />
            <span className="text-[10px] font-bold tracking-wide uppercase">Live</span>
        </div>

        {/* Scanning Indicator */}
        {isScanning && (
            <div className="absolute top-2 right-2 flex items-center gap-1 px-2 py-1 rounded-md bg-black/60 text-white backdrop-blur-sm z-10">
                <Loader2 size={12} className="animate-spin text-emerald-400" />
                <span className="text-[10px] font-medium">AI Analysis...</span>
            </div>
        )}
    </div>
  );
};

export const LivestockDashboard: React.FC = () => {
  const { addNotification } = useNotifications();
  const { t } = useLanguage();

  // -- State --
  const [animals, setAnimals] = useState<ExtendedAnimalData[]>([]);
  const [videoDevices, setVideoDevices] = useState<MediaDeviceInfo[]>([]);

  // UI State
  const [viewMode, setViewMode] = useState<'NORMAL' | 'THERMAL' | 'MAP'>('NORMAL');
  const [analysisResults, setAnalysisResults] = useState<Record<string, AIAnalysisResult>>({});
  const [refreshDevicesTrigger, setRefreshDevicesTrigger] = useState(0);

  // Configuration Modal
  const [configuringId, setConfiguringId] = useState<string | null>(null);
  const [configForm, setConfigForm] = useState({
      name: '',
      deviceId: '',
      weight: 0,
      temp: 0,
      breed: ''
  });

  // Map Refs
  const mapCanvasRef = useRef<HTMLCanvasElement>(null);
  const FARM_CENTER = { lat: 36.7378, lng: -119.7871 };
  const MAP_ZOOM_FACTOR = 10000;

  // -- Initialization --
  useEffect(() => {
    // Load devices
    const getDevices = async () => {
        try {
            // Need to ask for permission to get labels
            await navigator.mediaDevices.getUserMedia({ video: true }); 
            const devices = await navigator.mediaDevices.enumerateDevices();
            const cameras = devices.filter(d => d.kind === 'videoinput');
            setVideoDevices(cameras);
        } catch (e) {
            console.warn("Could not list video devices or permission denied", e);
            // Even if failed, we can offer 'default'
            setVideoDevices([]);
        }
    };
    getDevices();

    // Load saved slots
    const saved = localStorage.getItem('livestock_slots');
    if (saved) {
        try {
            setAnimals(JSON.parse(saved));
        } catch (e) {
            console.error("Failed to load slots", e);
        }
    }
  }, [refreshDevicesTrigger]);

  // Save slots on change
  useEffect(() => {
      localStorage.setItem('livestock_slots', JSON.stringify(animals));
  }, [animals]);

  // -- Handlers --

  const handleAddSlot = () => {
      const newSlot: ExtendedAnimalData = {
          id: Date.now().toString(),
          tagId: 'New Slot',
          species: 'Unknown',
          ageMonths: 0,
          weightKg: 0,
          temperature: 0,
          activityLevel: 'Resting',
          healthScore: 0,
          status: HealthStatus.UNKNOWN,
          lastCheckup: new Date().toISOString(),
          location: { lat: FARM_CENTER.lat + (Math.random() - 0.5) * 0.002, lng: FARM_CENTER.lng + (Math.random() - 0.5) * 0.002 },
          locationHistory: [],
          isConfigured: false
      };
      setAnimals(prev => [...prev, newSlot]);
  };

  const handleDeleteSlot = (id: string) => {
      if (confirm("Are you sure you want to remove this camera slot?")) {
        setAnimals(prev => prev.filter(a => a.id !== id));
        addNotification({ title: 'Slot Removed', message: 'Camera slot deleted.', type: 'INFO' });
      }
  };

  const openConfig = (animal: ExtendedAnimalData) => {
      setConfiguringId(animal.id);
      setConfigForm({
          name: animal.tagId === 'New Slot' ? '' : animal.tagId,
          deviceId: animal.deviceId || '',
          weight: animal.manualWeight || 0,
          temp: animal.manualTemp || 38.0,
          breed: animal.manualBreed || ''
      });
      // Trigger device refresh when opening config to ensure latest list
      setRefreshDevicesTrigger(prev => prev + 1);
  };

  const saveConfig = () => {
      if (!configuringId) return;

      setAnimals(prev => prev.map(a => {
          if (a.id === configuringId) {
              return {
                  ...a,
                  tagId: configForm.name || 'Unnamed',
                  deviceId: configForm.deviceId,
                  manualWeight: configForm.weight,
                  manualTemp: configForm.temp,
                  manualBreed: configForm.breed,
                  // If we have manual data, use it as baseline
                  weightKg: configForm.weight,
                  temperature: configForm.temp,
                  breed: configForm.breed,
                  isConfigured: !!configForm.deviceId,
                  status: HealthStatus.UNKNOWN 
              };
          }
          return a;
      }));
      setConfiguringId(null);
      addNotification({ title: 'Slot Configured', message: 'Camera and metadata updated.', type: 'SUCCESS' });
  };

  const handleLiveAnalysisUpdate = (id: string, result: AIAnalysisResult) => {
     setAnalysisResults(prev => ({ ...prev, [id]: result }));

     // Update the animal state with AI derived data
     setAnimals(prev => prev.map(a => {
         if (a.id === id) {
             let newStatus = HealthStatus.HEALTHY;
             if (result.condition.toLowerCase().includes('warning')) newStatus = HealthStatus.WARNING;
             if (result.condition.toLowerCase().includes('critical')) newStatus = HealthStatus.CRITICAL;

             // Extract species/breed from AI if valid
             let derivedBreed = a.manualBreed;
             if (result.detectedSubject && result.detectedSubject !== 'Unknown Animal' && result.confidence > 70) {
                 derivedBreed = result.detectedSubject; // e.g. "Holstein Cow"
             }

             return {
                 ...a,
                 status: newStatus,
                 healthScore: result.confidence,
                 breed: derivedBreed, 
                 activityLevel: 'Grazing', // Placeholder, could extract from result.rawAnalysis text
                 lastAnalysisTime: Date.now()
             };
         }
         return a;
     }));
  };

  const handleFeedError = (id: string, error: string) => {
     addNotification({ title: 'Camera Error', message: error, type: 'WARNING' });
  };

  const handleExportData = () => {
    const dataToExport = animals.map(a => ({
        Tag: a.tagId,
        Breed: a.breed || a.species,
        Weight: a.weightKg,
        Temp: a.temperature,
        Location: `${a.location?.lat.toFixed(5)}, ${a.location?.lng.toFixed(5)}`,
        Status: a.status,
        Timestamp: new Date().toISOString()
    }));
    ExportService.exportToCSV(dataToExport, 'livestock_metrics_live.csv');
  };

  // -- Render Map --
  useEffect(() => {
      if (viewMode !== 'MAP' || !mapCanvasRef.current) return;

      const canvas = mapCanvasRef.current;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      canvas.width = 800;
      canvas.height = 450;

      // Draw Background
      ctx.fillStyle = '#0f172a';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Grid
      ctx.strokeStyle = '#1e293b';
      ctx.lineWidth = 1;
      for (let i = 0; i < canvas.width; i += 50) { ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, canvas.height); ctx.stroke(); }
      for (let i = 0; i < canvas.height; i += 50) { ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(canvas.width, i); ctx.stroke(); }

      // Draw Animals (Only Configured)
      animals.forEach(animal => {
          if (!animal.isConfigured) return;

          const x = canvas.width / 2 + (animal.location.lng - FARM_CENTER.lng) * MAP_ZOOM_FACTOR;
          const y = canvas.height / 2 - (animal.location.lat - FARM_CENTER.lat) * MAP_ZOOM_FACTOR;

          ctx.beginPath();
          ctx.arc(x, y, 6, 0, 2 * Math.PI);
          ctx.fillStyle = animal.status === HealthStatus.HEALTHY ? '#10b981' : animal.status === HealthStatus.UNKNOWN ? '#94a3b8' : '#f59e0b';
          ctx.shadowBlur = 10;
          ctx.shadowColor = ctx.fillStyle;
          ctx.fill();
          ctx.shadowBlur = 0;

          ctx.strokeStyle = '#fff';
          ctx.lineWidth = 2;
          ctx.stroke();

          ctx.fillStyle = '#e2e8f0';
          ctx.font = 'bold 11px Inter';
          ctx.fillText(animal.tagId, x + 10, y + 4);
      });

      // HQ Center
      const cx = canvas.width / 2;
      const cy = canvas.height / 2;
      ctx.fillStyle = '#3b82f6';
      ctx.beginPath(); ctx.arc(cx, cy, 8, 0, 2 * Math.PI); ctx.fill();
      ctx.fillStyle = '#fff';
      ctx.textAlign = 'center';
      ctx.fillText("HQ", cx, cy + 20);

  }, [viewMode, animals]);

  // Derived Stats
  const activeCount = animals.filter(a => a.isConfigured && a.deviceId).length;
  const alertCount = animals.filter(a => a.status === HealthStatus.WARNING || a.status === HealthStatus.CRITICAL).length;

  const healthData = useMemo(() => {
     return animals
        .filter(a => a.isConfigured)
        .map(a => ({ name: a.tagId, score: a.healthScore }));
  }, [animals]);

  return (
    <div className="space-y-6 relative pb-20">

      {/* Configuration Modal */}
      {configuringId && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-md overflow-hidden">
                <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-900 text-white">
                    <h3 className="font-bold flex items-center gap-2">
                        <Settings size={18} /> Configure Slot
                    </h3>
                    <button onClick={() => setConfiguringId(null)}><X size={20} /></button>
                </div>
                <div className="p-6 space-y-4">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Slot Name / Tag ID</label>
                        <input 
                            type="text" 
                            className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-emerald-500 outline-none"
                            placeholder="e.g. COW-101"
                            value={configForm.name}
                            onChange={e => setConfigForm({...configForm, name: e.target.value})}
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Camera Source</label>
                        <select 
                            className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-emerald-500 outline-none"
                            value={configForm.deviceId}
                            onChange={e => setConfigForm({...configForm, deviceId: e.target.value})}
                        >
                            <option value="">-- Select Camera --</option>
                            <option value="default">Default System Camera</option>
                            {videoDevices.map(d => (
                                <option key={d.deviceId} value={d.deviceId}>{d.label || `Camera ${d.deviceId.slice(0,5)}...`}</option>
                            ))}
                        </select>
                        <p className="text-xs text-slate-500 mt-1">
                            {videoDevices.length === 0 ? "No cameras detected. Try 'Default System Camera'." : "Select the feed for this slot."}
                        </p>
                    </div>

                    <div className="p-3 bg-blue-50 rounded-lg border border-blue-100 text-xs text-blue-800">
                        <strong>Note:</strong> Real-time data (Weight, Temp) requires manual entry or sensor integration. The AI will detect health status and behavior from the video.
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 mb-1">Breed (Manual)</label>
                            <input 
                                type="text" 
                                className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-emerald-500 outline-none"
                                placeholder="e.g. Angus"
                                value={configForm.breed}
                                onChange={e => setConfigForm({...configForm, breed: e.target.value})}
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 mb-1">Weight (kg)</label>
                            <input 
                                type="number" 
                                className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-emerald-500 outline-none"
                                placeholder="0"
                                value={configForm.weight}
                                onChange={e => setConfigForm({...configForm, weight: parseFloat(e.target.value) || 0})}
                            />
                        </div>
                    </div>
                    <button 
                        onClick={saveConfig}
                        className="w-full bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-2 rounded-lg transition-colors flex items-center justify-center gap-2"
                    >
                        <Save size={18} /> Save Configuration
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">{t('livestock_monitoring')}</h1>
