             <button onClick={() => setViewMode(viewMode === 'MAP' ? 'NORMAL' : 'MAP')} className={`flex items-center gap-2 px-3 py-2 rounded-lg font-medium transition-colors text-sm ${viewMode === 'MAP' ? 'bg-indigo-600 text-white' : 'bg-white border border-slate-300 text-slate-700'}`}>
