                                    </div>
                                    <p className="text-sm text-indigo-800 font-medium">{analysisResults[animal.id].condition}</p>
                                    <p className="text-xs text-indigo-600 mt-1">{analysisResults[animal.id].issues[0] || 'Monitoring...'}</p>
