                            <p className="text-sm text-slate-500 dark:text-slate-400">Connect your own backend API (PostgreSQL/MongoDB via REST)</p>
                        </div>
                    </div>
                    <div className="flex items-center gap-2">
                         {dbConfig.apiUrl ? (
