                mid: '#f3f4f6', // Gray/White
                high: '#15803d', // Dark Green
                bg: '#15803d',
                gradient: 'from-red-700 via-gray-100 to-green-700',
                labels: ['Dead/Soil', 'Mix', 'Lush']
            };
        case 'RG': 
        default: 
            return { 
